import type { Chapter } from '../types'

export const PART: Chapter[] = [{"n":1,"title":"不要早死","intro":"本节只收外因死亡、少数证据最硬的疫苗与筛查，以及出现了就该去查的身体信号。收益一栏的数字来自随机试验、大型队列或官方统计，成本一栏是作者按市价的粗估，只用于比较，不作引用。","entries":[{"id":"1.1","sec":1,"n":1,"title":"系安全带，前排后排都系","cost":"0 元，每次上车 2 秒","human":"前排系上安全带，出车祸时被撞死的概率大约降一半（轻型卡车降六成）。美国 2022 年死在车里的乘员，能查到系带情况的有一半没系。","gain":"美国 NHTSA 估计安全带使轿车前排乘员致死伤害风险下降 45%，轻型卡车前排下降 60%；2022 年美国死亡的乘用车乘员中，已知系带情况者有 50% 未系；WHO 口径为车内人员死亡风险最多降低 50%。WHO 估计中国 2021 年道路交通死亡 248,099 人（17.4/10 万）","grade":"A","src":"NHTSA (2024). Occupant Protection in Passenger Vehicles: 2022 Data (DOT HS 813 573). <https://crashstats.nhtsa.dot.gov/Api/Public/ViewPublication/813573> ; WHO (2025). Road traffic injuries fact sheet. <https://www.who.int/news-room/fact-sheets/detail/road-traffic-injuries> ; WHO GHO RS_196/RS_198 (China, 2021). <https://ghoapi.azureedge.net/api/RS_196?$filter=SpatialDim%20eq%20%27CHN%27>","note":"NHTSA 的 45%/60% 是基于美国事故数据库的官方估计（引 Kahane 2015），不是随机试验。后排不系同样致命，NHTSA 同一报告中第二排被撞死者 60% 未系带。WHO 的中国死亡数是模型估计，比公安交管登记口径高出数倍，两者定义不同，这里只用 WHO 口径。","money":"0","time":"少","will":"否","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"极高"},{"id":"1.2","sec":1,"n":2,"title":"骑摩托车、电动自行车戴头盔并扣好","cost":"100 到 300 元买一顶，每次戴 5 秒","human":"戴头盔并且把扣子扣好，摩托车骑手出事时死亡的概率低约四成，头部受伤低约七成。扣带要系紧，松垮垮挂着不算戴。","gain":"Cochrane 荟萃分析：摩托车骑行者戴头盔使死亡风险下降 42%（OR 0.58，95% CI 0.50 到 0.68），头部损伤下降 69%（OR 0.31，95% CI 0.25 到 0.38）","grade":"A","src":"Liu BC 等 (2008). Helmets for preventing injury in motorcycle riders. Cochrane Database of Systematic Reviews. <https://doi.org/10.1002/14651858.CD004333.pub3>","note":"数据来自摩托车，电动自行车是外推，但受伤机制一样。头盔要扣好扣带，挂在车把上不算。","money":"少","time":"少","will":"否","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"高"},{"id":"1.3","sec":1,"n":3,"title":"装烟雾报警器；冬天在室内烧煤、用燃气取暖的再装一氧化碳报警器","cost":"烟雾报警器 30 到 100 元一个，一氧化碳报警器 50 到 150 元一个，装完每年换一次电池","human":"一个能正常工作的烟雾报警器，能把住宅火灾里死亡的概率降约六成——起火时有四成人在睡觉，靠鼻子是醒不过来的。冬天在屋里烧煤或用燃气的再加一个一氧化碳报警器：仅 2018 年中国就有 1.15 万人死于一氧化碳中毒，冬季那三个月有七成死在家里。","gain":"北卡罗来纳州住宅火灾病例对照研究：可工作的烟雾报警器使死亡风险下降（OR 0.39，95% CI 0.18 到 0.83）。美国 2018 到 2020 年有人居住的住宅致死火灾中 24% 没有烟雾报警器，41% 起火时人在睡觉。中国 2018 年报告一氧化碳中毒死亡 11,523 例，12 月、1 月、2 月死亡有 72.59%、67.42%、66.48% 发生在家中","grade":"B","src":"Marshall SW 等 (1998). Fatal residential fires: who dies and who survives? JAMA. <https://doi.org/10.1001/jama.279.20.1633> ; USFA (2022). Fatal Fires in Residential Buildings (2018-2020), Topical Fire Report Series 22(2). <https://www.usfa.fema.gov/downloads/pdf/statistics/v22i2.pdf> ; You J 等 (2020). Number of Deaths due to Carbon Monoxide Poisoning by Month and by Place of Death — China, 2018. China CDC Weekly. <https://doi.org/10.46234/ccdcw2020.008>","note":"烟雾报警器对死亡率的证据是单个病例对照研究，没有随机试验，所以只给 B。一氧化碳报警器本身没有死亡率研究，收益按「中毒死亡集中在冬季家中」推断。","money":"少","time":"少","will":"否","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"高"},{"id":"1.4","sec":1,"n":4,"title":"燃气软管和灶具到期就换，不自己改管道，燃气公司上门推销可以直接拒绝","cost":"一根合规燃气软管几十元，灶具几年一换；换的时候顺手看一眼有没有过期","human":"一根合规软管几十块，到期就换是条例写明的用户义务；自己改管道、拆燃气表则是明令禁止的。同一部条例还写了燃气公司不得要求你买它指定的产品或服务，所以上门推销「必须换」的可以直接拒绝。","gain":"条例把「及时更换国家明令淘汰或者使用年限已届满的燃气燃烧器具、连接管」写成用户义务，把「擅自安装、改装、拆除户内燃气设施和燃气计量装置」列为禁止行为；同时明确燃气经营者不得要求用户购买其指定的产品或者接受其提供的服务","grade":"A","src":"国务院 (2010). 城镇燃气管理条例（国务院令第 583 号）第二十七条：「燃气用户应当遵守安全用气规则，使用合格的燃气燃烧器具和气瓶，及时更换国家明令淘汰或者使用年限已届满的燃气燃烧器具、连接管等」；第二十八条禁止行为含「（一）擅自操作公用燃气阀门」「（二）将燃气管道作为负重支架或者接地引线」「（四）擅自安装、改装、拆除户内燃气设施和燃气计量装置」；第二十条燃气经营者不得「（六）要求燃气用户购买其指定的产品或者接受其提供的服务」；第二十九条用户可就收费、服务向燃气管理等部门投诉，「有关部门应当自收到投诉之日起15个工作日内予以处理」. <http://www.gov.cn/gongbao/content/2010/content_1758214.htm>","note":"以「安检」名义上门、检查完就推销自闭阀和报警器的，条例第二十条第六项直接堵掉了这条路，可以拒绝并投诉。TODO（待核实：闻到燃气味之后的标准处置步骤——开窗、关阀、不开关任何电器、到室外打电话——本次未取得可逐字核对的官方原文）。一氧化碳中毒是另一件事，见第 13 节。","money":"少","time":"少","will":"否","level":"大","lens":"死亡率","dispute":false,"todo":true,"ratio":"高"},{"id":"1.5","sec":1,"n":5,"title":"不采、不买、不吃野生蘑菇，任何「土办法鉴别」都不成立","cost":"0 元；代价是放弃一种季节性的野味","human":"光 2025 年一年，全国就有 828 起蘑菇中毒、2165 人中招、13 人死；那一年还新鉴定出 34 种以前没记录过会毒人的蘑菇。所谓银针试毒、虫子吃过就没毒、颜色鲜艳才有毒，全都不成立。","gain":"中国疾控中心 2025 年调查了 828 起蘑菇中毒事件，涉及 2165 人、死亡 13 人，病死率 0.6%；2019 到 2024 年每年 276 到 676 起，病死率在 0.87% 到 2.86% 之间。仅 2025 年就鉴定出 138 种有毒蘑菇，其中 34 种是国内首次记录到引起中毒","grade":"A","src":"Mushroom Poisoning Outbreaks — China, 2025. China CDC Weekly (2026)：「In 2025, China CDC investigated 828 mushroom poisoning incidents across 27 provincial-level administrative divisions (PLADs), affecting 2,165 individuals and causing 13 deaths - a case fatality rate of 0.6%, the lowest of the past six years. In total, 138 poisonous mushroom species were identified, including 34 newly recorded in poisoning incidents in China.」「From 2019 to 2024, the annual number of incidents ranged from 276 to 676, and the case fatality rate ranged from 0.87% to 2.86%.」<https://doi.org/10.46234/ccdcw2026.120>；同刊 2024 年度报告 <https://doi.org/10.46234/ccdcw2025.106>","note":"每年都有新种类被记录到中毒，说明「本地人认得清」这个前提本身站不住。银针验毒、和大蒜同煮、虫子吃过就没毒、颜色鲜艳才有毒，全都不成立。误食后立刻催吐并带上剩余蘑菇或照片去医院——毒蘑菇中毒有好几种临床类型，鉴定种类直接决定怎么治。","money":"0","time":"少","will":"些","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"高"},{"id":"1.6","sec":1,"n":6,"title":"电动自行车不推进楼道、不进电梯、不在家里充电","cost":"0 元；停到楼下集中充电点，多走几十米","human":"电动车推进楼道、电梯或者在家充电，是规章明令禁止的，不改正个人罚 500–1000 元，经营性的罚 2000–10000 元。罚款只是次要的，主要是这类火灾正好堵在你唯一的逃生通道上。","gain":"应急管理部部门规章明文禁止：「禁止在高层民用建筑公共门厅、疏散走道、楼梯间、安全出口停放电动自行车或者为电动自行车充电」；拒不改正的，非经营性单位和个人罚 500 至 1000 元，经营性的罚 2000 至 10000 元","grade":"A","src":"应急管理部 (2021). 高层民用建筑消防安全管理规定（应急管理部令第 5 号，第三十七条、第四十七条）. <https://www.gov.cn/zhengce/zhengceku/2021-08/01/content_5628815.htm>","note":"锂电池起火是几十秒内的轰燃加剧毒烟，堵在楼道就是把唯一的逃生通道点着。别买改装电池和杂牌充电器，别整夜充电。TODO（待核实：全国电动自行车火灾起数与死亡人数的官方年度数字）","money":"0","time":"少","will":"些","level":"大","lens":"死亡率","dispute":false,"todo":true,"ratio":"高"},{"id":"1.7","sec":1,"n":7,"title":"量血压，高了就吃药降到达标","cost":"电子血压计 100 到 200 元，一次 1 分钟；降压药多数每月几元到几十元","human":"血压每降 10 mmHg，出大的心血管事件的概率降两成，中风降 27%，心衰降 28%，死亡概率降 13%。中国 35–75 岁的人里 44.7% 有高血压，真正控制住的只有 7.2%。","gain":"荟萃分析（123 项试验，61 万余人）：收缩压每降 10 mmHg，主要心血管事件 RR 0.80（95% CI 0.77 到 0.83），卒中 RR 0.73，心力衰竭 RR 0.72，总死亡率 下降 13%（RR 0.87，95% CI 0.84 到 0.91）。中国 35 到 75 岁 170 万人筛查：44.7% 有高血压，其中知晓 44.7%、治疗 30.1%、控制 7.2%","grade":"A","src":"Ettehad D 等 (2016). Blood pressure lowering for prevention of cardiovascular disease and death: a systematic review and meta-analysis. Lancet. <https://doi.org/10.1016/S0140-6736(15)01225-8> ; Lu J 等 (2017). Prevalence, awareness, treatment, and control of hypertension in China (China PEACE Million Persons Project). Lancet. <https://doi.org/10.1016/S0140-6736(17)32478-9>","note":"降压目标值（130 还是 140）仍有讨论，但「知道自己高血压并把它降下来」本身没有争议。中国 10 个高血压里只有不到 1 个控制住，量一次血压是这本书里性价比最高的动作之一。","money":"少","time":"少","will":"些","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"高"},{"id":"1.8","sec":1,"n":8,"title":"35 岁以后只要超重，就去查一次空腹血糖，正常也每三年再查","cost":"空腹血糖十几元，糖化血红蛋白几十元；抽一次血","human":"花几十块抽一管血，就能在一点症状都没有的时候查出糖尿病前期。美国官方的筛查建议是给 35–70 岁超重或肥胖的人查，查着正常的每三年再查一次。","gain":"美国预防服务工作组现行建议：对 35 到 70 岁、超重或肥胖（体重指数分别 ≥25 和 ≥30）的无症状成年人筛查糖尿病前期和 2 型糖尿病，推荐等级 B；「对血糖正常的成年人，每 3 年筛查一次是合理的做法」","grade":"A","src":"US Preventive Services Task Force (2021). Screening for Prediabetes and Type 2 Diabetes. <https://www.uspreventiveservicestaskforce.org/uspstf/recommendation/screening-for-prediabetes-and-type-2-diabetes>","note":"查出糖尿病前期不等于要吃药，生活方式干预就能让相当一部分人逆转。中国成人糖尿病知晓率长期偏低，很多人是等到并发症才发现","money":"少","time":"少","will":"否","level":"中","lens":"死亡率","dispute":false,"todo":false,"ratio":"一般"},{"id":"1.9","sec":1,"n":9,"title":"开车不超速、不酒驾","cost":"0 元，多花几分钟车程，饭局上少喝","human":"平均车速每高 1%，撞死人的概率高约 4%。酒精没有「喝一点没事」的安全线，血液浓度很低时风险就开始往上走。","gain":"WHO：平均车速每升高 1%，致死事故风险升高 4%；酒驾风险从很低的血液酒精浓度就开始上升","grade":"B","src":"WHO (2025). Road traffic injuries fact sheet. <https://www.who.int/news-room/fact-sheets/detail/road-traffic-injuries>","note":"速度与死亡的 1%/4% 来自事故模型的估计，不是随机试验。酒驾 WHO 只给了定性结论，具体剂量效应本节未核实原始文献。","money":"0","time":"少","will":"些","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"高"},{"id":"1.10","sec":1,"n":10,"title":"给 4 岁以下儿童用安全座椅，不要抱在怀里","cost":"300 到 2000 元一个，能用几年，每次多花 1 分钟","human":"一岁以下的婴儿坐安全座椅，车祸里受致命伤的概率低约七成，1–4 岁低约一半。抱在怀里没有这个效果，急刹时你也抱不住。","gain":"美国 NHTSA 估计安全座椅使轿车内 1 岁以下婴儿致死伤害风险下降 71%，1 到 4 岁幼儿下降 54%；WHO 口径为婴儿死亡下降 71%","grade":"A","src":"NHTSA (2024). Occupant Protection in Passenger Vehicles: 2022 Data (DOT HS 813 573). <https://crashstats.nhtsa.dot.gov/Api/Public/ViewPublication/813573> ; WHO (2025). Road traffic injuries fact sheet. <https://www.who.int/news-room/fact-sheets/detail/road-traffic-injuries>","note":"数字是美国官方基于事故数据的估计。安全座椅装错等于没装，按说明书固定，1 岁以下反向安装。","money":"多","time":"少","will":"否","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"高"},{"id":"1.11","sec":1,"n":11,"title":"家里有小孩就给窗户和阳台装限位器，纱窗不算防护","cost":"一副窗户限位器或儿童安全锁几十元，装十分钟","human":"几十块钱一副限位器。纽约市给高风险住户免费装窗户护栏并上门讲解之后，一个区上报的儿童坠落数三年内降了一半，后来干脆立法要求房东给住着小孩的房子装护栏。纱窗一推就开，不算防护。","gain":"纽约市 1972 年起的「孩子不会飞」项目在高风险区免费发放窗户护栏并入户宣教，布朗克斯区报告的坠落数 1973 到 1975 年下降 50%；此后纽约市修改卫生法典，强制房东为住有 10 岁及以下儿童的公寓安装窗户护栏","grade":"B","src":"Spiegel CN, Lindaman FC (1977). Children can't fly: a program to prevent childhood morbidity and mortality from window falls. American Journal of Public Health：「Significant reduction in falls resulted, particularly in the Bronx, where reported falls declined 50 percent from 1973 to 1975」，1976 年纽约市卫生法典修订「to require that landlords provide window guards in apartments where children ten years old and younger reside」. <https://doi.org/10.2105/AJPH.67.12.1143>；(2021). Unintentional Window Falls in Children and Adolescents. Academic Pediatrics：2007 年 1 月至 2017 年 8 月全国电子伤害监测系统 38,840 例急诊就诊，「The majority of falls occurred in children under the age of 6 and were related to falls from a second story or below」. <https://doi.org/10.1016/j.acap.2020.07.008>","note":"不是只有高层才要装：美国那份数据里多数坠落发生在二层或更低。纱窗只挡蚊子，一推就掉，别把它当护栏。窗边和阳台边不要放床、沙发、箱子这类小孩能爬的东西。","money":"少","time":"少","will":"否","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"高"},{"id":"1.12","sec":1,"n":12,"title":"儿童近水不离视线，划船、野泳穿救生衣","cost":"救生衣 50 到 200 元；看护孩子的注意力","human":"落水时穿着救生衣的人，淹死的概率大约只有不穿的一半。溺水至今是中国 1–14 岁孩子的头号死因，农村的溺水死亡率约为城市的两倍。","gain":"美国海岸警卫队数据配对队列：休闲船只落水者穿救生衣溺亡风险调整 RR 0.51（95% CI 0.35 到 0.74）。中国 20 岁以下溺水死亡率从 2013 年 6.60/10 万降到 2021 年 3.28/10 万，农村约为城市 2 倍，溺水仍是 1 到 14 岁儿童首位死因；2021 年 0 到 19 岁伤害死亡中溺水占 31.1%、道路交通占 27.9%","grade":"A","src":"Cummings P 等 (2011). Association between wearing a personal floatation device and death by drowning among recreational boaters. Injury Prevention. <https://doi.org/10.1136/ip.2010.028688> ; Li Z 等 (2023). Unintentional Drowning Mortality Among Individuals Under Age 20 — China, 2013–2021. China CDC Weekly. <https://doi.org/10.46234/ccdcw2023.198> ; Zhou J 等 (2024). Injury Mortality of Children and Adolescents Aged 0–19 Years — China, 2010–2021. China CDC Weekly. <https://doi.org/10.46234/ccdcw2024.057>","note":"A 级只对应救生衣；「不离视线」是共识（C），没有随机试验也不会有。中国溺水死亡集中在农村、夏季、15 到 19 岁男性。","money":"少","time":"中","will":"否","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"高"},{"id":"1.13","sec":1,"n":13,"title":"60 岁以上练平衡和腿部力量，改造家里的浴室和楼梯","cost":"每周 2 到 3 次各 30 分钟的太极或平衡训练；浴室防滑垫、扶手、夜灯几十到几百元","human":"每周练两三次平衡（太极这类），老人跌倒的次数降约两成三，摔过的人数降 15%；家里做防滑和扶手改造再降约两成。跌倒是中国 65 岁以上因伤害死亡的头号原因，而且一多半就摔在自己家里。","gain":"Cochrane 荟萃分析（108 项试验，23,407 人）：运动使老年人跌倒率下降 23%（RaR 0.77，95% CI 0.71 到 0.83），跌倒人数下降 15%（RR 0.85）；居家安全评估与改造使跌倒率下降（RR 0.81，95% CI 0.68 到 0.97）；太极使跌倒风险 RR 0.71。中国跌倒是 65 岁以上伤害死亡首位原因，2018 年监测的老年人跌倒 55.97% 发生在家中","grade":"A","src":"Sherrington C 等 (2019). Exercise for preventing falls in older people living in the community. Cochrane Database of Systematic Reviews. <https://doi.org/10.1002/14651858.CD012424.pub2> ; Gillespie LD 等 (2012). Interventions for preventing falls in older people living in the community. Cochrane Database of Systematic Reviews. <https://doi.org/10.1002/14651858.CD007146.pub3> ; Lu Z 等 (2021). Characteristics of Falls Among Older People — China, 2018. China CDC Weekly. <https://doi.org/10.46234/ccdcw2021.013>","note":"结局是跌倒次数，不是死亡；跌倒到髋部骨折再到死亡的链条在老年人里很短。适用人群为社区居住的 60 岁以上老人。","money":"少","time":"多","will":"是","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"一般"},{"id":"1.14","sec":1,"n":14,"title":"查乙肝两对半，没有抗体就打疫苗","cost":"检查几十元；成人乙肝疫苗 3 针共约 100 到 300 元，半年打完","human":"查一次几十块。启东那项随访 30 年的试验里，出生就打了乙肝疫苗的人，后来得原发性肝癌的概率低 84%，乙肝携带率低 72%。成人查出没抗体的补三针，半年打完，一两百块。","gain":"启东整群随机试验 30 年随访：新生儿接种乙肝疫苗使原发性肝癌下降 84%（95% CI 23% 到 97%），HBsAg 阳性率下降 72%（95% CI 68% 到 75%）。中国全人群 HBsAg 流行率 1992 到 2014 年下降 52%，5 岁以下下降 97%","grade":"A","src":"Qu C 等 (2014). Efficacy of neonatal HBV vaccination on liver cancer and other liver diseases over 30-year follow-up of the Qidong hepatitis B intervention study. PLoS Medicine. <https://doi.org/10.1371/journal.pmed.1001774> ; Cui F 等 (2017). Prevention of Chronic Hepatitis B after 3 Decades of Escalating Vaccination Policy, China. Emerging Infectious Diseases. <https://doi.org/10.3201/eid2305.161477>","note":"适用人群是 1992 年前出生、没接种过或抗体已消失的成人。肝癌下降的数字来自新生儿接种，同一试验里青少年补种对 HBsAg 的效力只有 21%，成人接种的收益主要是不再感染，不能直接套用 84%。已感染者（HBsAg 阳性）打疫苗无用，要去看肝病科随访。","money":"少","time":"少","will":"否","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"高"},{"id":"1.15","sec":1,"n":15,"title":"被铁钉、木刺扎到或者伤口沾了泥土，当天去处理，顺便问破伤风要不要打","cost":"挂号加处置几十元；需要打的话，疫苗或免疫球蛋白几十到几百元","human":"破伤风一旦发病，大约每 10 个人里死 1 个。深的伤口、沾了泥土的伤口风险最高，当天去处理花不了几十块，别拖到肿起来再说。","gain":"美国的破伤风病例里约每 10 例死 1 例；深的、被泥土污染的伤口风险更高","grade":"B","src":"美国疾病控制与预防中心. 破伤风：「Tetanus bacteria can get into someone's body through broken skin, usually through injuries.」「Tetanus can lead to death (1 in 10 cases in the United States are fatal).」「People who didn't complete the primary series or who aren't up to date with their 10-year tetanus booster shots are also at increased risk.」「Vaccination also helps prevent tetanus in people with wounds, depending on their tetanus vaccination history.」<https://www.cdc.gov/tetanus/about/index.html>；国家卫生健康委办公厅 (2024). 关于印发非新生儿破伤风诊疗规范（2024 年版）的通知（国卫办医急函〔2024〕381 号）. <https://www.gov.cn/zhengce/zhengceku/202410/content_6982262.htm>","note":"不是所有伤口都要打，医生按伤口性质加上一次接种时间决定，所以别自己判断也别拒绝问。「小时候打过就一辈子有效」是错的，加强针按 10 年算。TODO（待核实：中国《非新生儿破伤风诊疗规范（2024 年版）》正文的伤口分级与免疫程序表，附件是 PDF，本机读不了）。","money":"少","time":"少","will":"否","level":"大","lens":"死亡率","dispute":false,"todo":true,"ratio":"高"},{"id":"1.16","sec":1,"n":16,"title":"女性接种 HPV 疫苗，越早越好","cost":"国产二价约 300 多元一针，进口九价约 1300 元一针，2 到 3 针；打针半天","human":"瑞典 167 万女性的数据里，17 岁前打过 HPV 疫苗的人，后来得浸润性宫颈癌的概率只有没打的约八分之一；17–30 岁才打的也只有一半左右。所以越早打越值。","gain":"瑞典 167 万女性队列：接种者浸润性宫颈癌发病率比未接种者低，17 岁前接种 IRR 0.12（95% CI 0.00 到 0.34），17 到 30 岁接种 IRR 0.47（95% CI 0.27 到 0.75）","grade":"A","src":"Lei J 等 (2020). HPV Vaccination and the Risk of Invasive Cervical Cancer. New England Journal of Medicine. <https://doi.org/10.1056/NEJMoa1917338>","note":"9 到 14 岁收益最大，17 到 30 岁仍有一半以上的下降，30 岁后收益递减。接种后仍要做筛查（见下一条）。","money":"多","time":"少","will":"否","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"高"},{"id":"1.17","sec":1,"n":17,"title":"女性 40 岁起做乳腺癌筛查，每两年一次钼靶","cost":"钼靶每次两三百元，很多地区有免费筛查项目；每两年花半天","human":"40 到 74 岁每两年拍一次钼靶，是美国官方筛查建议里明确推荐的做法。75 岁以上，以及给致密乳腺加做超声和磁共振，官方的结论是证据还不够——体检套餐拿这些加价时可以不买。","gain":"美国预防服务工作组现行建议：「建议 40 至 74 岁女性每两年做一次筛查性乳腺 X 线摄影」，推荐等级 B；对 75 岁及以上女性和致密型乳腺的补充超声、磁共振，均判定为「现有证据不足」","grade":"A","src":"US Preventive Services Task Force (2024). Breast Cancer: Screening. <https://www.uspreventiveservicestaskforce.org/uspstf/recommendation/breast-cancer-screening>","note":"起始年龄各国不同，中国部分指南和地方项目从 45 岁起。有一级亲属乳腺癌史、携带 BRCA 突变的属于高危，要单独找医生定方案，不适用本条","money":"少","time":"少","will":"否","level":"中","lens":"死亡率","dispute":false,"todo":false,"ratio":"一般"},{"id":"1.18","sec":1,"n":18,"title":"30 岁以上女性做宫颈癌筛查，优先 HPV 检测","cost":"HPV 检测 100 到 300 元一次，阴性可 5 年一次；取样几分钟","human":"印度农村那项试验里，一辈子只做过一次 HPV 检测的女性，死于宫颈癌的概率低约一半，被查出晚期宫颈癌的概率低约五成。一次一两百块，阴性能管 5 年。","gain":"印度农村整群随机试验（30 到 59 岁女性）：单次 HPV 检测筛查使宫颈癌死亡 HR 0.52（95% CI 0.33 到 0.83），晚期宫颈癌 HR 0.47（95% CI 0.32 到 0.69）","grade":"A","src":"Sankaranarayanan R 等 (2009). HPV screening for cervical cancer in rural India. New England Journal of Medicine. <https://doi.org/10.1056/NEJMoa0808516>","note":"这是少数用死亡作为结局的筛查随机试验，且只筛了一轮。打过 HPV 疫苗也要筛，疫苗不覆盖全部型别。","money":"少","time":"少","will":"否","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"高"},{"id":"1.19","sec":1,"n":19,"title":"45 到 50 岁起做结直肠癌筛查，粪便免疫化学检测或肠镜","cost":"粪便检测几十元，每 1 到 2 年一次；肠镜几百到一千多元，阴性可 10 年一次，需要一天肠道准备","human":"每一两年做一次几十块的粪便隐血检查，死于结直肠癌的概率低约 16%，每轮都不落下的低 25%；被叫去做一次肠镜的那组，往后十年得结直肠癌的概率从 1.20% 降到 0.98%。","gain":"Cochrane 荟萃分析：粪便隐血筛查使结直肠癌死亡 RR 0.84（95% CI 0.78 到 0.90），参加至少一轮者 RR 0.75。NordICC 随机试验：邀请做肠镜使 10 年结直肠癌发病从 1.20% 降到 0.98%（RR 0.82，95% CI 0.70 到 0.93）","grade":"A","src":"Hewitson P 等 (2007). Screening for colorectal cancer using the faecal occult blood test, Hemoccult. Cochrane Database of Systematic Reviews. <https://doi.org/10.1002/14651858.CD001216.pub2> ; Bretthauer M 等 (2022). Effect of Colonoscopy Screening on Risks of Colorectal Cancer and Related Death. New England Journal of Medicine. <https://doi.org/10.1056/NEJMoa2208375>","note":"争议。NordICC 意向筛查分析中结直肠癌死亡 0.28% 对 0.31%（RR 0.90，95% CI 0.64 到 1.16），没有统计学意义，肠镜对死亡率的好处被高估过；粪便检测的死亡率证据反而更硬。起始年龄各国指南在 45 到 50 岁之间，有家族史的更早。","money":"少","time":"中","will":"否","level":"中","lens":"死亡率","dispute":true,"todo":false,"ratio":"一般"},{"id":"1.20","sec":1,"n":20,"title":"有心血管病的人和老年人每年打流感疫苗","cost":"50 到 150 元一针，每年秋天一次","human":"心梗之后打流感疫苗的那项试验里，一年内死亡的比例从 4.9% 降到 2.9%。有心血管病的人和老人每年秋天补一针，50–150 元。","gain":"心肌梗死后随机双盲试验（2571 人）：接种流感疫苗 12 个月 总死亡率 2.9% 对安慰剂 4.9%（HR 0.59，95% CI 0.39 到 0.89），心血管死亡 HR 0.59。荟萃分析：流感疫苗使主要心血管事件 3.6% 对 5.4%（RR 0.66，95% CI 0.53 到 0.83），心血管死亡 RR 0.74（95% CI 0.42 到 1.30，无统计学意义）","grade":"A","src":"Fröbert O 等 (2021). Influenza Vaccination After Myocardial Infarction: A Randomized, Double-Blind, Placebo-Controlled, Multicenter Trial. Circulation. <https://doi.org/10.1161/CIRCULATIONAHA.121.057042> ; Behrouzi B 等 (2022). Association of Influenza Vaccination With Cardiovascular Risk: A Meta-analysis. JAMA Network Open. <https://doi.org/10.1001/jamanetworkopen.2022.8873>","note":"争议。A 级只对应有心血管病的人。对健康老年人，Cochrane 综述（Demicheli V 等 2018，Vaccines for preventing influenza in the elderly，<https://doi.org/10.1002/14651858.CD004876.pub4>）只能给出一季流感发病从 6% 降到 2.4% 的低确定性证据，对死亡率的证据是极低确定性。","money":"少","time":"少","will":"否","level":"大","lens":"死亡率","dispute":true,"todo":false,"ratio":"高"},{"id":"1.21","sec":1,"n":21,"title":"50 岁以后打带状疱疹疫苗","cost":"重组带状疱疹疫苗两针合计约 3000 到 4000 元，自费","human":"三期试验里，这支疫苗把带状疱疹挡掉了 97%，各年龄段都差不多。缺点是两针三四千元全自费，而这笔钱买的是九成七的发病率降幅。","gain":"18 国 1.54 万人的三期随机对照试验，平均随访 3.2 年：疫苗组 6 例、安慰剂组 210 例发生带状疱疹（每千人年 0.3 对 9.1），「疫苗对带状疱疹的总体效力为 97.2%（95% CI 93.7–99.0，P<0.001）」，各年龄组效力在 96.6% 到 97.9% 之间","grade":"A","src":"Lal H, Cunningham AL, Godeaux O, et al. (2015). Efficacy of an adjuvanted herpes zoster subunit vaccine in older adults. New England Journal of Medicine, 372(22), 2087-2096. <https://doi.org/10.1056/NEJMoa1501184>","note":"本条按性价比排在后面是因为贵。带状疱疹本身很少致命，真正麻烦的是带状疱疹后神经痛，可能疼上几个月到几年。疫苗接种后局部疼痛、发热的比例不低（三级症状 17.0% 对 3.2%）","money":"多","time":"少","will":"否","level":"中","lens":"死亡率","dispute":false,"todo":false,"ratio":"一般"},{"id":"1.22","sec":1,"n":22,"title":"65 岁以上打肺炎球菌疫苗","cost":"几百元，部分地区对老年人免费","human":"8.45 万老人的试验里，13 价肺炎球菌疫苗把疫苗覆盖类型的肺炎挡掉约 46%，把最凶险的侵袭性感染挡掉 75%；但对「所有原因的肺炎」没看出效果，别指望它管住所有肺炎。","gain":"荷兰 8.45 万名 65 岁以上老人的随机对照试验：13 价肺炎球菌结合疫苗对疫苗覆盖型肺炎的效力 45.6%（95.2% CI 21.8–62.5），对侵袭性肺炎球菌病 75.0%（95% CI 41.4–90.8）；对全部原因的肺炎无效","grade":"A","src":"Bonten MJ, Huijts SM, Bolkenbaas M, et al. (2015). Polysaccharide conjugate vaccine against pneumococcal pneumonia in adults. New England Journal of Medicine, 372(12), 1114-1125. <https://doi.org/10.1056/NEJMoa1408544>","note":"只防疫苗覆盖的那些型别，不是打了就不得肺炎。中国老年人常用的是 23 价多糖疫苗，与本试验用的 13 价结合疫苗不是同一种，效力数据不能直接套用","money":"少","time":"少","will":"否","level":"中","lens":"死亡率","dispute":false,"todo":false,"ratio":"一般"},{"id":"1.23","sec":1,"n":23,"title":"查幽门螺杆菌，阳性就根除","cost":"碳 13/14 呼气试验 100 到 200 元；四联根除 2 周药费 200 到 500 元","human":"山东临朐随访 22 年的试验里，把幽门螺杆菌根除掉的人，后来得胃癌的概率低约一半，死于胃癌的概率低约四成。查一次一两百块，根除吃两周药。","gain":"山东临朐随机干预试验 22 年随访：幽门螺杆菌根除治疗使胃癌发病 OR 0.48（95% CI 0.32 到 0.71），胃癌死亡 HR 0.62（95% CI 0.39 到 0.99）","grade":"A","src":"Li WQ 等 (2019). Effects of Helicobacter pylori treatment and vitamin and garlic supplementation on gastric cancer incidence and mortality: follow-up of a randomized intervention trial. BMJ. <https://doi.org/10.1136/bmj.l5016>","note":"试验人群是胃癌高发区居民，低发区绝对收益会小得多。根除后可能再感染，家人同查同治。","money":"少","time":"少","will":"些","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"高"},{"id":"1.24","sec":1,"n":24,"title":"重度吸烟者每年做一次低剂量胸部 CT","cost":"200 到 400 元一次，10 分钟；假阳性后的复查和焦虑","human":"符合条件的重度吸烟者每年做一次低剂量 CT，死于肺癌的概率比只拍胸片低 20%，总的死亡概率低 6.7%。代价是假阳性带来的复查和一段时间的提心吊胆。","gain":"美国 NLST 随机试验（53,454 人，55 到 74 岁、吸烟史 30 包年以上、戒烟不超过 15 年）：低剂量 CT 比胸片使肺癌死亡相对下降 20.0%（95% CI 6.8 到 26.7），总死亡率 相对下降 6.7%（95% CI 1.2 到 13.6）","grade":"A","src":"National Lung Screening Trial Research Team (2011). Reduced Lung-Cancer Mortality with Low-Dose Computed Tomographic Screening. New England Journal of Medicine. <https://doi.org/10.1056/NEJMoa1102873>","note":"只适用于高危吸烟者。同一试验中低剂量 CT 组 24.2% 的筛查为阳性，其中 96.4% 是假阳性，不吸烟的人做这项检查是花钱买焦虑。","money":"少","time":"少","will":"否","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"高"},{"id":"1.25","sec":1,"n":25,"title":"抑郁或有自杀念头时打 12356，家里不囤安眠药和农药","cost":"0 元；一个电话，或者把药锁起来、农药不放家里","human":"把致命的手段从手边拿走，这一类做法的证据一直在变强：管住镇痛药以后相关自杀降 43%，跳楼热点装上防护后降 86%。所以家里不囤安眠药和农药。想不开的时候先打 12356，全国通用，每天至少开 18 小时。","gain":"10 年系统综述：限制致死手段的证据持续增强，镇痛药管控相关自杀下降 43%，跳楼热点加防护后下降 86%（79% 到 91%）；校园认知项目使自杀未遂 OR 0.45（95% CI 0.24 到 0.85）；抑郁的药物和心理治疗是预防的重要环节。中国 2025 年 5 月 1 日起全国拨 12356 接通心理援助热线，每日不少于 18 小时","grade":"B","src":"Zalsman G 等 (2016). Suicide prevention strategies revisited: 10-year systematic review. Lancet Psychiatry. <https://doi.org/10.1016/S2215-0366(16)30030-X> ; 国家卫生健康委 (2024). 关于应用\"12356\"全国统一心理援助热线电话号码的通知（国卫医政函〔2024〕259 号）. <https://www.gov.cn/zhengce/zhengceku/202412/content_6994470.htm>","note":"限制手段的证据多为生态学研究（政策前后对比），热线本身没有死亡率证据，所以给 B。自杀冲动往往只持续几分钟到几小时，把致死工具放远一步就是干预——这个时间尺度的数据和未遂之后的长期结局见本节第 30 条，被救回来之后留下什么见本节第 31 条。","money":"0","time":"少","will":"否","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"极高"},{"id":"1.26","sec":1,"n":26,"title":"备齐灭火器、灭火毯、逃生呼吸面罩和急救包，每年检查一次","cost":"灭火器、灭火毯、每人一只呼吸面罩加一个急救包，一套几百元；买一次，之后每年花十分钟检查","human":"灭火器、灭火毯、逃生面罩、急救包，是应急管理部那份 11 样家庭应急清单里的东西，一套几百元买一次。上门做过家庭安全指导的那些研究里，伤害发生率低约四分之一。","gain":"应急管理部《全国基础版家庭应急物资储备建议清单》共 11 样，其中「灭火器和灭火毯」用于「初起火灾的扑救」，「灭火毯可披覆在身上逃生」；「呼吸面罩」指「消防过滤式自救呼吸器，用于火灾逃生使用」；「外用药品」是「止血粉、止血贴、纱布绷带等，用于处理伤口」。98 项研究、2,605,044 人的 Cochrane 综述：家庭安全干预使伤害发生率 IRR 0.89（95% CI 0.78 到 1.01），其中入户开展的干预 IRR 0.75（95% CI 0.62 到 0.91）","grade":"B","src":"应急管理部 (2020). 全国基础版家庭应急物资储备建议清单. <https://www.mem.gov.cn/kp/shaq/202011/t20201129_372149.shtml> ; Kendrick D 等 (2012). Home safety education and provision of safety equipment for injury prevention. Cochrane Database of Systematic Reviews. <https://doi.org/10.1002/14651858.CD005014.pub3> ; 武胜县市场监督管理局 (2025). 手提式灭火器、防火门（窗）、点型感温（烟）火灾探测器消费提示. <https://www.wusheng.gov.cn/gasylbzj/c109568/zzzq/content/content_1988424970198126592.html>","note":"争议。同一份 Cochrane 里不发装备的干预 IRR 0.78（95% CI 0.66 到 0.92），发装备的组并没有做得更好，降低伤害的主要是入户教育和改造，所以装备的收益记「中」不记「大」。买灭火器认准 CCC 标志，贮压式的指针要停在绿区。烟雾报警器和一氧化碳报警器见本节第 3 条，止血带的用法见第 13 节第 11 条，逐项怎么选、放哪里、几年换见 [docs/家庭应急装备清单.md](../docs/家庭应急装备清单.md)","money":"少","time":"少","will":"否","level":"中","lens":"死亡率","dispute":true,"todo":false,"ratio":"一般"},{"id":"1.27","sec":1,"n":27,"title":"尿里出现肉眼看得见的血，哪怕不疼、哪怕第二天就干净了，也要去查一次","cost":"尿常规几十元加泌尿系超声一两百元；医生认为需要时加做膀胱镜，千元上下","human":"60 岁以上的人出现一次肉眼看得见的血尿，最后查出膀胱癌的概率约 2.8%，40–59 岁约 1.2%——不算高，但足够高到必须去查一次。哪怕第二天不出血了也要去查。","gain":"英国初级医疗电子病历的病例对照研究，4915 例膀胱癌对 21718 例对照：肉眼血尿对膀胱癌的阳性预测值，60 岁以上 2.8%（95% CI 2.5 到 3.1），40 到 59 岁 1.2%（0.6 到 2.3）；只有显微镜下看得见的血尿同样有意义，比值比 20（95% CI 12 到 33），60 岁以上阳性预测值 1.6%（1.2 到 2.1）","grade":"B","src":"Price SJ, Shephard EA, Stapley SA, Barraclough K, Hamilton WT (2014). Non-visible versus visible haematuria and bladder cancer risk: a study of electronic records in primary care. British Journal of General Practice, 64(626), e584-e589. <https://doi.org/10.3399/bjgp14X681409>","note":"收益记「小」是因为只有检出率，没有「早查能降低多少死亡」的效应量。「不疼」是关键：结石和感染的血尿多半伴着腰腹绞痛或尿频尿急尿痛，肿瘤引起的往往一点感觉都没有，而且会自己停几天再出现，很多人就此放过。在吃抗凝药不是可以不查的理由。剧烈运动后、女性经期附近的血尿可以先复查一次再定。","money":"少","time":"中","will":"否","level":"小","lens":"死亡率","dispute":false,"todo":false,"ratio":"一般"},{"id":"1.28","sec":1,"n":28,"title":"性行为全程用安全套，不和别人共用针具","cost":"一只一两元；难点不在钱，在每次都用、且从一开始就戴","human":"每一次都全程戴，异性之间传染艾滋病的概率大约降七成以上；「大部分时候戴」的效果，和不戴差不了多少。梅毒、淋病这些也顺带挡住。","gain":"25 项研究、10676 对 HIV 血清不一致异性伴侣的系统综述与荟萃分析：与从不使用者相比，坚持每次使用安全套的人 HIV 传播风险 RR 0.29（95% CI 0.20 至 0.43）；与不规律使用者相比 RR 0.23（95% CI 0.13 至 0.40）。作者结论是安全套虽不完美，「坚持使用可使 HIV 传播降低 70% 以上」。同一层保护还覆盖梅毒、淋病、衣原体等其他性传播感染","grade":"A","src":"Giannou FK, Tsiara CG, Nikolopoulos GK, et al. (2016). Condom effectiveness in reducing heterosexual HIV transmission: a systematic review and meta-analysis of studies on HIV serodiscordant couples. Expert Review of Pharmacoeconomics & Outcomes Research, 16(4), 489-499. <https://doi.org/10.1586/14737167.2016.1102635>","note":"「不规律使用」和「不用」的差距很小，这条的全部效力都在「每次、全程」四个字上。共用针具（包括注射毒品、纹身、穿孔）是另一条独立的高效传播途径，和性行为无关。属于高风险人群的还有暴露前预防（PrEP）这条路：18 项研究的荟萃分析显示，在服药依从性超过 70% 的试验里，口服 PrEP 相比安慰剂的 HIV 感染风险比为 0.30（95% CI 0.21 至 0.45），依从性低的试验则看不到保护效果（Fonner VA 等, 2016, AIDS, <https://doi.org/10.1097/QAD.0000000000001145>）；PrEP 是处方药，去感染科或疾控问，别自己网购。已经暴露之后怎么办见第 13 节","money":"少","time":"少","will":"些","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"高"},{"id":"1.29","sec":1,"n":29,"title":"有过高危行为就去查一次，疾控中心免费、结果保密","cost":"0 元；跑一趟疾控或指定医疗机构，抽一管血","human":"去疾控查艾滋病不花钱，办法明文规定工作人员不得泄露你的姓名、住址和检测结果。查出来也不是判死刑：坚持吃药把病毒压到测不出来的人不会再传给性伴侣——一项随访了七百多对伴侣、七万多次无套性行为的研究里，伴侣之间传染的例数是零。","gain":"《艾滋病防治条例》第二十三条：县级以上地方人民政府卫生主管部门指定的医疗卫生机构，「应当为自愿接受艾滋病咨询、检测的人员免费提供咨询和初筛检测」。查得早的意义不是心理安慰：现在的抗病毒治疗能把病毒压到检测不到，世界卫生组织的口径是「接受抗病毒治疗且病毒载量检测不到的感染者不会把 HIV 传染给性伴侣」——PARTNER 研究随访 782 对同性血清不一致伴侣、1593 对年、共 76088 次无套性行为，出现的 15 例新感染经系统发育分析全部不来自伴侣，即伴侣间传播为零；《全国艾滋病检测工作管理办法》规定艾滋病检测实验室工作人员不得泄露艾滋病病人或感染者的姓名、住址、检测结果等有关情况","grade":"A","src":"卫生部 (2006). 全国艾滋病检测工作管理办法. <https://www.gov.cn/zwgk/2006-06/27/content_320458.htm>；国务院 (2006). 艾滋病防治条例（第三、二十三、三十八条）. <https://wjw.beijing.gov.cn/zwgk_20040/zcwj2022/flfg/202304/t20230408_2992986.html>（北京市卫生健康委员会转载）；Rodger AJ, Cambiano V, Bruun T, et al. (2019). Risk of HIV transmission through condomless sex in serodifferent gay couples with the HIV-positive partner taking suppressive antiretroviral therapy (PARTNER): final results of a multicentre, prospective, observational study. The Lancet, 393(10189), 2428-2438. <https://doi.org/10.1016/S0140-6736(19)30418-0>","note":"窗口期决定什么时候查才算数。广东省疾控中心的口径：核酸检测约 1 周、第四代抗原抗体联合检测约 2 周、第三代抗体检测约 3 周可检出，建议至少 2 周后再查、间隔 2 至 4 周复查，末次高危行为 3 个月后 99.99% 以上可以排除感染（<https://cdcp.gd.gov.cn/jkjy/kpydjwjxz/content/post_3441820.html>）。自测试剂阳性不等于确诊，必须去疾控或正规机构复核。条例第三条写明任何单位和个人不得歧视感染者及其家属，婚姻、就业、就医、入学等权益受法律保护；第三十八条同时规定感染者有义务「将感染或者发病的事实及时告知与其有性关系者」。孕期的三病筛查和母婴阻断见第 27 节","money":"0","time":"少","will":"些","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"高"},{"id":"1.30","sec":1,"n":30,"title":"念头一冒出来先告诉身边的一个人，把这几十分钟交出去","cost":"0 元；难的是当时开口，以及承认自己这几个小时不能一个人待着","human":"82 名自杀未遂者的访谈里，47.6% 说从这次第一次冒出念头到动手不超过 10 分钟——要熬的不是想不通的一生，是几十分钟。同一批人里 76.8% 在这段时间跟人有过接触，机会通常是有的，只是没开口。往后看，90 项随访研究的综述里，因自伤到医院的人 1 年后约 2% 死于自杀、9 年以上约 7%——绝大多数人后来不是这么走的：这阵过去，日子是能接着过的。","gain":"82 名自杀未遂者入院 3 天内的访谈：47.6%（39 人）报告从当次第一次出现自杀念头到实施不超过 10 分钟，过程较长者自杀意图评分显著更高，冲动性量表得分与过程长短无关；76.8%（63 人）报告在此期间与伴侣、家人或朋友有过某种人际接触；作者结论是可干预的时间窗通常很短，专业人员在这一阶段能介入的余地有限，因此要把识别信号和干预办法普及到普通人。90 项随访研究的系统综述：因自伤就诊者 1 年后非致死性重复自伤的中位比例 16%、死于自杀 2%，随访 9 年以上约 7% 死于自杀","grade":"B","src":"Deisenhammer EA, Ing CM, Strauss R, Kemmler G, Hinterhuber H, Weiss EM (2009). The duration of the suicidal process: how much time is left for intervention between consideration and accomplishment of a suicide attempt? Journal of Clinical Psychiatry, 70(1), 19-24. <https://doi.org/10.4088/JCP.07m03904>；Owens D, Horrocks J, House A (2002). Fatal and non-fatal repetition of self-harm: systematic review. British Journal of Psychiatry, 181, 193-199. <https://doi.org/10.1192/bjp.181.3.193>","note":"给 B 的原因：Deisenhammer 只有 82 人、单中心、靠事后回忆自报；Owens 给的是 90 项异质研究的中位比例，不是合并效应量，而且同一篇明确写着自伤者的自杀风险仍是普通人群的几百倍——「绝大多数后来不是这么走的」说的是这批人后来的结局分布，不是对个人的承诺，该看的病还是要看。把致死手段挪远和 12356 见本节第 25 条，情绪低落时先做的几件事见第 3 节第 19 条，救回来之后的后遗症见本节第 31 条，身边人流露出这种念头时你能做什么见第 8 节第 13 条","money":"0","time":"少","will":"些","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"高"},{"id":"1.31","sec":1,"n":31,"title":"别把「救回来」当成兜底：急诊能保住的是命，保不住肺和脑子","cost":"0 元，只是先知道这件事","human":"百草枯没有解毒药，洗胃不该做，血液灌流和透析也改变不了病程；它被主动运进肺里，引起肺炎和肺纤维化，同时伤肾伤肝，所有中心的病死率都很高，孟加拉 10 家三级医院 257 例的病死率是 43.2%。农业农村部 2018 年重申禁令的理由就写在文件里：水剂禁而不绝，服用百草枯自杀的事时有发生。一氧化碳是另一头：两组各 76 人的随机试验里，常压吸氧组六周后 46.1% 留下认知损害，高压氧组 25.0%；另一项 73 人的前瞻研究里 30% 有认知后遗症。也就是说，这条路没有一个干净的结局，更常见的产出是留下来的后遗症。","gain":"百草枯中毒的系统综述：病死率极高，原因是本身毒性强且缺乏有效治疗；它被逆浓度梯度主动摄取进肺组织，导致肺炎和肺纤维化，并造成肾损伤和肝损伤；不应进行洗胃，血液透析和血液灌流不大可能改变临床病程，激素与免疫抑制剂的疗效证据很弱，「所有中心的病死率都很高，尽管治疗差异很大」。孟加拉 10 家三级医院 2013 至 2024 年的 1420 例中可分析的 257 例：病死率 43.2%，常见表现为急性肾衰引起的下肢肿胀 71.2%、呕吐 65.8%、腹痛 58.0%。急性一氧化碳中毒的双盲随机试验（两组各 76 人）：六周时认知后遗症在高压氧组 19/76（25.0%）、常压氧组 35/76（46.1%）（P=0.007），校正后 OR 0.45（95% CI 0.22 至 0.92）；另一项 73 例连续病例的前瞻研究：30% 有认知后遗症，12% 出现脑白质高信号。中国自 2014 年 7 月 1 日起撤销百草枯水剂登记和生产许可、停止生产，2016 年 7 月 1 日停止水剂在国内销售和使用，2020 年 9 月 26 日起禁止可溶胶剂在境内销售、使用，文件写明「致使服用百草枯自杀事件时有发生」是加强监管的直接原因","grade":"B","src":"Gawarammana IB, Buckley NA (2011). Medical management of paraquat ingestion. British Journal of Clinical Pharmacology, 72(5), 745-757. <https://doi.org/10.1111/j.1365-2125.2011.04026.x>；Chowdhury FR 等 (2026). Clinical and Laboratory Profile of Paraquat Poisoning: A Toxicological Crisis in Bangladesh. American Journal of Tropical Medicine and Hygiene, 115, 176-182. <https://doi.org/10.4269/ajtmh.25-0719>；Weaver LK, Hopkins RO, Chan KJ, et al. (2002). Hyperbaric oxygen for acute carbon monoxide poisoning. New England Journal of Medicine, 347(14), 1057-1067. <https://doi.org/10.1056/NEJMoa013121>；Parkinson RB, Hopkins RO, Cleavinger HB, et al. (2002). White matter hyperintensities and neuropsychological outcome following carbon monoxide poisoning. Neurology, 58(10), 1525-1532. <https://doi.org/10.1212/wnl.58.10.1525>；农业农村部办公厅 (2018). 关于切实加强百草枯监督管理的通知（农办农〔2018〕17 号）. <https://www.gov.cn/zhengce/zhengceku/2018-12/31/content_5442594.htm>","note":"给 B 的原因：这几项研究的对象是中毒患者，不是单一的自杀未遂人群（一氧化碳那项试验里也含意外中毒），后遗症比例不能直接当成「自杀未遂者的后果概率」。这条不比较不同方式的致死率，也不给任何具体做法，能确定的只有一句：没有哪一种是干净的。一氧化碳的现场处置见第 13 节第 18 条，误服农药和药物先别催吐、带上瓶子就医见第 13 节第 19 条，家里不囤农药和安眠药见本节第 25 条","money":"0","time":"少","will":"否","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"极高"},{"id":"1.32","sec":1,"n":32,"title":"别拿「躺几天就好」赌高处坠落：进了创伤 ICU 的人多数活下来，代价按年算","cost":"0 元，只是先把这笔账看清","human":"新疆南部一家创伤 ICU 收的 289 例高处坠落，院内或 30 天内死亡的只有 5.5%——绝大多数活了下来，代价是：伤情评分中位数 24，47.1% 同时伤到三个以上部位，36% 上了呼吸机（中位 103.5 小时），ICU 中位住 8 天、最长的住了 132 天。这批人坠落高度的中位数只有 3 米，11.4% 才是从 10 米以上下来。出了 ICU 之后还有长期治疗和康复：伤情评分 25 以上的重伤者，随访下来能回去工作的是 58%。钱这一侧，2024 年全国医院次均住院费用 9870 元——那是一次普通住院的平均数，多次手术加按月算的住院不在这个量级上，而全国卫生总费用里个人自付占 27.5%，差额落在家里人身上。","gain":"新疆南部某创伤 ICU 2020 年 4 月至 2024 年 7 月的 289 例高处坠落（平均年龄 40.3 岁）：坠落高度中位数 3 米，26.6% 从 5 米以上、11.4% 从 10 米以上坠落；ISS 中位数 24，63.3% 的 ISS 大于 20；47.1% 伤及 3 个以上部位，18.3% 伤及 4 个以上；36% 需要机械通气，通气时长中位 103.5 小时；ICU 住院中位 8 天（1 至 132 天）；院内或 30 天死亡率 5.5%（16/289）。德国一家创伤中心 84 例 ISS ≥ 25 的多发伤患者：随访期内重返工作的比例为 58%，年龄、ICU 治疗时长和自评健康是预测因素。2024 年全国医院次均住院费用 9870.0 元（按当年价格比上年下降 4.3%），全国卫生总费用 90895.5 亿元中个人卫生支出 25007.5 亿元、占 27.5%","grade":"B","src":"Chen Y, Li W, Wang X, Zhong Q, Abudurexiti A, Qiu Q, Li J, Luo J (2025). Clinical features and prognostic predictors for patients admitted to trauma intensive care unit due to fall from height in South Xinjiang. International Journal of Emergency Medicine, 18, 142. <https://doi.org/10.1186/s12245-025-00959-4>；Simmel S, Wurm S, Drisch S, Woltmann A, Coenen M (2020). Prädiktion der Rückkehr zur Arbeit nach Polytrauma bei Patienten mit einem ISS von mindestens 25. Die Rehabilitation, 59(2), 95-103. <https://doi.org/10.1055/a-0977-6853>；国家卫生健康委 (2025). 2024 年我国卫生健康事业发展统计公报解读. <https://www.gov.cn/zhengce/202512/content_7050025.htm>","note":"给 B 的原因：坠落那组是单中心回顾性队列、不区分意外与自伤，重返工作那组只有 84 人且在德国，两组都不能当成「跳楼之后的个人预后」；次均住院费用是全国所有住院的平均数，不是坠落伤的费用，引它只为给一个可核对的下限。这条不写任何高度与后果的对应关系——原文只给了这批人的高度分布。长期卧床期间最该盯的压疮见第 17 节第 8 条，深静脉血栓与肺栓塞见第 13 节第 10 条（一条腿突然肿起来），念头冒出来时怎么办见本节第 30 条，中毒那一头见本节第 31 条（别把「救回来」当成兜底）。这条的时间线是作者的亲历：从四楼坠落，事前以为「十几天就好」，实际住院一年、四处手术、上了钢板、半年不能自己翻身坐起，家里为此借钱","money":"0","time":"少","will":"否","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"极高"},{"id":"1.33","sec":1,"n":33,"title":"别拿「少一个肾没什么」换钱：剩下那个要替两个干活，卖过肾的人事后 86% 说身体变差","cost":"0 元，只是先把这笔账看清","human":"先看最好的情况——层层筛查过、术后有随访的正规捐献者。美国那份 9.6 万人的队列里，捐肾后 15 年走到尿毒症（得靠透析或者再移植才能活）的是每万人 31 人，同样健康、同样够格捐但没捐的人是每万人 4 人。挪威随访 15 年的那份，捐肾者得尿毒症的风险高十倍上下，全因死亡高约三成，心血管死亡高约四成。就算没走到透析那一步，剩下那个肾也在替两个肾干活：捐后平均 12 年复查，32.1% 有高血压，12.7% 有蛋白尿，肾滤过功能还保持在 60 以上的是 85.5%。再看卖肾的那一头：印度金奈 305 个卖过肾的人，平均 6 年后回访，86% 说自己身体变差了，家庭收入平均降了三分之一，四分之三还欠着债，79% 不建议别人卖。上面前三组人有筛查、有复查、出问题能回医院，卖肾的人这三样一样都没有。","gain":"美国 96,217 名活体捐肾者与 20,024 名 NHANES III 中条件相当的健康未捐者比较：捐后 15 年 ESRD 估计风险 30.8/万（95% CI 24.3–38.5）对 3.9/万（95% CI 0.8–8.9），P<0.001；估计终生 ESRD 风险为捐献者 90/万、未经筛查的一般人群 326/万、健康未捐者 14/万。挪威 1901 名捐肾者（中位随访 15.1 年）与 32,621 名符合捐献条件的对照（中位随访 24.9 年）比较：全因死亡 HR 1.30（95% CI 1.11–1.52），心血管死亡 HR 1.40（1.03–1.91），ESRD HR 11.38（4.37–29.6），捐献者 ESRD 总发生率 302 例/百万。美国 3698 名捐肾者中 11 人发生 ESRD（180 例/百万人年，同期一般人群 268 例/百万人年）；其中 255 人在捐后平均 12.2±9.2 年复查：85.5% 的 GFR ≥ 60 ml/min/1.73 m²，32.1% 有高血压，12.7% 有蛋白尿。印度金奈 305 名卖肾者（平均在卖肾 6 年后接受调查）：96% 为还债而卖，平均拿到 1070 美元，切肾后家庭平均收入下降三分之一（P<0.001），生活在贫困线以下的人数增加，四分之三在调查时仍负债，86% 报告健康状况较切肾前变差，79% 不建议他人卖肾","grade":"A","src":"Muzaale AD, Massie AB, Wang MC, Montgomery RA, McBride MA, Wainright JL, Segev DL (2014). Risk of end-stage renal disease following live kidney donation. JAMA, 311(6), 579-586. <https://doi.org/10.1001/jama.2013.285141>；Mjøen G, Hallan S, Hartmann A, et al. (2014). Long-term risks for kidney donors. Kidney International, 86(1), 162-167. <https://doi.org/10.1038/ki.2013.460>；Ibrahim HN, Foley R, Tan L, et al. (2009). Long-term consequences of kidney donation. New England Journal of Medicine, 360(5), 459-469. <https://doi.org/10.1056/NEJMoa0804883>；Goyal M, Mehta RL, Schneiderman LJ, Sehgal AR (2002). Economic and health consequences of selling a kidney in India. JAMA, 288(13), 1589-1593. <https://doi.org/10.1001/jama.288.13.1589>","note":"争议：Ibrahim 那项以一般人群为对照，结论是捐肾者的生存和 ESRD 风险与一般人群相仿；Muzaale 和 Mjøen 把对照换成「同样健康、同样够格捐肾」的人之后，风险就显著高出来——分歧在对照组选谁，不在捐献者身上。三项都同意绝对风险不大（15 年 30.8/万），所以这条的重点不是「捐肾很危险」，而是两件事：剩下那个肾确实在付代价，高血压和蛋白尿的比例摆在那里；以及这些数字全都出自被筛查、有随访、出事能回医院的人群，黑市卖肾三样都没有，印度那份随访给出的是另一种结局。原始研究只给到自述健康变差、蛋白尿、高血压和尿毒症发生率，没有「多少人卧床」这类数字，这里不替它补。合法捐献的亲属限制、罚款与刑责见第 9 节第 22 条（不卖自己的器官）；已经要透析的，跨省直接结算和长期用药见第 16 节第 1、2 条（药按医嘱吃满、门诊慢特病异地备案）","money":"0","time":"少","will":"否","level":"大","lens":"死亡率","dispute":true,"todo":false,"ratio":"极高"},{"id":"1.34","sec":1,"n":34,"title":"不捡、不拆、不卖来路不明的金属件，带三叶草警示标志的离远点","cost":"0 元；看见不认识的金属圆柱、铅罐、从设备上拆下来的部件就绕开，不捡不拆不放进口袋","human":"辐射没有气味、颜色和温度，人感觉不到，所以「看着没事」不能用来判断——多数放射源就是一截普通金属，不发光也不发热。全国在用的放射源约 17.8 万枚，事故率稳定在每万枚不到 1 起，普通人撞上的概率极低，可撞上那一次是不可逆的：1987 年巴西有人把废弃诊所的放疗机当废铁拆开、把里面的铯-137 源带回家弄破，约 11.2 万人接受监测，249 人受到污染，4 人死亡。国内 2020 年一起探伤事故里，三名作业人员左手被照伤，最重的一只手到 Ⅳ 度。","gain":"截至 2025 年全国约 17.8 万枚在用放射源和 35.5 万台（套）射线装置，放射源辐射事故年发生率稳定在每万枚 1 起以下；Ⅰ类、Ⅱ类放射源丢失、被盗、失控即构成重大辐射事故，Ⅲ类为较大辐射事故，Ⅳ类、Ⅴ类丢失被盗或导致人员受到超过年剂量限值的照射为一般辐射事故；官方案例：2020 年 6 月宁夏钢铁集团炼铁厂高炉管道改造项目的 γ 射线探伤作业中，Ⅱ 类铱-192 放射源致三名作业人员受照，陈某某左手急性放射性皮肤损伤 Ⅲ 度，刘某某左手拇指、食指 Ⅳ 度并中指、无名指、小指 Ⅲ 度，樊某某左手 Ⅰ-Ⅱ 度，三人受照剂量均严重超过国家标准规定的剂量限值，两家责任单位被吊销辐射安全许可证并罚款 7 万元；国际案例：1987 年巴西戈亚尼亚，废弃诊所的远距离治疗机被拆解取出 50.8 TBq 铯-137 源并破坏源囊，约 112,000 人接受监测，249 人受到体内或体外污染，其中 129 人为中度至重度污染、50 人需密切医学监护，4 人死亡（全国 / 国际）","grade":"A","src":"生态环境部 (2025). 2024 中国生态环境状况公报. <https://www.mee.gov.cn/ywgz/sthjjcgl/hjzljcypj/202506/t20250605_1120773.shtml>；国家核安全局 (2026). 2025 年我国核与辐射安全监管工作成效. <https://nnsa.mee.gov.cn/tpxw/202601/t20260107_1140062.html>；生态环境部 (2021). 关于一起 γ 射线探伤作业违法违规造成辐射事故案件处理情况的通报. <https://www.mee.gov.cn/xxgk2018/xxgk/xxgk06/202101/t20210121_818216.html>；国务院 (2019). 放射性同位素与射线装置安全和防护条例（2019 年修订，第三十四、四十二、六十八条）. <https://www.mee.gov.cn/ywgz/fgbz/xzfg/201909/t20190918_734315.shtml>；环境保护部 (2009). 关于建立放射性同位素与射线装置辐射事故分级处理和报告制度的通知（辐射事故分级标准）. <https://www.mee.gov.cn/gkml/zj/wj/200910/t20091022_172414.htm>；International Atomic Energy Agency (1988). The Radiological Accident in Goiânia. IAEA, Vienna. <https://www-pub.iaea.org/MTCD/Publications/PDF/Pub815_web.pdf>","note":"X 光机、CT 这类靠通电产生射线的装置，断电后不残留放射性；真正危险的是设备里那枚密封放射源——医院的放疗机、管道和锅炉上的 γ 探伤机、测井仪、料位计都含源，拆开外壳就是把源暴露出来，而它们外观和普通金属件没有区别。所以规则不是「认出放射源」，是「来路不明的设备部件一律不拆、不卖、不带回家」。真遇到：离远点、记住位置、别搬动、打 110，条例要求向生态环境主管部门、公安部门、卫生主管部门报告；距离和时间是唯一有效的防护，隔着口袋或塑料袋没有任何用。废品回收、拆解、五金和工地这几行的人风险比一般人高得多，工地上见到画着三叶草标志的警戒区就绕行。这条说的是失控的放射源，和核电站泄漏是两回事，后者普通人遇到的概率更低。受益人主要是你自己和同在现场的家人。","money":"0","time":"少","will":"否","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"极高"}]},{"n":2,"title":"不要慢慢死","intro":"本节只收对总死亡率效应大、证据硬的慢性风险因素，按性价比从高到低排。除特别标注的随机试验外，数字都来自观察性研究，HR/RR 里含混杂和反向因果，读成「方向和量级」而不是「照做就能拿到的折扣」。","entries":[{"id":"2.1","sec":2,"n":1,"title":"戒烟，越早越好","cost":"戒断期的毅力（数周到数月）；金钱是负成本，一天一包烟约 20–30 元，戒了就省下。","human":"吸烟的人平均比不吸烟的人少活十年以上；40 岁前戒掉，能把继续吸烟带来的死亡风险抹掉九成左右，戒得越早捡回来越多。","gain":"美国队列（观察性）：现吸烟者比从不吸烟者预期寿命短 10 年以上；40 岁前戒掉可消除继续吸烟所带来死亡风险的约 90%，25–34、35–44、45–54 岁戒烟分别约多活 10、9、6 年（原文以寿命年报告）。中国队列（观察性）：2010 年代城市男性吸烟者 总死亡率 RR 1.65，农村男性 RR 1.22；主动戒烟满 10 年后归因风险接近消失。","grade":"A","src":"Jha P 等 (2013). 21st-century hazards of smoking and benefits of cessation in the United States. NEJM. <https://doi.org/10.1056/NEJMsa1211128>；Chen Z 等 (2015). Contrasting male and female trends in tobacco-attributed mortality in China: evidence from successive nationwide prospective cohort studies. Lancet. <https://doi.org/10.1016/S0140-6736(15)00340-2>","note":"二手烟同样致死：2004 年全球约 60.3 万人死于二手烟暴露，占当年总死亡约 1%（Oberg M 等 (2011). Worldwide burden of disease from exposure to second-hand smoke: a retrospective analysis of data from 192 countries. Lancet. <https://doi.org/10.1016/S0140-6736(10)61388-8>）。自己不吸也要避开别人的烟，尤其别让孩子吸。","money":"0","time":"少","will":"是","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"高"},{"id":"2.2","sec":2,"n":2,"title":"别在家里和车里抽烟，也别让客人在家里抽","cost":"0 元，难的是跟家人和客人开口","human":"全球每年约 60 万人死于吸别人的烟，其中近三成是孩子；长期吸二手烟的人，高血压、心脏病、卒中的风险都高三成上下，而且家里吸到的比外面更伤人。","gain":"2004 年全球有 603,000 人死于二手烟，约占全球死亡的 1.0%，其中 28% 是儿童；57 项研究的荟萃分析里，二手烟暴露者高血压比值比 1.28、心脏病 1.39、心肌梗死 1.50、卒中 1.36，且家庭内暴露的风险高于家庭外","grade":"A","src":"Öberg M, Jaakkola MS, Woodward A, Peruga A, Prüss-Ustün A (2011). Worldwide burden of disease from exposure to second-hand smoke: a retrospective analysis of data from 192 countries. Lancet：「603,000 deaths were attributable to second-hand smoke in 2004, which was about 1·0% of worldwide mortality. 47% of deaths from second-hand smoke occurred in women, 28% in children, and 26% in men」，「61% of DALYs were in children」. <https://doi.org/10.1016/S0140-6736(10)61388-8>；(2026). The Associations Between Secondhand Smoke Exposure and Various Cardiovascular Diseases: A Meta-Analysis. Nicotine & Tobacco Research：57 项研究，「hypertension (OR: 1.28, 95% CI: 1.15 to 1.40), heart disease (OR: 1.39, 95% CI: 1.28 to 1.50), myocardial infarction (OR: 1.50, 95% CI: 1.17 to 1.84), stroke (OR: 1.36, 95% CI: 1.18 to 1.54)」「Home exposure has a higher risk of CVD than non-home exposure」. <https://doi.org/10.1093/ntr/ntaf111>","note":"家里是最该管的地方，不只因为待得久，也因为荟萃分析里家庭内暴露的效应比家庭外更大。儿童承担了二手烟伤残调整生命年损失的 61%。自己戒烟见本节第 1 条。","money":"0","time":"少","will":"些","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"高"},{"id":"2.3","sec":2,"n":3,"title":"不喝含糖饮料","cost":"零；换成白水或无糖茶还省钱。","human":"每天喝两瓶以上甜饮料的人，同期死亡的概率比几乎不喝的人高约两成，每天一到两瓶也高一成多。","gain":"美国两大队列（观察性，约 11.8 万人、3.6 万例死亡）：每天 ≥2 份 vs 每月 <1 份，总死亡率 HR 1.21；每天 1–2 份 HR 1.14。欧洲 EPIC 队列（观察性，45 万人）：每天 ≥2 杯 vs 每月 <1 杯，含糖软饮 HR 1.08，所有软饮合计 HR 1.17。","grade":"A","src":"Malik VS 等 (2019). Long-Term Consumption of Sugar-Sweetened and Artificially Sweetened Beverages and Risk of Mortality in US Adults. Circulation. <https://doi.org/10.1161/CIRCULATIONAHA.118.037401>；Mullee A 等 (2019). Association Between Soft Drink Consumption and Mortality in 10 European Countries. JAMA Internal Medicine. <https://doi.org/10.1001/jamainternmed.2019.2478>","note":"观察性，重度饮用者整体生活方式更差，效应可能被高估。EPIC 里代糖饮料每天 ≥2 杯 HR 1.26 反而高于含糖饮料，可能是反向因果（已有代谢病的人改喝代糖），别把代糖饮料当成安全替代品大量喝，替代品首选水。","money":"0","time":"少","will":"些","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"高"},{"id":"2.4","sec":2,"n":4,"title":"不嚼槟榔","cost":"0 元，还省下买槟榔的钱","human":"嚼槟榔的人同期死亡的概率比不嚼的人高约两成，糖尿病和代谢综合征的风险高近五成，口腔癌和食管癌另算。","gain":"17 项亚洲研究、38.8 万人的荟萃分析：嚼槟榔者相对不嚼者总死亡率的相对风险 1.21（P=0.02，17.96 万人），糖尿病 1.47，代谢综合征 1.51；槟榔本身是口腔癌和食管癌的已知危险因素","grade":"A","src":"Yamada T, Hara K, Kadowaki T (2013). Chewing betel quid and the risk of metabolic disease, cardiovascular disease, and all-cause mortality: a meta-analysis. PLoS One, 8(8), e70679. <https://doi.org/10.1371/journal.pone.0070679>","note":"口腔癌风险与嚼的年数和每天的量成正比，戒了以后风险随时间下降。含烟草的槟榔更危险","money":"0","time":"少","will":"些","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"高"},{"id":"2.5","sec":2,"n":5,"title":"把家里的食盐换成低钠盐（钾盐）","cost":"每袋比普通盐贵几元；口味几乎不变，不需要毅力。","human":"两万人的随机试验里，把家里的盐换成低钠盐的人，五年内死亡的概率低约 12%，中风低约 14%。这是随机分组做出来的结果，比一般的观察数据更可信。","gain":"随机试验（中国农村，20995 名有卒中史或 ≥60 岁高血压者，随访 4.74 年）：低钠盐组 vs 普通盐组，全因死亡 RR 0.88，卒中 RR 0.86，主要心血管事件 RR 0.87；高钾血症事件两组无显著差异。","grade":"A","src":"Neal B 等 (2021). Effect of Salt Substitution on Cardiovascular Events and Death. NEJM. <https://doi.org/10.1056/NEJMoa2105675>","note":"争议：PURE 队列（观察性，O'Donnell M 等 (2014). Urinary sodium and potassium excretion, mortality, and cardiovascular events. NEJM. <https://doi.org/10.1056/NEJMoa1311889>）报告估算钠排泄 <3 g/天者死亡+心血管事件复合 OR 1.27，≥7 g/天 OR 1.15，提示钠摄入呈 J 型。但 SSaSS 是随机试验，低钠盐只是部分替换，不会把钠压到那么低。试验人群是高危老人，健康年轻人的绝对获益更小；肾功能不全或在吃保钾类药物的人换盐前先问医生。","money":"少","time":"少","will":"否","level":"中","lens":"死亡率","dispute":true,"todo":false,"ratio":"一般"},{"id":"2.6","sec":2,"n":6,"title":"认真刷牙，每天清一次牙缝，缺牙及时补","cost":"牙线或牙缝刷每年几十元，每天多花两三分钟；洗牙每次一两百元","human":"每天用牙线或牙缝刷的人，同期死亡的概率低约一成；牙掉光的老人死亡概率高约九成，剩不到 20 颗牙的高约一倍。","gain":"日本 9676 人 6 年队列：使用牙缝清洁工具者总死亡率风险比 0.89，使用舌苔清洁工具者 0.77；社区老人荟萃分析：全口无牙的死亡比值比 1.87（95% CI 1.35–2.59），牙齿少于 20 颗的 2.04（1.67–2.49）","grade":"B","src":"Wang K, Matsuyama Y, Kiuchi S, et al. (2026). Routine oral health practices and all-cause mortality. Journal of Dentistry. <https://doi.org/10.1016/j.jdent.2026.106789>；Ko MJ, Seo S, So JS, et al. (2026). Deteriorated oral health and function as risk factors for physical disability and mortality in community-dwelling older adults: a systematic review and meta-analysis. European Geriatric Medicine. <https://doi.org/10.1007/s41999-025-01319-4>","note":"争议。观察性数据，牙不好的人往往整体健康和经济状况也差，因果方向不确定。但成本极低，牙周炎和缺牙本身就影响进食","money":"少","time":"少","will":"些","level":"中","lens":"死亡率","dispute":true,"todo":false,"ratio":"一般"},{"id":"2.7","sec":2,"n":7,"title":"每天走到 7000–8000 步","cost":"约 60–90 分钟步行，可以拆进通勤和买菜里；不花钱。","human":"每天走 5800 步的人，同期死亡的概率比只走 3500 步的人低约四成；走到 7800 步低约四成半；再往上还能低一些，但 60 岁以上走到 6000 到 8000 步、60 岁以下走到 8000 到 10000 步之后收益就趋平了。老人走到 6000–8000 步就够。","gain":"15 个队列的荟萃分析（观察性，47471 人、3013 例死亡）：按步数四分位，中位 5801、7842、10901 步/天 vs 3553 步/天，总死亡率 HR 分别 0.60、0.55、0.47；≥60 岁者获益在 6000–8000 步后趋平，<60 岁者在 8000–10000 步后趋平。另一荟萃分析：从约 3867 步/天起开始有效，每多 1000 步/天 总死亡率 降约 15%。","grade":"A","src":"Paluch AE 等 (2022). Daily steps and all-cause mortality: a meta-analysis of 15 international cohorts. Lancet Public Health. <https://doi.org/10.1016/S2468-2667(21)00302-9>；Banach M 等 (2023). The association between daily step count and all-cause and cardiovascular mortality: a meta-analysis. European Journal of Preventive Cardiology. <https://doi.org/10.1093/eurjpc/zwad229>","note":"观察性，走得最少的人里混有已经病弱者（反向因果），HR 偏大是常态；但剂量反应清楚，从 4000 步走到 7000 步的边际收益最大，不必执着一万步。和第 10 条（每周 150–300 分钟中等强度运动）是同一件事的两种计量方式，达标一个即可。","money":"0","time":"多","will":"些","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"一般"},{"id":"2.8","sec":2,"n":8,"title":"有高血压、高血脂就按医嘱规律吃药，别自行停","cost":"集采降压药、他汀每月几元到几十元；每天一次的习惯。","human":"血压每降 10 mmHg，死亡概率降约 13%、中风降约 27%；他汀把低密度胆固醇降 1 个单位，死亡概率降约一成。按时吃药的人比经常漏吃的人，死亡概率低三成到四成半。","gain":"随机试验荟萃分析：收缩压每降 10 mmHg，总死亡率 RR 0.87，主要心血管事件 RR 0.80，卒中 RR 0.73，心衰 RR 0.72；他汀使 LDL 每降 1.0 mmol/L，总死亡率 RR 0.90，主要血管事件 RR 0.78。依从性荟萃分析（观察性）：他汀、降压药依从 ≥80% 者 vs 依从差者，总死亡率 RR 分别 0.55、0.71。","grade":"A","src":"Ettehad D 等 (2016). Blood pressure lowering for prevention of cardiovascular disease and death: a systematic review and meta-analysis. Lancet. <https://doi.org/10.1016/S0140-6736(15)01225-8>；Cholesterol Treatment Trialists' (CTT) Collaboration (2010). Efficacy and safety of more intensive lowering of LDL cholesterol: a meta-analysis of data from 170 000 participants in 26 randomised trials. Lancet. <https://doi.org/10.1016/S0140-6736(10)61350-5>；Chowdhury R 等 (2013). Adherence to cardiovascular therapy: a meta-analysis of prevalence and clinical consequences. European Heart Journal. <https://doi.org/10.1093/eurheartj/eht295>","note":"只对有用药指征的人成立，健康人不需要吃。依从性那组数字是观察性的，「能坚持吃药的人本身更自律」会夸大效应，前两组随机试验数字更可靠。本节不单列血糖控制：强化降糖对 总死亡率 的证据不如血压、血脂一致。","money":"少","time":"少","will":"些","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"高"},{"id":"2.9","sec":2,"n":9,"title":"每晚睡 7 小时左右，作息固定","cost":"时间（多数人是把刷手机的时间换成睡觉）；固定作息需要一点自律。","human":"长期睡不到 7 小时的人，同期死亡的概率高约一成；作息越乱风险越高，睡得最规律的人比最不规律的人低两成到近五成——作息规律比睡多久更能预测死亡风险。","gain":"荟萃分析（观察性，16 项研究、138 万人、11.3 万例死亡）：睡得短者 总死亡率 RR 1.12，睡得长者 RR 1.30。剂量反应荟萃分析：以 7 小时为最低点，少于 7 小时每少 1 小时 RR 1.06，多于 7 小时每多 1 小时 RR 1.13。UK Biobank 约 6.1 万人腕表数据（观察性）：睡眠最规律的四个五分位 vs 最不规律的五分位，总死亡率 低 20%–48%，规律性比时长更能预测死亡。","grade":"A","src":"Cappuccio FP 等 (2010). Sleep duration and all-cause mortality: a systematic review and meta-analysis of prospective studies. Sleep. <https://doi.org/10.1093/sleep/33.5.585>；Yin J 等 (2017). Relationship of Sleep Duration With All-Cause Mortality and Cardiovascular Events: A Systematic Review and Dose-Response Meta-Analysis of Prospective Cohort Studies. JAHA. <https://doi.org/10.1161/JAHA.117.005947>；Windred DP 等 (2024). Sleep regularity is a stronger predictor of mortality risk than sleep duration: A prospective cohort study. Sleep. <https://doi.org/10.1093/sleep/zsad253>","note":"长睡的高风险多半是反向因果（抑郁、慢性病、睡眠呼吸暂停让人睡得多），不必刻意压缩睡眠；短睡和不规律更值得改。规律性证据目前来自单一队列，单独看属 B 级。","money":"0","time":"多","will":"些","level":"中","lens":"死亡率","dispute":false,"todo":false,"ratio":"一般"},{"id":"2.10","sec":2,"n":10,"title":"每周累计 150–300 分钟中等强度运动，快走即可","cost":"每天 20–45 分钟；不花钱。","human":"每周快走 150–300 分钟的人，同期死亡的概率比不运动的人低约三成；就算没练够也能低两成，练到三五倍量降到底（低约四成），再多不再降，也没坏处。","gain":"多队列汇总分析（观察性）：达到指南下限 1–2 倍（7.5–15 MET·h/周，约合快走 150–300 分钟/周）者 vs 不运动者 总死亡率 HR 0.69；不足下限也有 HR 0.80；3–5 倍时 HR 0.61 到顶，再多不再降但也无害（≥10 倍 HR 0.69）。加速度计测量的荟萃分析：中高强度活动最高四分位 vs 最低 HR 0.52。","grade":"A","src":"Arem H 等 (2015). Leisure time physical activity and mortality: a detailed pooled analysis of the dose-response relationship. JAMA Internal Medicine. <https://doi.org/10.1001/jamainternmed.2015.0533>；Ekelund U 等 (2019). Dose-response associations between accelerometry measured physical activity and sedentary time and all cause mortality: systematic review and harmonised meta-analysis. BMJ. <https://doi.org/10.1136/bmj.l4570>","note":"观察性；加速度计研究随访短、样本偏老，HR 里含反向因果成分，真实效应应小于 0.52 这种量级。和第 7 条（每天走到 7000–8000 步）二选一即可。","money":"0","time":"多","will":"些","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"一般"},{"id":"2.11","sec":2,"n":11,"title":"每周打三次球拍类运动，每次 45 分钟","cost":"场地费每次几十元；每周约 2 小时","human":"常打网球、羽毛球、乒乓球的人，同期死亡的概率比不打的人低约一半，心血管死亡低约 56%；游泳低约 28%，跑步和足球在这份数据里没看出差别。","gain":"英国 8.03 万人队列：相对不做该项目，球拍类运动（网球、羽毛球、乒乓球）的总死亡率风险比 0.53（95% CI 0.40–0.69），心血管死亡 0.44（0.24–0.83）；游泳 0.72 和 0.59；有氧操 0.73 和 0.64；骑车 0.85；跑步和足球未见显著关联","grade":"A","src":"Oja P, Kelly P, Pedisic Z, et al. (2017). Associations of specific types of sports and exercise with all-cause and cardiovascular-disease mortality: a cohort study of 80 306 British adults. British Journal of Sports Medicine, 51(10), 812-817. <https://doi.org/10.1136/bjsports-2016-096822>","note":"争议。观察性研究，打球的人本身更健康、社交更多；跑步组无显著关联也提示存在选择效应。别据此认为跑步没用，本节另有运动总量的条目","money":"少","time":"中","will":"些","level":"大","lens":"死亡率","dispute":true,"todo":false,"ratio":"一般"},{"id":"2.12","sec":2,"n":12,"title":"把爬楼梯、快走赶路这类零碎的用力活动攒到每天四五分钟","cost":"0 元；不用额外挤出锻炼时间","human":"平时完全不锻炼的人，只要每天有三次一两分钟的用力活动（爬楼梯、快步赶路），同期死亡的概率就比一点没有的人低约四成，心血管死亡低近一半。","gain":"英国生物银行 2.52 万名不专门锻炼者、平均随访 6.9 年、852 例死亡：每天 3 次、每次 1–2 分钟的零碎剧烈活动，相对完全没有的人，总死亡率和癌症死亡率降低 38%–40%，心血管死亡率降低 48%–49%；每天累计 4.4 分钟对应总死亡率和癌症死亡率降低 26%–30%，心血管死亡率降低 32%–34%","grade":"A","src":"Stamatakis E, Ahmadi MN, Gill JMR, et al. (2022). Association of wearable device-measured vigorous intermittent lifestyle physical activity with mortality. Nature Medicine, 28, 2521-2529. <https://doi.org/10.1038/s41591-022-02100-x>","note":"争议。用可穿戴设备实测，比问卷可靠，但仍是观察性研究，随访只有 6.9 年。研究对象是完全不锻炼的人，对已经规律运动的人不适用","money":"0","time":"少","will":"些","level":"大","lens":"死亡率","dispute":true,"todo":false,"ratio":"高"},{"id":"2.13","sec":2,"n":13,"title":"每周做 30–60 分钟力量训练","cost":"每周 1–2 次、每次 20–30 分钟；徒手深蹲、俯卧撑不花钱。","human":"每周练 30–60 分钟力量的人，同期死亡的概率比不练的人低一到两成，再多练不再加分；和有氧一起做效果最好。","gain":"队列荟萃分析（观察性）：做力量训练者 vs 不做者 总死亡率 低 10%–17%；剂量反应呈 J 型，约 30–60 分钟/周时降幅最大（约 10%–20%），更多不再增益；力量+有氧都做 vs 都不做，总死亡率 更低。","grade":"A","src":"Momma H 等 (2022). Muscle-strengthening activities are associated with lower risk and mortality in major non-communicable diseases: a systematic review and meta-analysis of cohort studies. British Journal of Sports Medicine. <https://doi.org/10.1136/bjsports-2021-105061>","note":"观察性，自报运动量。J 型曲线右侧上升段的证据薄，不必因此限制训练量；对老年人另有防跌倒、保肌肉的收益，那是第 1 节的事。","money":"0","time":"中","will":"些","level":"中","lens":"死亡率","dispute":false,"todo":false,"ratio":"一般"},{"id":"2.14","sec":2,"n":14,"title":"别连着坐太久，隔一阵起身动一动","cost":"零；设个提醒。","human":"坐得最久的人，同期死亡的概率是坐得最少的人的 2.6 倍，一次连着坐很久还要另算一笔。但每天有 60–75 分钟中等强度活动，久坐多出来的风险基本能被抵消。","gain":"美国队列（观察性，加速度计）：久坐总时长最高四分位 vs 最低 总死亡率 HR 2.63；连续不起身的久坐时段最长四分位 vs 最短 HR 1.96，总量和连续时长各自独立相关。百万人汇总分析（观察性）：每天坐 >8 小时且几乎不运动者 vs 坐 <4 小时且最活跃者 HR 1.59；每天约 60–75 分钟中等强度活动可抵消久坐的超额风险（最活跃组坐 >8 小时 HR 1.04，不显著）。","grade":"A","src":"Diaz KM 等 (2017). Patterns of Sedentary Behavior and Mortality in U.S. Middle-Aged and Older Adults: A National Cohort Study. Annals of Internal Medicine. <https://doi.org/10.7326/M17-0212>；Ekelund U 等 (2016). Does physical activity attenuate, or even eliminate, the detrimental association of sitting time with mortality? A harmonised meta-analysis of data from more than 1 million men and women. Lancet. <https://doi.org/10.1016/S0140-6736(16)30370-1>","note":"观察性，坐得最多的人里含大量病弱者，HR 2.63 这种量级明显含反向因果。可靠的结论是：坐多久不如动多少重要，运动量够时久坐风险基本消失；看电视 ≥3 小时/天的风险各活动水平都在，最活跃组也只是把阈值推到 ≥5 小时（HR 1.16）。","money":"0","time":"少","will":"些","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"高"},{"id":"2.15","sec":2,"n":15,"title":"少吃加工肉（火腿、培根、香肠、午餐肉）","cost":"零，甚至省钱；口味上的一点牺牲。","human":"火腿、培根、香肠吃得最多的人，同期死亡的概率比吃得最少的人高约两成；每天多吃一份加工肉就高两成。","gain":"荟萃分析（观察性）：加工肉最高 vs 最低摄入组 总死亡率 RR 1.23，总红肉 RR 1.29，未加工红肉 RR 1.10（不显著）；另一荟萃分析按剂量：加工肉每多 1 份/天 RR 1.23，红肉每多 1 份/天 RR 1.10。","grade":"A","src":"Larsson SC, Orsini N (2014). Red meat and processed meat consumption and all-cause mortality: a meta-analysis. American Journal of Epidemiology. <https://doi.org/10.1093/aje/kwt261>；Schwingshackl L 等 (2017). Food groups and risk of all-cause mortality: a systematic review and meta-analysis of prospective studies. American Journal of Clinical Nutrition. <https://doi.org/10.3945/ajcn.117.153148>","note":"争议：NutriRECS 指南（Johnston BC 等 (2019). Unprocessed Red Meat and Processed Meat Consumption: Dietary Guideline Recommendations From the NutriRECS Consortium. Annals of Internal Medicine. <https://doi.org/10.7326/M19-1621>）用 GRADE 把证据评为低确定性，给出「维持现有摄入」的弱推荐。争的是证据质量而不是方向，没有研究说加工肉有益。未加工红肉效应小且不显著，重点是加工肉。","money":"0","time":"少","will":"些","level":"大","lens":"死亡率","dispute":true,"todo":false,"ratio":"高"},{"id":"2.16","sec":2,"n":16,"title":"少喝或不喝酒","cost":"社交场合的一点尴尬；省钱。","human":"每周超过 100 g 纯酒精（约合 2.5 L 啤酒）以后，喝得越多死得越早：40 岁时每周喝 100–200 g 的人少活半年左右，200–350 g 少一两年，超过 350 g 少四五年。按整体健康算，最划算的量是 0。","gain":"83 项前瞻研究 60 万现饮者汇总（观察性）：总死亡率 最低点在每周 ≤100 g 纯酒精（约合 5% 啤酒 2.5 L 或 40° 白酒 300 mL）；40 岁时每周 100–200 g 者预期寿命少约 6 个月，200–350 g 少 1–2 年，>350 g 少 4–5 年（原文以寿命年报告）。GBD 2016：把各类健康损失合计，风险最低的饮酒量是 0 杯/周。校正研究设计偏倚的荟萃分析：少量饮酒（1.3–24 g/天）vs 终身不饮 RR 0.93（不显著），45–64 g/天 RR 1.19，≥65 g/天 RR 1.35。","grade":"A","src":"Wood AM 等 (2018). Risk thresholds for alcohol consumption: combined analysis of individual-participant data for 599 912 current drinkers in 83 prospective studies. Lancet. <https://doi.org/10.1016/S0140-6736(18)30134-X>；GBD 2016 Alcohol Collaborators (2018). Alcohol use and burden for 195 countries and territories, 1990–2016: a systematic analysis for the Global Burden of Disease Study 2016. Lancet. <https://doi.org/10.1016/S0140-6736(18)31310-2>；Zhao J 等 (2023). Association Between Daily Alcohol Intake and Risk of All-Cause Mortality: A Systematic Review and Meta-analyses. JAMA Network Open. <https://doi.org/10.1001/jamanetworkopen.2023.6185>","note":"争议。J 型曲线一方：34 项前瞻研究荟萃（Di Castelnuovo A 等 (2006). Alcohol dosing and total mortality in men and women: an updated meta-analysis of 34 prospective studies. Archives of Internal Medicine. <https://doi.org/10.1001/archinte.166.22.2437>）报告少量饮酒 总死亡率 最多低 17%–18%，男性 ≤4 杯/天、女性 ≤2 杯/天仍呈负相关。反方认为「不饮者」里混入了因病戒酒者和整体健康更差的人，Zhao 2023 校正这些偏倚后保护作用消失，GBD 2018 也给 0 最安全。稳妥读法：少喝不会明显伤寿命，多喝一定伤，「为了健康开始喝」没有依据。","money":"0","time":"少","will":"些","level":"大","lens":"死亡率","dispute":true,"todo":false,"ratio":"高"},{"id":"2.17","sec":2,"n":17,"title":"每天吃一小把坚果","cost":"每天 28 克，一年约两三百元","human":"常吃坚果的人，同期死亡的概率比不吃的人低约两成；一周吃一次就能看出差别（低约一成），吃到每天最明显。","gain":"两个美国队列 11.9 万人、300 多万人年：相对不吃坚果，每周吃不到 1 次的总死亡率风险比 0.93（95% CI 0.90–0.96），每周 1 次 0.89（0.86–0.93），每周 2–4 次 0.87（0.83–0.90），每周 5–6 次 0.85（0.79–0.91），每周 7 次以上 0.80（0.73–0.86）","grade":"A","src":"Bao Y, Han J, Hu FB, et al. (2013). Association of nut consumption with total and cause-specific mortality. New England Journal of Medicine, 369(21), 2001-2011. <https://doi.org/10.1056/NEJMoa1307352>","note":"观察性队列，吃坚果的人整体生活方式更好，数字要打折。选原味不加盐的；热量不低，别当零食无限吃","money":"少","time":"少","will":"否","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"高"},{"id":"2.18","sec":2,"n":18,"title":"把一部分红肉换成鱼和禽肉","cost":"0 元，是替换不是增加","human":"每周多吃两份加工肉或红肉，同期死亡的概率高约 3%；换成同样份数的鱼或禽肉，就看不出升高。这条的效应在本节里偏小，属于顺手就换、不必较劲的事。","gain":"美国 6 个队列近 3 万人的合并分析：每周多吃两份加工肉，总死亡率风险比 1.03（95% CI 1.02–1.05）；每周多吃两份未加工红肉 1.03（1.01–1.05）；同样吃法的禽肉 0.99（0.97–1.02）、鱼 0.99（0.97–1.01），均无统计学意义","grade":"A","src":"Zhong VW, Van Horn L, Greenland P, et al. (2020). Associations of Processed Meat, Unprocessed Red Meat, Poultry, or Fish Intake With Incident Cardiovascular Disease and All-Cause Mortality. JAMA Internal Medicine, 180(4), 503-512. <https://doi.org/10.1001/jamainternmed.2019.6969>","note":"每周两份的效应量很小，别指望靠换肉延寿；这条的价值在于同样花钱吃肉时选哪一种","money":"0","time":"少","will":"些","level":"小","lens":"死亡率","dispute":false,"todo":false,"ratio":"一般"},{"id":"2.19","sec":2,"n":19,"title":"把一部分精米白面换成全谷物","cost":"糙米、燕麦、全麦面价格略高，口感需要适应。","human":"每天多吃 90 g 全谷物（约三份）的人，同期死亡的概率低约 17%，吃到每天 200 g 左右还在继续降。","gain":"荟萃分析（观察性）：全谷物每多 90 g/天（约 3 份）总死亡率 RR 0.83，收益持续到 210–225 g/天；另一荟萃分析每多 1 份/天 RR 0.92。","grade":"A","src":"Aune D 等 (2016). Whole grain consumption and risk of cardiovascular disease, cancer, and all cause and cause specific mortality: systematic review and dose-response meta-analysis of prospective studies. BMJ. <https://doi.org/10.1136/bmj.i2716>；Schwingshackl L 等 (2017). Food groups and risk of all-cause mortality: a systematic review and meta-analysis of prospective studies. American Journal of Clinical Nutrition. <https://doi.org/10.3945/ajcn.117.153148>","note":"观察性，吃全谷物的人整体更健康，效应偏大；研究间异质性高（I² 83%）。不必全换，换一半就已在剂量反应曲线的陡段。","money":"少","time":"少","will":"些","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"高"},{"id":"2.20","sec":2,"n":20,"title":"每周喝三次以上茶","cost":"每年几十到几百元","human":"有喝茶习惯的人，同期死亡的概率低约 15%；从 50 岁算起，平均多 1.26 年寿命，多 1.41 年不得心血管病的时间。","gain":"中国 10.09 万人、中位随访 7.3 年的队列（China-PAR）：习惯饮茶者总死亡率风险比 0.85（95% CI 0.79–0.90）；以 50 岁为起点，习惯饮茶者无动脉粥样硬化性心血管病的年数多 1.41 年，预期寿命多 1.26 年","grade":"A","src":"Wang X, Liu F, Li J, et al. (2020). Tea consumption and the risk of atherosclerotic cardiovascular disease and all-cause mortality: The China-PAR project. European Journal of Preventive Cardiology, 27(18), 1956-1963. <https://doi.org/10.1177/2047487319894685>","note":"争议。观察性研究，中国男性饮茶者中吸烟饮酒比例高，作者已校正但残余混杂难免。别喝滚烫的，见本节关于热饮温度的一条","money":"少","time":"少","will":"否","level":"中","lens":"死亡率","dispute":true,"todo":false,"ratio":"一般"},{"id":"2.21","sec":2,"n":21,"title":"每天喝三到四杯咖啡，不加糖不加奶盖","cost":"自己冲每天一两元","human":"每天喝三到四杯咖啡的人，同期死亡的概率比不喝的人低约 17%。","gain":"涵盖 201 项观察性研究荟萃分析的伞形综述：每天 3–4 杯相对不喝，总死亡率相对风险 0.83（95% CI 0.79–0.88），即低 17%","grade":"A","src":"Poole R, Kennedy OJ, Roderick P, et al. (2017). Coffee consumption and health: umbrella review of meta-analyses of multiple health outcomes. BMJ, 359, j5024. <https://doi.org/10.1136/bmj.j5024>","note":"争议。原作者写明证据几乎全是观察性的，「需要可靠的随机对照试验才能判断是否为因果」。孕妇和有心律失常、焦虑、失眠问题的人另说；加糖加奶盖会把好处抵消","money":"少","time":"少","will":"否","level":"大","lens":"死亡率","dispute":true,"todo":false,"ratio":"高"},{"id":"2.22","sec":2,"n":22,"title":"每天吃够 5 份（约 400 g）水果蔬菜","cost":"每天几元到十几元；洗切的时间。","human":"每天多吃 200 g 果蔬，同期死亡的概率低约一成；每天吃够 5 份的人比只吃 2 份的人低约 13%，再多不再降。","gain":"荟萃分析（观察性）：每多 200 g/天 总死亡率 RR 0.90，收益持续到 800 g/天；美国两大队列加 26 项队列荟萃：每天 5 份 vs 2 份 总死亡率 HR 0.87，2 份水果+3 份蔬菜最优，再多不再降。","grade":"A","src":"Aune D 等 (2017). Fruit and vegetable intake and the risk of cardiovascular disease, total cancer and all-cause mortality: a systematic review and dose-response meta-analysis of prospective studies. International Journal of Epidemiology. <https://doi.org/10.1093/ije/dyw319>；Wang DD 等 (2021). Fruit and Vegetable Intake and Mortality: Results From 2 Prospective Cohort Studies of US Men and Women and a Meta-Analysis of 26 Cohort Studies. Circulation. <https://doi.org/10.1161/CIRCULATIONAHA.120.048996>","note":"观察性，混杂明显（吃菜多的人收入、教育、运动都不同），RR 0.90 是上限量级。两项研究对「够不够」的答案一致：5 份到位，10 份不必。","money":"少","time":"中","will":"些","level":"中","lens":"死亡率","dispute":false,"todo":false,"ratio":"一般"},{"id":"2.23","sec":2,"n":23,"title":"少吃超加工食品（薯片、方便面、糕点、速食）","cost":"要自己做饭或挑原材料食物，时间和毅力成本中等。","human":"超加工食品吃得最多的人，同期死亡的概率比吃得最少的人高约两成，心血管死亡高五成。不过这类证据的确定性被评为低，数字要往回打折看。","gain":"伞状综述（汇总观察性荟萃分析）：超加工食品摄入高 vs 低，总死亡率 RR 1.21，心血管病死亡 RR 1.50；两者证据分级分别为「高度提示」和「令人信服」，但 GRADE 确定性为低/极低。","grade":"A","src":"Lane MM 等 (2024). Ultra-processed food exposure and adverse health outcomes: umbrella review of epidemiological meta-analyses. BMJ. <https://doi.org/10.1136/bmj-2023-077310>","note":"争议：分类标准（NOVA）把营养差异很大的食物归为一类，且与含糖饮料、加工肉（第 3、15 条）高度重叠，独立效应难以分离，GRADE 评级低。做到第 3、15 条（不喝含糖饮料、少吃加工肉）之后，这一条的边际收益不确定；反方证据是同一篇综述里的低确定性评级本身，目前没有反向结论的原始研究。","money":"0","time":"多","will":"是","level":"大","lens":"死亡率","dispute":true,"todo":false,"ratio":"一般"},{"id":"2.24","sec":2,"n":24,"title":"不喝甜味饮料，无糖的也算","cost":"0 元，还省钱","human":"每天喝两杯以上软饮料的人，同期死亡的概率比每月不到一杯的人高约 17%；其中代糖饮料高约 26%，比含糖的还高——多半是已经有病的人才改喝代糖，别据此认为代糖更毒，但也别把它当安全替代。","gain":"欧洲 10 国 45 万人队列：每天喝两杯以上软饮料相对每月不到一杯，总死亡率风险比 1.17（95% CI 1.11–1.22）；其中含糖饮料 1.08（1.01–1.16），人工甜味剂饮料 1.26（1.16–1.35）","grade":"A","src":"Mullee A, Romaguera D, Pearson-Stuttard J, et al. (2019). Association Between Soft Drink Consumption and Mortality in 10 European Countries. JAMA Internal Medicine, 179(11), 1479-1490. <https://doi.org/10.1001/jamainternmed.2019.2478>","note":"争议。人工甜味剂饮料的关联更强，很可能是反向因果：已经超重或得了糖尿病的人才改喝无糖版。但至少说明「换成无糖就没事」没有证据支持","money":"0","time":"少","will":"些","level":"中","lens":"死亡率","dispute":true,"todo":false,"ratio":"一般"},{"id":"2.25","sec":2,"n":25,"title":"做饭、取暖不烧煤和柴，换成电或燃气","cost":"农村家庭换灶具加燃料费，每年几百到上千元；城市居民基本已达成。","human":"做饭烧煤或柴的人，同期死亡的概率高约一成，取暖烧的高约 14%；已经改用电或燃气的人，比继续烧固体燃料的人死亡概率低 13%–33%。","gain":"中国慢性病前瞻队列（观察性，27.1 万无心血管病成人）：做饭用固体燃料 vs 清洁燃料 总死亡率 HR 1.11，取暖用固体燃料 HR 1.14；已从固体燃料换成清洁燃料者 vs 继续用固体燃料者，做饭 HR 0.87、取暖 HR 0.67。室外 PM2.5：104 项队列荟萃，长期暴露每高 10 µg/m³，自然原因死亡 RR 1.08。","grade":"A","src":"Yu K 等 (2018). Association of Solid Fuel Use With Risk of Cardiovascular and All-Cause Mortality in Rural China. JAMA. <https://doi.org/10.1001/jama.2018.2151>；Chen J, Hoek G (2020). Long-term exposure to PM and all-cause and cause-specific mortality: A systematic review and meta-analysis. Environment International. <https://doi.org/10.1016/j.envint.2020.105974>","note":"观察性；换燃料的家庭往往也更富裕，HR 0.67 含混杂。室外 PM2.5 个人能做的有限（搬家、口罩、净化器），空气净化器没有以死亡率为终点的研究，本节不给数字。","money":"多","time":"少","will":"否","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"高"},{"id":"2.26","sec":2,"n":26,"title":"热的东西放一放再喝，不喝滚烫的茶、汤和咖啡","cost":"0 元；多等两三分钟","human":"喝很烫的茶，得食管癌的概率是喝温茶的 8 倍，只是「热」也有 2 倍；倒出来不到两分钟就喝，风险是等四分钟以上的 5 倍。等四分钟以上再喝的人，风险只有不到两分钟就喝的五分之一左右。","gain":"伊朗北部食管癌高发区 300 例病例、571 名对照：相对喝温的茶，喝「热」的茶患食管鳞癌的比值比 2.07（95% CI 1.28–3.35），喝「很热」的 8.16（3.93–16.9）；倒出后不到 2 分钟就喝相对等 4 分钟以上的 5.41（2.63–11.1）","grade":"A","src":"Islami F, Pourshams A, Nasrollahzadeh D, et al. (2009). Tea drinking habits and oesophageal cancer in a high risk area in northern Iran: population based case-control study. BMJ, 338, b929. <https://doi.org/10.1136/bmj.b929>；Loomis D, Guyton KZ, Grosse Y, et al. (2016). Carcinogenicity of drinking coffee, mate, and very hot beverages. Lancet Oncology, 17(7), 877-878. <https://doi.org/10.1016/S1470-2045(16)30239-X>","note":"国际癌症研究机构把 65 ℃ 以上的热饮列为 2A 类（很可能致癌），同时认定咖啡本身不致癌。中国潮汕、太行山一带食管癌高发，与趁烫喝的习惯有关","money":"0","time":"少","will":"些","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"高"},{"id":"2.27","sec":2,"n":27,"title":"白天出门晒晒太阳，别整天不见光","cost":"0 元；每天十几分钟，通勤和午休就够","human":"刻意躲太阳的女性，预期寿命比晒得最多的人少 0.6–2.1 年；原文的说法是，不吸烟但躲太阳的人，寿命和晒太阳最多那组里的吸烟者差不多。","gain":"瑞典 2.95 万名女性、20 年随访：相对晒太阳最多的一组，回避晒太阳者的预期寿命少 0.6 到 2.1 年；作者写道「不吸烟但回避晒太阳的人，预期寿命与晒太阳最多组里的吸烟者相当」","grade":"B","src":"Lindqvist PG, Epstein E, Nielsen K, et al. (2016). Avoidance of sun exposure as a risk factor for major causes of death: a competing risk analysis of the Melanoma in Southern Sweden cohort. Journal of Internal Medicine, 280(4), 375-387. <https://doi.org/10.1111/joim.12496>","note":"争议。瑞典纬度高、日照少，结论不能直接搬到中国；回避晒太阳的人可能本来就体弱、不出门。晒太阳增加皮肤癌风险，别晒到晒伤，正午强光下仍要遮挡","money":"0","time":"少","will":"否","level":"中","lens":"死亡率","dispute":true,"todo":false,"ratio":"高"},{"id":"2.28","sec":2,"n":28,"title":"把 BMI 控制在 20–25，超重就减","cost":"毅力最大的一条：饮食加运动长期坚持，减下来之后维持更难。","human":"死亡概率在 BMI 20–25 最低；BMI 到 27.5–30 高约两成，30–35 高约四成半，35–40 接近翻倍。东亚人对超重更敏感，BMI 每高 5 就高约四成。","gain":"239 项前瞻研究个体数据荟萃（观察性，限定从不吸烟、基线无慢性病、存活满 5 年者）：总死亡率 在 BMI 20–25 最低，25–27.5 HR 1.07，27.5–30 HR 1.20，30–35 HR 1.45，35–40 HR 1.94，40–60 HR 2.76；BMI 25 以上每高 5 kg/m²，东亚人群 HR 1.39。","grade":"A","src":"Global BMI Mortality Collaboration (2016). Body-mass index and all-cause mortality: individual-participant-data meta-analysis of 239 prospective studies in four continents. Lancet. <https://doi.org/10.1016/S0140-6736(16)30175-1>","note":"争议：「肥胖悖论」一方（Flegal KM 等 (2013). Association of all-cause mortality with overweight and obesity using standard body mass index categories: a systematic review and meta-analysis. JAMA. <https://doi.org/10.1001/jama.2012.113905>）汇总得超重 HR 0.94、1 级肥胖 HR 0.95，即轻度超重反而略低。分歧主要来自是否剔除吸烟者、已患病者和早期随访（病重的人先瘦下来），Global BMI 剔除后超重的风险重新出现。另外没有随机试验证明减重本身降低 总死亡率，收益是从横断比较推出来的，不能直接当成「减掉就能拿到」的折扣。","money":"0","time":"多","will":"是","level":"大","lens":"死亡率","dispute":true,"todo":false,"ratio":"一般"},{"id":"2.29","sec":2,"n":29,"title":"每周吃四次以上辣椒","cost":"0 元","human":"每周吃四次以上辣椒的人，同期死亡的概率比很少吃的人低约 23%，心血管死亡低约三分之一。","gain":"意大利 2.28 万人、中位随访 8.2 年、1236 例死亡：每周吃辣椒 4 次以上相对很少吃，总死亡率风险比 0.77（95% CI 0.66–0.90），心血管死亡 0.66（0.50–0.86）","grade":"B","src":"Bonaccio M, Di Castelnuovo A, Costanzo S, et al. (2019). Chili Pepper Consumption and Mortality in Italian Adults. Journal of the American College of Cardiology, 74(25), 3139-3149. <https://doi.org/10.1016/j.jacc.2019.09.068>","note":"争议。地中海饮食背景下的观察性研究，吃辣的人可能整体饮食更接近传统模式。有胃食管反流、痔疮、肠易激的人吃辣会加重症状，不必勉强","money":"0","time":"少","will":"否","level":"大","lens":"死亡率","dispute":true,"todo":false,"ratio":"极高"},{"id":"2.30","sec":2,"n":30,"title":"每天喝一两份奶或酸奶","cost":"每天几元","human":"每天喝两份以上奶或酸奶的人，同期死亡的概率比不喝的人低约 17%。","gain":"21 国 13.6 万人、平均随访 9.1 年、6796 例死亡的 PURE 队列：每天两份以上奶制品相对不吃，总死亡率风险比 0.83（95% CI 0.72–0.96，趋势 P=0.0052）","grade":"B","src":"Dehghan M, Mente A, Rangarajan S, et al. (2018). Association of dairy intake with cardiovascular disease and mortality in 21 countries from five continents (PURE): a prospective cohort study. Lancet, 392(10161), 2288-2297. <https://doi.org/10.1016/S0140-6736(18)31812-9>","note":"争议。PURE 纳入大量中低收入国家，那里能天天喝奶本身就是经济条件的标志，混杂很难排干净。乳糖不耐受的人换酸奶或低乳糖奶，不必硬喝","money":"少","time":"少","will":"否","level":"大","lens":"死亡率","dispute":true,"todo":false,"ratio":"高"},{"id":"2.31","sec":2,"n":31,"title":"鸡蛋不用戒，但别每天三四个","cost":"0 元","human":"每天多吃半个全蛋，同期死亡的概率高约 7%；把这半个换成蛋清、鱼、禽肉或坚果，各项死亡风险反而都更低。不用戒蛋，别每天三四个而已。","gain":"美国 52.1 万人队列、12.9 万例死亡：每天多吃半个全蛋，总死亡率风险比 1.07（95% CI 1.06–1.08）；把半个全蛋换成等量蛋清、禽肉、鱼、奶制品或坚果豆类，总死亡率、心血管、癌症和呼吸系统死亡率都更低","grade":"B","src":"Zhuang P, Wu F, Mao L, et al. (2021). Egg and cholesterol consumption and mortality from cardiovascular and different causes in the United States: A population-based cohort study. PLoS Medicine, 18(2), e1003508. <https://doi.org/10.1371/journal.pmed.1003508>","note":"争议大。也有大型队列和荟萃分析没发现鸡蛋与死亡率相关，美国膳食指南已取消胆固醇的每日上限。本条只反对每天三四个，一天一个不必焦虑","money":"0","time":"少","will":"否","level":"小","lens":"死亡率","dispute":true,"todo":false,"ratio":"一般"},{"id":"2.32","sec":2,"n":32,"title":"有条件就泡澡，别只冲淋浴","cost":"水费电费；每次半小时","human":"几乎每天泡澡的人，心血管事件的风险比每周泡不到两次的人低约 28%，脑出血低约 46%。","gain":"日本 3.0 万人、19 年随访、2097 例心血管事件：几乎每天泡澡相对每周不超过两次，心血管事件风险比 0.72（95% CI 0.62–0.84），冠心病 0.65（0.45–0.94），脑卒中 0.74（0.62–0.87），脑出血 0.54（0.40–0.73）","grade":"B","src":"Ukai T, Iso H, Yamagishi K, et al. (2020). Habitual tub bathing and risks of incident coronary heart disease and stroke. Heart, 106(10), 732-737. <https://doi.org/10.1136/heartjnl-2019-315752>","note":"争议。日本人群和浴缸文化下的结果，中国多数家庭没有条件天天泡。水温过高、泡太久对老年人和有心脑血管病的人反而危险，日本每年有大量老人在浴缸内猝死","money":"少","time":"中","will":"否","level":"大","lens":"死亡率","dispute":true,"todo":false,"ratio":"高"}]},{"n":3,"title":"不要浪费精力","intro":"本节只算精力和时间账：每天可用的注意力、反应速度、错误率、被打断后的恢复时间。所有数字都来自实验或队列研究里的直接测量，不换算成寿命或死亡率。多数条目证据等级是 B，这是这个领域的常态，不代表建议不成立。第 20 条讲的是和机构打交道时的预期，引的是法规而不是实验，等级记 C；第 15、23 两条引的是死亡率与自杀风险的数字，口径与本节其余条目不同，不放在一起比较。","entries":[{"id":"3.1","sec":3,"n":1,"title":"关掉非必要通知，工作时把手机放到视线之外","cost":"几分钟设置；几乎不需要毅力","human":"手机响一下，哪怕你没看没碰，注意力任务的成绩也会掉，掉的幅度和真去接电话、发短信差不多；甚至只是手机搁在桌上、你忍住不看，脑子能用的余量也变少，越离不开手机的人掉得越多。","gain":"只是收到通知（不看不碰）就显著拉低注意力任务成绩，效应量与实际接打电话或发短信相当（实验室，大学生）；两项实验显示，即便成功克制住不去看手机，自己的手机在场本身就会降低可用认知容量，手机依赖强的人下降最多","grade":"B","src":"Stothart, Mitchum & Yehnert (2015). The attentional cost of receiving a cell phone notification. Journal of Experimental Psychology: Human Perception and Performance. <https://doi.org/10.1037/xhp0000100>；Ward, Duke, Gneezy & Bos (2017). Brain Drain: The Mere Presence of One's Own Smartphone Reduces Available Cognitive Capacity. Journal of the Association for Consumer Research. <https://doi.org/10.1086/691462>","note":"都是单次实验室任务，日常工作中的累积效应没有直接测量。真正需要随叫随到的岗位可以只留少数联系人的通知","money":"0","time":"少","will":"否","level":"中","lens":"时间","dispute":false,"todo":false,"ratio":"高"},{"id":"3.2","sec":3,"n":2,"title":"固定起床时间，周末也一样","cost":"不花钱；周末少睡懒觉，需要一点毅力","human":"作息最乱的那五分之一人，生物钟比最规律的那五分之一晚了约 2.5 小时——等于长期活在时差里。作息越规律的学生，成绩也越好。","gain":"61 名大学生记录 30 天，作息最不规律的五分之一比最规律的五分之一昼夜节律晚约 2.5 小时（褪黑素起始 00:08 vs 21:32），睡眠倾向高峰晚约 1.8 小时；作息规律性与学业成绩正相关（r = 0.37）","grade":"B","src":"Phillips et al. (2017). Irregular sleep/wake patterns are associated with poorer academic performance and delayed circadian and sleep/wake timing. Scientific Reports. <https://doi.org/10.1038/s41598-017-03171-4>","note":"单一队列、观察性、样本小。模型分析提示节律差异主要来自光照模式不同，所以固定起床时间要配合早上见光才有效","money":"0","time":"少","will":"些","level":"中","lens":"时间","dispute":false,"todo":false,"ratio":"一般"},{"id":"3.3","sec":3,"n":3,"title":"每晚睡够 7 到 8 小时，别把 6 小时当作够用","cost":"每天多留 1 到 2 小时给睡眠","human":"连着两周每晚只睡 6 小时，脑子的表现会掉到相当于两天两夜没合眼的水平。麻烦的是自己感觉不到：主观困倦头几天涨完就不再涨，睡 6 小时的人和睡 4 小时的人自评一样困。所以「我睡 6 小时够用」这句话本身就是缺觉的症状。","gain":"48 名 21 到 38 岁健康成人连续 14 天每晚只睡 6 小时，认知表现累计下降到相当于连续 2 晚完全不睡的水平；而主观困倦评分只在头几天上升，之后几乎不再增加，6 小时组和 4 小时组的主观困倦没有差别（RCT）；急性剥夺睡眠（不超过 48 小时）对简单注意力走神的效应量 g = -0.776，对推理准确率 g = -0.125（70 项研究荟萃分析）","grade":"A","src":"Van Dongen, Maislin, Mullington & Dinges (2003). The cumulative cost of additional wakefulness. Sleep. <https://doi.org/10.1093/sleep/26.2.117>；Lim & Dinges (2010). A meta-analysis of the impact of short-term sleep deprivation on cognitive variables. Psychological Bulletin. <https://doi.org/10.1037/a0018883>","note":"最重要的一点是「自己觉得不困」不是睡够的证据，长期睡 6 小时的人主观上适应了，表现没有。荟萃分析针对的是急性完全剥夺，慢性限制的效应量来自单项 RCT","money":"0","time":"多","will":"些","level":"大","lens":"时间","dispute":false,"todo":false,"ratio":"一般"},{"id":"3.4","sec":3,"n":4,"title":"下午两点以后不碰咖啡因","cost":"零；习惯下午喝咖啡的人需要一点毅力","human":"睡前 6 小时喝一大杯咖啡（400 mg），当晚实测少睡 1 小时以上，而自己写的睡眠日记根本看不出差别。一杯普通咖啡（107 mg）要在睡前 8.8 小时以上喝完才不影响睡眠——十一点睡的人，下午两点就是界线。","gain":"睡前 6 小时喝 400 mg 咖啡因，客观监测的总睡眠时间比安慰剂少 1.1 到 1.2 小时，而受试者的睡眠日记没有报告出差别，即自己察觉不到；荟萃分析：咖啡因平均使总睡眠时间减少 45 分钟、睡眠效率下降 7%，一杯咖啡（107 mg）需在睡前 8.8 小时以上喝完才不影响睡眠","grade":"A","src":"Drake, Roehrs, Shambroom & Roth (2013). Caffeine effects on sleep taken 0, 3, or 6 hours before going to bed. Journal of Clinical Sleep Medicine. <https://doi.org/10.5664/jcsm.3170>；Gardiner et al. (2023). The effect of caffeine on subsequent sleep: A systematic review and meta-analysis. Sleep Medicine Reviews. <https://doi.org/10.1016/j.smrv.2023.101764>","note":"Drake 是单一实验室研究，用的 400 mg 剂量偏大（约两三杯咖啡）。对咖啡因代谢慢的人截止时间要更早。收益口径是睡眠时长，和第 3 条（每晚睡够 7 到 8 小时）叠加","money":"0","time":"少","will":"些","level":"大","lens":"时间","dispute":false,"todo":false,"ratio":"高"},{"id":"3.5","sec":3,"n":5,"title":"把邮件和消息改成每天固定几次批量处理","cost":"不花钱；需要和同事说明回复节奏；毅力中等","human":"同一批人对比两周：把邮件限制成每天只查 3 次的那周，日常压力明显更低，而收发的邮件数量一样多。不限制的时候，人平均每天要查 15.5 次。","gain":"124 名成年人两周内自身对照，限制为每天查 3 次邮件的那周，日常压力显著低于不限次数那周（Cohen's d = 0.37），收到和回复的邮件数量两周并无差别；基线时人们平均每天查邮件 15.5 次","grade":"B","src":"Kushlev & Dunn (2015). Checking email less frequently reduces stress. Computers in Human Behavior. <https://doi.org/10.1016/j.chb.2014.11.005>","note":"单一研究，效应量中等偏小，结果指标是压力而非产出。即时消息未直接研究，只能类推","money":"0","time":"少","will":"些","level":"中","lens":"时间","dispute":false,"todo":false,"ratio":"一般"},{"id":"3.6","sec":3,"n":6,"title":"做需要连续思考的工作时，把哪怕几秒钟的打断也挡在外面","cost":"关门、戴耳机或挂个「勿扰」牌；不花钱","human":"一次平均 2.8 秒的打断，就让接下来的操作出错概率翻倍；4.4 秒的打断翻三倍。现场跟踪则显示，被打断的那件事平均要 25 分钟才回得来，中间还插进两件别的事。被打断的人干得更快，但压力、挫败感和费劲程度全都更高。","gain":"平均 2.8 秒的打断使序列任务的步骤错误率翻倍，4.4 秒的打断使其翻三倍（实验室）；24 名信息工作者的现场观察：平均每 11 分钟切换一次工作主题，57% 的工作主题被打断，当天恢复被打断工作平均要 25 分 26 秒，中间还插了 2.26 个别的事；被打断的人做得更快但报告更高的压力、挫败感、时间压力和努力度（48 人实验）","grade":"B","src":"Altmann, Trafton & Hambrick (2014). Momentary interruptions can derail the train of thought. Journal of Experimental Psychology: General. <https://doi.org/10.1037/a0030986>；Mark, Gonzalez & Harris (2005). No task left behind? Examining the nature of fragmented work. CHI 2005. <https://doi.org/10.1145/1054972.1055017>；Mark, Gudith & Klocke (2008). The cost of interrupted work: More speed and stress. CHI 2008. <https://doi.org/10.1145/1357054.1357072>","note":"现场研究把打断分为外部打断和自己发起的内部打断两类，关门只挡得住前者，配合第 1、5 条（关掉非必要通知、批量处理消息）使用","money":"0","time":"少","will":"否","level":"大","lens":"时间","dispute":false,"todo":false,"ratio":"极高"},{"id":"3.7","sec":3,"n":7,"title":"一次只做一件事，不要边开会边回消息","cost":"零；需要一点毅力","human":"任务一切换，反应就更慢、更容易错。经常同时开好几个屏的人并没有练出多任务的本事，反而在任务切换测试上表现更差。","gain":"任务切换后的反应明显更慢、更容易出错（综述）；重度媒体多任务者更容易被无关刺激和无关记忆干扰，在任务切换测试上反而表现更差（实验室，大学生）","grade":"B","src":"Monsell (2003). Task switching. Trends in Cognitive Sciences. <https://doi.org/10.1016/S1364-6613(03)00028-7>；Ophir, Nass & Wagner (2009). Cognitive control in media multitaskers. PNAS. <https://doi.org/10.1073/pnas.0903620106>","note":"切换成本的具体百分比高度依赖任务类型，这里不给统一数字。Ophir 是横断面比较，无法区分「多任务导致注意力差」还是「注意力差的人更爱多任务」","money":"0","time":"少","will":"些","level":"中","lens":"时间","dispute":false,"todo":false,"ratio":"一般"},{"id":"3.8","sec":3,"n":8,"title":"睡前一小时不看发光屏幕，要看就看纸书或墨水屏","cost":"不花钱；需要毅力","human":"睡前读发光屏幕，比读纸书晚约 10 分钟才睡着，褪黑素被压低 55%，第二天生物钟往后推 1.5 小时以上，早上更困、要更久才清醒。","gain":"实验室交叉试验，睡前读发光电子书比读纸书入睡慢约 10 分钟（25.7 vs 15.8 分钟），晚间褪黑素被压低 55%，次日昼夜节律推迟超过 1.5 小时（褪黑素起始 22:31 vs 21:01），第二天早上更困、要更长时间才完全清醒","grade":"B","src":"Chang, Aeschbach, Duffy & Czeisler (2015). Evening use of light-emitting eReaders negatively affects sleep, circadian timing, and next-morning alertness. PNAS. <https://doi.org/10.1073/pnas.1418490112>","note":"样本小，实验室受控条件，日常手机亮度和时长下效应可能更小。手机夜间模式能减少多少没有在本研究中测量","money":"0","time":"少","will":"是","level":"中","lens":"时间","dispute":false,"todo":false,"ratio":"一般"},{"id":"3.9","sec":3,"n":9,"title":"到点就睡，不为游戏、短视频、色情内容熬夜","cost":"不花钱；需要长期对抗「再看一集」的惯性，手机不进卧室最省力","human":"2025 年中国人夜间平均睡 6.97 小时，平均 0:10 才入睡。睡前用手机平板的人，睡不够的概率是两倍多，白天犯困的概率是 2.7 倍；设备只是放在卧室里不用，数字也差不多——所以最省事的办法是手机不进卧室。","gain":"2025 年我国居民夜间平均睡眠 6.97 小时、平均入睡时间 0:10（中国睡眠研究会）。睡前用便携设备与睡不够（OR 2.17）、睡眠质量差（OR 1.46）、白天嗜睡（OR 2.72）相关，设备只是放在卧室里不用也一样（OR 1.79/1.53/2.27）（20 项横断面研究、125198 名儿童青少年的荟萃分析）；844 名 18 到 94 岁成人中，关灯后仍用手机的人入睡更慢、睡眠效率更低、白天更疲劳（横断面）","grade":"B","src":"Carter et al. (2016). Association Between Portable Screen-Based Media Device Access or Use and Sleep Outcomes. JAMA Pediatrics. <https://doi.org/10.1001/jamapediatrics.2016.2341>；Exelmans & Van den Bulck (2016). Bedtime mobile phone use and sleep in adults. Social Science & Medicine. <https://doi.org/10.1016/j.socscimed.2015.11.037>；中国睡眠研究会 (2026). 2026 中国睡眠健康研究白皮书（福建省卫健委转载健康报报道）. <https://wjw.fujian.gov.cn/jggk/csxx/xcc/mtbd/202603/t20260323_7114382.htm>","note":"争议：熬夜本身的代价见本节第 3 条（每晚睡够 7 到 8 小时）；色情内容对普通人精力和认知的影响没有可靠的因果证据，一项系统综述加荟萃分析认为「色情问题」更多来自个人观念与行为的不一致而非内容本身（Grubbs et al. 2019, <https://doi.org/10.1007/s10508-018-1248-x>），另一项汇总 280 名男性数据的研究发现观看时长与伴侣性生活中的勃起功能无关（Prause & Pfaus 2015, <https://doi.org/10.1002/sm2.58>）；本条针对的只是它挤占睡眠时间。TODO（待核实：中国睡眠研究会官网原文页为动态加载未能抓取，数字以省卫健委转载为准）","money":"0","time":"少","will":"是","level":"大","lens":"时间","dispute":true,"todo":true,"ratio":"高"},{"id":"3.10","sec":3,"n":10,"title":"深夜不做重大决定、不发要紧的消息","cost":"不花钱；只是把事情推到睡醒之后","human":"熬到 49.5 小时没睡的人做风险决策实验，睡饱时能很快学会躲开高风险的选项，缺觉之后反而一次次挑高风险的，年纪越大受影响越明显。这测的是连续两晚不睡的极端情况，少睡几小时有多大影响没直接测过，但方向上值得把要紧的决定推到第二天。","gain":"34 名健康人在 49.5 小时不睡后做爱荷华赌博任务（一种衡量风险决策的实验），休息充足时能很快学会避开高风险选项，缺觉后反而更多地选高风险选项，年纪大的人受影响更大（实验，单一研究）","grade":"B","src":"Killgore, Balkin & Wesensten (2006). Impaired decision making following 49 h of sleep deprivation. Journal of Sleep Research. <https://doi.org/10.1111/j.1365-2869.2006.00487.x>","note":"研究的是连续两晚不睡的极端情况，普通熬夜到凌晨两点的效应没有直接测量；「不发消息」部分是经验（C），第二天再发也不迟","money":"0","time":"少","will":"些","level":"小","lens":"时间","dispute":false,"todo":false,"ratio":"一般"},{"id":"3.11","sec":3,"n":11,"title":"下午困了就睡 10 分钟，不要睡半小时","cost":"10 分钟加一个能躺或趴的地方","human":"10 分钟的小睡当场就能提神，效果能撑两个半小时；睡 5 分钟基本没用；睡 20 分钟要等半小时后才见效；睡 30 分钟醒来先有一段发懵，那阵子表现比不睡还差。","gain":"前一晚睡眠受限后，10 分钟小睡立刻改善困倦、疲劳、精力和认知表现，部分收益维持到 155 分钟后；5 分钟几乎没有收益；20 分钟的收益要等 35 分钟后才出现；30 分钟小睡后先有一段睡眠惰性（醒来后表现反而更差），之后才改善","grade":"B","src":"Brooks & Lack (2006). A brief afternoon nap following nocturnal sleep restriction: Which nap duration is most recuperative? Sleep. <https://doi.org/10.1093/sleep/29.6.831>","note":"单一实验室研究，健康年轻人。睡不着也不必勉强，闭眼躺 10 分钟本身没有研究支持的收益","money":"0","time":"少","will":"否","level":"中","lens":"时间","dispute":false,"todo":false,"ratio":"高"},{"id":"3.12","sec":3,"n":12,"title":"在开放式办公室工作时用耳塞或找安静房间做需要记忆的活","cost":"耳塞几十元；预订会议室要花点时间","human":"背景噪音从 39 分贝涨到 51 分贝，能记住的词就变少、人更累、也更不想干活。休息时看带声音的自然风光片，比接着听办公室噪音更能把精力找回来。","gain":"学生在模拟开放办公室工作，背景噪音从 39 dB 升到 51 dB（LAeq）时，记住的词更少、自评更疲劳、动机下降；休息时看带声音的自然影片比只听河流声或办公室噪音更能恢复精力评分","grade":"B","src":"Jahncke, Hygge, Halin, Green & Dimberg (2011). Open-plan office noise: Cognitive performance and restoration. Journal of Environmental Psychology. <https://doi.org/10.1016/j.jenvp.2011.07.002>","note":"单一实验室研究。噪音的主要危害来自能听清内容的人声，白噪音耳机对这一点有帮助，但本研究没有测试耳机","money":"少","time":"少","will":"否","level":"小","lens":"时间","dispute":false,"todo":false,"ratio":"一般"},{"id":"3.13","sec":3,"n":13,"title":"每周工作时间不要超过 49 小时","cost":"可能少加班费，或者和上级谈判的成本","human":"一战英国军工厂的产出记录：每周 49 小时以内，干多久出多少活；超过 49 小时，增速就开始往下掉，一周干 70 小时和干 56 小时的产出几乎一样——多干的那 14 小时是白干。","gain":"一战时期英国军工厂工人的产出记录：每周 49 小时以内，产出与工时成正比；49 小时以上，产出增速递减，约 63 小时达到最大，70 小时的产出与 56 小时几乎没有差别，即多干的 14 小时是白干","grade":"B","src":"Pencavel (2015). The Productivity of Working Hours. The Economic Journal. <https://doi.org/10.1111/ecoj.12166>","note":"数据来自体力劳动、百年前的工厂、以女性为主，阈值对脑力工作不一定相同，作者自己也说其他工种可能更高或更低。方向性结论（超过某个点边际产出趋零）比具体的 49 这个数字可靠","money":"少","time":"少","will":"些","level":"大","lens":"时间","dispute":false,"todo":false,"ratio":"高"},{"id":"3.14","sec":3,"n":14,"title":"发现自己在反复回想同一件糟心事时，换个需要动手的活","cost":"不花钱；需要察觉自己在反刍，这本身要练习","human":"反复回想同一件糟心事不会想出答案，只会加重抑郁、把负面念头钉得更牢、让人更解决不了问题、也更难真动手，还会把身边愿意听你说的人耗光。察觉到自己在原地绕，就去干点要动手的活。","gain":"综述：反刍思维加重抑郁、强化负面思考、损害问题解决能力、妨碍实际行动、消耗社会支持；与焦虑、暴食、酗酒、自伤相关","grade":"B","src":"Nolen-Hoeksema, Wisco & Lyubomirsky (2008). Rethinking Rumination. Perspectives on Psychological Science. <https://doi.org/10.1111/j.1745-6924.2008.00088.x>","note":"这是精力口径里最难量化的一条，综述给的是方向而非数字。「换个活」是作者的经验做法，文献支持的是分散注意力优于继续反刍，具体做什么活没有比较研究","money":"0","time":"少","will":"些","level":"中","lens":"时间","dispute":false,"todo":false,"ratio":"一般"},{"id":"3.15","sec":3,"n":15,"title":"把「事情肯定会更糟」这类念头当症状看，不当事实看","cost":"0 元","human":"一项随访 20 年的双生子研究里，悲观程度每高一个档，同期死亡的概率高约 13%，心血管死亡高约 20%；反过来，乐观得分高并没有带来相应的好处。所以要处理的是悲观，不是「不够正能量」。","gain":"澳大利亚 2978 名 50 岁以上双生子、平均随访 20 年、1068 例死亡：悲观量表每高 1 个标准差，总死亡率风险比 1.134（95% CI 1.065–1.207，P=8.85×10⁻⁵），心血管死亡 1.196（1.045–1.368，P=0.0093），与癌症死亡无关；乐观得分与死亡率没有显著关联","grade":"B","src":"Whitfield JB, Zhu G, Landers JG, Martin NG (2020). Pessimism is associated with greater all-cause and cardiovascular mortality, but optimism is not protective. Scientific Reports, 10, 12609. <https://doi.org/10.1038/s41598-020-69388-y>","note":"争议。观察性研究，作者用「若是疾病导致悲观，癌症死亡也应相关」来反驳反向因果，但残余混杂仍在。注意乐观没有保护作用，所以不必强迫自己「积极思考」，要做的是别把悲观预期当成对未来的准确预测","money":"0","time":"少","will":"些","level":"中","lens":"死亡率","dispute":true,"todo":false,"ratio":"一般"},{"id":"3.16","sec":3,"n":16,"title":"减少让你消耗的人际关系，学会拒绝不想接的请求","cost":"短期社交摩擦，可能失去部分关系；需要相当的毅力","human":"一个消耗你的人造成的损失，比一个支持你的人带来的好处更大、也更一致。所以先做减法，再做加法。","gain":"120 名 60 到 89 岁丧偶女性的调查：负面社交互动与心理幸福感的关联比正面互动更一致、更强，即一个消耗你的人造成的损失大于一个支持你的人带来的收益","grade":"C","src":"Rook (1984). The negative side of social interaction: Impact on psychological well-being. Journal of Personality and Social Psychology. <https://doi.org/10.1037/0022-3514.46.5.1097>","note":"样本特殊且是横断面数据，结果指标是幸福感而非精力，放在本节是作者的推断。哪些关系算「消耗」没有客观标准，只能自己判断","money":"0","time":"少","will":"是","level":"中","lens":"时间","dispute":false,"todo":false,"ratio":"一般"},{"id":"3.17","sec":3,"n":17,"title":"把穿什么、吃什么这类低价值决策固定下来","cost":"不花钱；前期要花一点时间定下默认选项","human":"这条没有硬证据。「做选择会耗光意志力」的原始实验在两次大规模重复里都没做出来（两千人、三千人的多实验室复制，效应基本为零）。固定穿什么吃什么仍然值得做，理由是省下那几分钟和几次纠结，不是「省意志力」。","gain":"无法量化。原始实验称做选择和自我控制会消耗一种共用的有限资源（自我损耗），但两次大规模预注册多实验室复制都没有复现：23 个实验室 2141 人，d = 0.04，95% CI [-0.07, 0.15]；36 个实验室 3531 人，d = 0.06，不显著","grade":"C","src":"Baumeister, Bratslavsky, Muraven & Tice (1998). Ego depletion: Is the active self a limited resource? Journal of Personality and Social Psychology. <https://doi.org/10.1037/0022-3514.74.5.1252>；Hagger et al. (2016). A Multilab Preregistered Replication of the Ego-Depletion Effect. Perspectives on Psychological Science. <https://doi.org/10.1177/1745691616652873>；Vohs et al. (2021). A Multisite Preregistered Paradigmatic Test of the Ego-Depletion Effect. Psychological Science. <https://doi.org/10.1177/0956797621989733>","note":"争议。「决策疲劳」在大众读物里被当成定论，但实验室证据在复制危机中基本站不住。这条保留的理由只是它成本几乎为零，且省下的时间是实打实的；别指望它能改善下午的判断力","money":"0","time":"少","will":"否","level":"小","lens":"时间","dispute":true,"todo":false,"ratio":"一般"},{"id":"3.18","sec":3,"n":18,"title":"生气时先离场，把对方当天气而不是当敌人","cost":"不花钱；当场忍住不回嘴、转身走开，事后再决定要不要处理，需要一点练习","human":"换个角度解释刚发生的事，或者站到对方立场想一下，都能实打实把情绪降下来（后者更管用）；硬压着不表现出来没有效果。另外，惩罚了冒犯者的人事后反而更久地反复想这件事，不报复的人翻篇更快——报复带来的痛快，人们事先高估了。","gain":"306 组实验比较的荟萃分析：换个角度解释发生的事（认知重评）对情绪的效应 d = 0.36，站到对方立场看 d = 0.45，转移注意 d = 0.27，硬压住感受无效（d = -0.04）；三项实验显示惩罚冒犯者的人事后反而更久地反复想对方，不惩罚的人更快「翻篇」，人们事先高估了报复带来的痛快","grade":"B","src":"Webb TL, Miles E, Sheeran P (2012). Dealing with feeling: A meta-analysis of the effectiveness of strategies derived from the process model of emotion regulation. Psychological Bulletin. <https://doi.org/10.1037/a0027600>；Carlsmith KM, Wilson TD, Gilbert DT (2008). The paradoxical consequences of revenge. Journal of Personality and Social Psychology. <https://doi.org/10.1037/a0012165>","note":"荟萃分析测的是情绪强度而非精力，效应量小到中等，报复研究是单一系列实验，所以给 B。「空船」是庄子《山木》的寓言：空船撞来不生气，船上有人才生气，撞的是同一下——这是类比，不是证据。真有损失走第 8、9 节的法律路径，比当场发作便宜得多。","money":"0","time":"少","will":"些","level":"中","lens":"时间","dispute":false,"todo":false,"ratio":"一般"},{"id":"3.19","sec":3,"n":19,"title":"情绪低落时先做性价比最高的几件事：动起来、晒太阳、按时睡、找人说、打 12356","cost":"不花钱或很少；每周几次快走、慢跑或力量训练，白天出门晒太阳，固定作息，一个电话","human":"对抑郁来说，快走和慢跑在这 218 项试验里效果最好，瑜伽和力量训练稍次，强度越大越有效；晒光照对季节性抑郁效果很强，对非季节性的也有效；网上的自助认知行为课程管用，症状偏重时有人带着做更好。想不开先打 12356。","gain":"218 项随机对照试验、14170 人的网络荟萃分析：与积极对照相比，步行或慢跑对抑郁的效应 g = -0.62（95% 可信区间 -0.80 到 -0.45），瑜伽 -0.55，力量训练 -0.49，强度越大效果越好；光照治疗荟萃分析：季节性抑郁效应量 0.84（0.60 到 1.08），非季节性抑郁 0.53（0.18 到 0.89）；互联网认知行为疗法（网上自助课程）的个体数据网络荟萃分析：有人指导和无人指导都优于对照，中重度（PHQ-9 大于 9 分）时有人指导的更好；12356 全国心理援助热线每日不少于 18 小时","grade":"A","src":"Noetel M 等 (2024). Effect of exercise for depression: systematic review and network meta-analysis of randomised controlled trials. BMJ. <https://doi.org/10.1136/bmj-2023-075847>；Golden RN 等 (2005). The efficacy of light therapy in the treatment of mood disorders: a review and meta-analysis of the evidence. American Journal of Psychiatry. <https://doi.org/10.1176/appi.ajp.162.4.656>；Karyotaki E 等 (2021). Internet-Based Cognitive Behavioral Therapy for Depression: A Systematic Review and Individual Patient Data Network Meta-analysis. JAMA Psychiatry. <https://doi.org/10.1001/jamapsychiatry.2020.4364>；国家卫生健康委 (2024). 关于应用\"12356\"全国统一心理援助热线电话号码的通知（国卫医政函〔2024〕259 号）. <https://www.gov.cn/zhengce/zhengceku/202412/content_6994470.htm>","note":"这些是轻中度抑郁的辅助手段，中重度、有自杀念头的要就医，先打 12356（见第 1 节第 25 条）。运动试验多为小样本且无法盲法，光照研究截至 2003 年且样本小，「按时睡」「找人说」是作者经验，没有单列文献。别把「动起来」当成对抑郁者的要求，能走十分钟就算数。","money":"0","time":"中","will":"些","level":"大","lens":"时间","dispute":false,"todo":false,"ratio":"高"},{"id":"3.20","sec":3,"n":20,"title":"把警察、医生、柜员当成按规则上班的人，别当成角色：能推动事情的是文书和期限，不是情绪","cost":"0 元；改的是预期和动作顺序，第一次要忍住「把道理讲到对方认同」的冲动","human":"小孩子的模型是「警察就是抓坏人的、医生就是救人的、老师天生就是老师」。成年人的模型是：他们是按岗位规则上班的人，手上的裁量被文书、期限和监督框着；个人态度是个人差异，和你这件事办不办、几天办完基本是两回事。换了模型，力气就会花到能动的地方：报警当场要受案回执，不立案要书面通知，到期按法定期限追问，不服有复议、复核和检察院立案监督（第 8 节第 37 条）；看病按分诊级别和医疗需要排队，红包想买的那个「优先」恰恰是文件里点名禁止交易的，想谢救过你的医生就走感谢信和满意度评价（第 24 节第 12 条、第 24 节第 8 条（急诊预检分诊））；想「送点东西让人家多上点心」，对办案执法的人是明文从重的行贿罪（第 8 节第 38 条）。对方态度差是另一件事，走投诉渠道，别让它把你从本来走得通的流程上带走。","gain":"把和机构打交道的动作从「求人、生气、反复复述委屈」换成「拿文书、记期限、按渠道申诉」，省下的是重复沟通和情绪反刍的时间，属于一次性的认知调整，不是每天的时间节省。可核对的锚点是这些期限本身都写在文件里：治安案件自受理之日起办案期限不超过 30 日，案情重大复杂的经上一级公安机关批准可延长 30 日；有控告人的案件决定不予立案的，不予立案通知书应当在 3 日以内送达，控告人 7 日以内可申请复议、公安机关 30 日以内作出决定，不服再 7 日以内向上一级申请复核","grade":"C","src":"公安部 (2020). 公安机关办理刑事案件程序规定（公安部令第 159 号修正后，第一百七十一、一百七十八、一百七十九条）. <http://www.gov.cn/gongbao/content/2020/content_5549884.htm>；公安部 (2013/2019 修正). 公安机关办理行政案件程序规定（公安部令第 125 号、第 149 号）. <http://www.gov.cn/gongbao/content/2013/content_2321117.htm>","note":"定 C 的理由：「很多人对机构抱着角色化的想象」这个判断本身没有直接文献，能引的只是规则那一半——期限、文书和救济渠道都是明文的，本条引的数字全部来自第 8 节第 37 条那两份公安部规章。这条不解决「对方态度差」，也不承诺「按流程走就一定办成」，它换掉的只是预期和第一步动作。银行柜员、政务窗口同理：操作留痕、要复核、出错要追责，所以该做的是留凭条、要回单、按渠道投诉，而不是凭「他会不会坑我」猜。合法的优先级都写在明处，比如急诊按病情分级而不是先来后到（第 24 节第 8 条）；遇到明显的区别对待，那是投诉和监督的对象，不是要去模仿的潜规则","money":"0","time":"少","will":"些","level":"小","lens":"时间","dispute":false,"todo":false,"ratio":"一般"},{"id":"3.21","sec":3,"n":21,"title":"别把「别人过得怎么样」当每日必读：给刷同龄人动态的应用设限或关掉","cost":"0 元；设应用限时或停用账号是几分钟的事，难的是之后不再打开，要长期对抗惯性","human":"习惯在网上往上比的人，情绪更差、自尊更低，54 个样本、三万六千多人合起来是中等强度的相关（r = 0.33），其中最强的一项是「怕被人看轻」这类感受（0.44），抑郁是 0.31。相关不等于因果，但也有随机试验：让人把 Facebook 停用四周，每天空出 60 分钟，幸福感提高 0.09 个标准差，大约相当于常规心理干预效果的四分之一到四成；另一项把三个平台各限到每天 10 分钟、做三周，孤独和抑郁都降了下来。代价要一起算：停用那四周里，受试者对时事的了解掉了 0.19 个标准差。","gain":"荟萃分析（54 个独立样本、94 个效应量、N = 36,583，三层随机效应模型）：网上向上社会比较与心理适应不良的平均相关 r = 0.330（95% CI 0.289–0.370）；按结局分，社会评价类负性情绪 0.438、焦虑 0.382、抑郁 0.306、幸福感偏低 0.268、自尊偏低 0.263；年龄、文化背景、数据采集年份均无显著调节作用，纵向研究的效应并不比横断面更强。随机对照试验（2,743 名美国 Facebook 用户中，愿意以低于 102 美元接受停用的 61% 被随机分为停用四周组与对照组）：停用为普通受试者每天空出 60 分钟，主观幸福感指数提高 0.09 个标准差（生活满意度 0.12、焦虑 0.10、抑郁 0.09、快乐 0.08，校正多重比较后仍显著），作者给的参照是正性心理干预对主观幸福感约 +0.34 个标准差、对抑郁约 -0.23 个标准差，故该效应约为常规心理干预的 25% 到 40%；同期时事知识指数下降 0.19 个标准差、政治极化指数下降 0.16 个标准差；实验结束后停用组的 Facebook 使用仍比对照低 12 分钟/天（0.31 个标准差，降幅 23%）。另一项随机对照试验：143 名本科生随机分为「Facebook、Instagram、Snapchat 每个平台每天限 10 分钟」与照常使用，三周后限时组的孤独与抑郁显著下降，两组的焦虑与错失恐惧都较基线下降","grade":"A","src":"Lei Y, Hu S, Sun Y, Zheng L (2026). \"Looking up\" linked to feeling down: a meta-analysis of online upward social comparison and psychological maladjustment. Frontiers in Psychology. <https://doi.org/10.3389/fpsyg.2026.1825169>；Allcott H, Braghieri L, Eichmeyer S, Gentzkow M (2020). The Welfare Effects of Social Media. American Economic Review, 110(3), 629–676. <https://doi.org/10.1257/aer.20190658>；Allcott H, Braghieri L, Eichmeyer S, Gentzkow M (2019). The Welfare Effects of Social Media. NBER Working Paper No. 25514（本条引用的具体数字按这一版逐字核对，刊出版的摘要不含数字）. <https://www.nber.org/papers/w25514>；Hunt MG, Marx R, Lipson C, Young J (2018). No More FOMO: Limiting Social Media Decreases Loneliness and Depression. Journal of Social and Clinical Psychology, 37(10), 751–768. <https://doi.org/10.1521/jscp.2018.37.10.751>","note":"相关那一半不能读成因果，作者自己说还需要更多纵向研究；随机试验那一半是因果，但人群是 2018 年美国中期选举前的 Facebook 用户，搬到中国的平台上属于外推，Hunt 那项只有 143 名本科生、单一研究。效应量都不大，别指望关掉应用就能解决情绪问题。这条要拦的是「看别人过得怎么样」这一类使用，和家人朋友联系、查信息、找工作不在内；真按不住就先从关推送、关「可能认识的人」和首页推荐入手。总屏幕时间的账见第 4 节第 10、11 条（短视频硬上限、不看滚动新闻），情绪低落时先做什么见本节第 19 条，靠买东西找回身份感见第 6 节第 23 条，为了「往上挪一档」多花钱见第 6 节第 24 条","money":"0","time":"少","will":"是","level":"大","lens":"时间","dispute":false,"todo":false,"ratio":"高"},{"id":"3.22","sec":3,"n":22,"title":"觉得「所有人都看见我出丑了」的时候，把这个估计除以二","cost":"0 元；只是在紧张的时候多问自己一句「他们真的看见了吗」","human":"让人穿上一件尴尬的 T 恤走进有人的房间，穿的人估计 46% 的旁观者能认出衣服上印的是谁，实际只有 23%，正好高了一倍；换成自己挑的、觉得体面的 T 恤，估计 48%、实际 8%，差了六倍。另一组研究里，人在聊完天之后普遍低估了对方有多喜欢自己，大学新生室友之间这种低估持续了好几个月。所以「刚才那句话说砸了，所有人都记住了」这个判断本身就是系统性偏高的，把它砍一半，仍然偏高。","gain":"实验一（穿印有 Barry Manilow 头像的 T 恤进入有其他参与者的房间）：穿的人平均估计 46% 的旁观者能正确指出衣服上的人，旁观者实际正确率 23%，估计值恰为实际值的两倍；逐场把估计值减去实际值，平均高估 23 个百分点（95% CI 9–38），剔除只有两名和三名旁观者的两场后为 27 个百分点（11–43）。实验二（改穿参与者自选的、自认为正面的 T 恤）：平均估计 48%，旁观者实际正确率 8%，为六倍。另一系列研究（陌生人配对交谈、大学新生室友、成人工作坊三种场景）：人们系统性低估交谈对象对自己的喜欢程度和对交谈的享受程度，作者称之为「喜欢差」；不同长度的交谈中都存在，在新生室友之间持续数月","grade":"B","src":"Gilovich T, Medvec VH, Savitsky K (2000). The spotlight effect in social judgment: An egocentric bias in estimates of the salience of one's own actions and appearance. Journal of Personality and Social Psychology, 78(2), 211–222. <https://doi.org/10.1037/0022-3514.78.2.211>；Boothby EJ, Cooney G, Sandstrom GM, Clark MS (2018). The Liking Gap in Conversations: Do People Like Us More Than We Think? Psychological Science, 29(11), 1742–1756. <https://doi.org/10.1177/0956797618783714>","note":"B 的理由：都是小样本的实验室与校园研究，场景是穿衣服和陌生人聊天，外推到「被同事议论」「在会上说错话」没有直接证据；数字只说明高估的方向和大致倍数，不是给你一个可以套的系数。这条不是说别人的看法都不重要——真正在评价你的场合（面试、答辩、考核、体检报告），评价是实打实的，该准备就准备。它针对的是日常里那种「所有人都在看我」的感觉，那部分的对手是自己的估计偏差","money":"0","time":"少","will":"些","level":"小","lens":"时间","dispute":false,"todo":false,"ratio":"一般"},{"id":"3.23","sec":3,"n":23,"title":"把「别人要求我做到完美」当症状看，不当事实看","cost":"0 元；难的是把这种念头当成需要处理的东西，而不是当成对别人真实要求的准确测量","human":"「我周围的人要求我做到完美、做不到就会被否定」这种感觉，和自杀意念的相关是 0.28；换成「我自己要求自己做到完美」，相关只有 0.10。危险的那一半不是高标准本身，是觉得标准是别人加给你的。把原本就有的自杀念头控制住之后，前一种感觉仍能预测随访时念头变多，后一种不能。它和第 15 条（把「事情肯定会更糟」当症状看）里的悲观预期一样，是可以当症状处理的东西。","gain":"荟萃分析（45 项研究、N = 11,747，人群为本科生、医学生、社区成人与精神科患者，随机效应模型）：与自杀意念的加权平均相关，完美主义担忧（社会规定型完美主义、在意犯错、对行动的怀疑、现实与标准的落差等的合集）r = .28（95% CI .24–.32，42 项研究、7,936 人），其中社会规定型完美主义单独为 r = .28（.25–.32，30 项研究、3,640 人）；完美主义追求（自我导向的完美主义与个人标准的合集）r = .10（.07–.13，31 项研究、4,588 人）；父母批评 r = .20（.11–.29）。与自杀未遂：完美主义担忧 r = .12（.07–.17，15 项研究、5,275 人），社会规定型完美主义 r = .19（.08–.29，8 项研究、689 人）。纵向部分：控制基线自杀意念后，社会规定型完美主义仍与随访时的自杀意念呈小而正的关联，自我导向与他人导向的完美主义均不显著","grade":"B","src":"Smith MM, Sherry SB, Chen S, Saklofske DH, Mushquash C, Flett GL, Hewitt PL (2018). The perniciousness of perfectionism: A meta-analytic review of the perfectionism-suicide relationship. Journal of Personality, 86(3), 522–542. <https://doi.org/10.1111/jopy.12333>","note":"B 的理由：纳入研究以横断面相关为主，相关强度中等（r 约 .28，大致只解释几个到一成的差异），结局是自杀意念与未遂这两个替代终点而不是死亡率，所以收益量级按「只有替代终点」记小；作者自己报告完美主义担忧与自杀未遂这一组有发表偏倚的迹象，用填补法补足缺失研究后结论方向不变。这条不反对高标准，也不是让人降低要求，区别在于标准从哪来、达不到时会不会觉得「我这个人就完了」。有自杀念头先打 12356、把致死手段挪远，见第 1 节第 25 条；身边人流露出这种念头时你能做什么见第 8 节第 13 条；孩子这一侧的抑郁筛查见第 30 节第 6 条","money":"0","time":"少","will":"些","level":"小","lens":"死亡率","dispute":false,"todo":false,"ratio":"一般"}]},{"n":4,"title":"不要浪费时间","intro":"本节只算时间账：每天、每周、每年能省回多少小时，或任务完成率能提高多少。不换算成寿命，也不换算成钱；涉及钱的地方只给算法，不给结论。多数条目的证据是单一研究或时间利用统计，等级以 B、C 为主。","entries":[{"id":"4.1","sec":4,"n":1,"title":"把「打算做」写成「几点、在哪、遇到什么就做什么」","cost":"每件事花 1 到 2 分钟写一句「如果……就……」（如「周二早 8 点坐到书桌前就先写引言」），零金钱","human":"把「我要做」改写成「周二早 8 点坐到书桌前就先写引言」，在 94 项检验里目标达成率明显提高，属于中到大的效果。改的只是一句话的写法，不花钱也不花力气。","gain":"荟萃分析 94 项独立检验，形成实施意图的人目标达成率提高，效应量 d = 0.65（中到大），覆盖开始行动、抵御干扰、从失败路线撤出等环节","grade":"A","src":"Gollwitzer, P. M., & Sheeran, P. (2006). Implementation intentions and goal achievement: A meta-analysis of effects and processes. Advances in Experimental Social Psychology, 38, 69–119. <https://doi.org/10.1016/S0065-2601(06)38002-1>","note":"只对自己真想做的事有效，目标本身不想要时写再多也没用；样本多为学生和健康行为研究，工作场景外推需谨慎","money":"0","time":"少","will":"否","level":"大","lens":"时间","dispute":false,"todo":false,"ratio":"极高"},{"id":"4.2","sec":4,"n":2,"title":"开工前写下退出条件","cost":"立项时花 5 分钟写清「到某日期没达到某指标就停」，零金钱；执行时需要一点面子","human":"开工前先写好「到某月某日还没达到某指标就停」。同一类研究显示，这种写法也帮人从注定失败的事上撤下来。省下的是本来还会继续往里砸的全部时间。","gain":"实施意图荟萃分析显示，预先设定的「如果……就……」同样促进「从失败路线上撤出」（disengagement from failing courses of action）；省下的是本来会继续投进去的全部时间","grade":"B","src":"Gollwitzer, P. M., & Sheeran, P. (2006). Implementation intentions and goal achievement: A meta-analysis of effects and processes. Advances in Experimental Social Psychology, 38, 69–119. <https://doi.org/10.1016/S0065-2601(06)38002-1>","note":"撤出效应在荟萃分析里是分项结论，没有单独的时间节省数字；退出条件要在情绪冷静的立项期定，事后再定会被已投入的成本带偏（见下一条）","money":"0","time":"少","will":"些","level":"大","lens":"时间","dispute":false,"todo":false,"ratio":"高"},{"id":"4.3","sec":4,"n":3,"title":"决定是否继续时，只看未来投入和未来回报，不看已投入多少","cost":"零金钱；需要接受「之前的时间已经没了」这个事实","human":"已经投进去的钱和时间会让人更想继续，这一点在 98 组数据的汇总里稳定存在。所以判断该不该接着干，只算「往后还要投多少、还能拿回多少」，别算已经花掉的。","gain":"已投入的钱、精力、时间会让人更倾向继续（沉没成本效应），98 个效应量的荟萃分析确认效应稳定存在；避开它省下的是被「不想浪费」绑住的后续时间","grade":"B","src":"Arkes, H. R., & Blumer, C. (1985). The psychology of sunk cost. Organizational Behavior and Human Decision Processes, 35, 124–140. <https://doi.org/10.1016/0749-5978(85)90049-4>；Roth, S., Robbert, T., & Straus, L. (2015). On the sunk-cost effect in economic decision-making: A meta-analytic review. Business Research, 8(1), 99–138. <https://doi.org/10.1007/s40685-014-0014-8>","note":"Arkes & Blumer 的剧院实验只核实到定性结论（付更高价买季票的人半年内看戏更多），各组场次数字待核实；Roth 等发现效应随时间推移减弱、年长者受影响更小","money":"0","time":"少","will":"些","level":"中","lens":"时间","dispute":false,"todo":true,"ratio":"一般"},{"id":"4.4","sec":4,"n":4,"title":"估工期时按过去同类任务的实际耗时估，不按计划推","cost":"零金钱；估之前花几分钟翻一下上次同类事做了多久","human":"学生估自己 33.9 天写完论文，实际用了 55.5 天，只有 29.7% 的人按自己的估计做完。被要求先回想上次同类事花了多久再估的那组，按时完成的比例从 29.3% 升到 60.0%。","gain":"学生预计 33.9 天完成论文，实际 55.5 天，只有 29.7% 按自己的估计按时完成；被要求把过去经历和当前任务挂钩后，按时完成比例从对照组 29.3% 升到 60.0%，乐观偏差消失","grade":"B","src":"Buehler, R., Griffin, D., & Ross, M. (1994). Exploring the \"planning fallacy\": Why people underestimate their task completion times. Journal of Personality and Social Psychology, 67(3), 366–381. <https://doi.org/10.1037/0022-3514.67.3.366>；Flyvbjerg, B. (2006). From Nobel Prize to project management: Getting risks right. Project Management Journal, 37(3), 5–15. <https://doi.org/10.1177/875697280603700302>；Halkjelsvik, T., & Jørgensen, M. (2012). From origami to software development: A review of studies on judgment-based predictions of performance time. Psychological Bulletin, 138(2), 238–271. <https://doi.org/10.1037/a0025996>","note":"Buehler 的样本是加拿大大学生，单研究、小样本（37 人和每组约 40 人）；参考类预测在工程项目上的做法见 Flyvbjerg；Halkjelsvik 综述指出低估比高估更常见，但效应大小随任务和研究方法变化很大","money":"0","time":"少","will":"否","level":"大","lens":"时间","dispute":false,"todo":false,"ratio":"极高"},{"id":"4.5","sec":4,"n":5,"title":"会前发议程，没议程的会不开；能站着开就站着开","cost":"组织者会前花 5 到 10 分钟写议程；站会需要参会者配合","human":"有议程的会，参会者判定更有效；实验里坐着开的会比站着开的长 34%，而决策质量没有差别。","gain":"两项调查（958 人和 292 人）中，使用议程是感知会议效果的显著预测因子；实验中 55 组坐着开会比 56 组站着开会时长多 34%，决策质量没有差别","grade":"B","src":"Leach, D. J., Rogelberg, S. G., Warr, P. B., & Burnfield, J. L. (2009). Perceived meeting effectiveness: The role of design characteristics. Journal of Business and Psychology, 24(1), 65–76. <https://doi.org/10.1007/s10869-009-9092-6>；Bluedorn, A. C., Turban, D. B., & Love, M. S. (1999). The effects of stand-up and sit-down meeting formats on meeting outcomes. Journal of Applied Psychology, 84(2). <https://doi.org/10.1037/0021-9010.84.2.277>","note":"站会实验是 5 人小组的实验室任务，长会和大型会议不宜直接外推；Leach 的结论是「感知效果」，不是客观产出","money":"0","time":"少","will":"否","level":"中","lens":"时间","dispute":false,"todo":false,"ratio":"高"},{"id":"4.6","sec":4,"n":6,"title":"砍会议数量，能用文字异步解决的不开会","cost":"需要同事和上级配合；写清楚一段文字比开口说费一点精力","human":"当天开的会越多，人越累、主观工作量越高。砍掉一个会省下的时间，就是那个会本身的长度，一分不打折。","gain":"每周工作 35 小时以上的员工中（676 人和 304 人两项调查），会议时间需求与工作态度和幸福感的关系受会议质量、任务依赖程度调节；一周日记研究显示当天开会次数越多，疲劳和主观工作量越高。省下的时间等于砍掉的会议时长本身","grade":"B","src":"Rogelberg, S. G., Leach, D. J., Warr, P. B., & Burnfield, J. L. (2006). \"Not another meeting!\" Are meeting time demands related to employee well-being? Journal of Applied Psychology, 91(1). <https://doi.org/10.1037/0021-9010.91.1.83>；Luong, A., & Rogelberg, S. G. (2005). Meetings and more meetings: The relationship between meeting load and the daily well-being of employees. Group Dynamics: Theory, Research, and Practice, 9(1). <https://doi.org/10.1037/1089-2699.9.1.58>","note":"争议：Rogelberg 2006 发现会议多少与幸福感的关系并非单向，任务高度依赖他人的岗位上会议多反而不坏；没有直接研究把「异步替代」和会议做过对照，异步替代属于作者推论","money":"0","time":"少","will":"些","level":"大","lens":"时间","dispute":true,"todo":false,"ratio":"高"},{"id":"4.7","sec":4,"n":7,"title":"把大任务拆成子任务再估时、再开工","cost":"拆分本身花 5 到 15 分钟，零金钱","human":"人估工期时不会自动把任务拆开算，先列出子任务再估就能少低估一截；拆开之后每一小步都能立刻开始，也就不那么容易拖。","gain":"人们估工期时不会自发把多面任务拆成子部分（写文献综述、写讨论、整理参考文献等），先列出子任务再估计可以减少规划谬误；拆开后每一小步都成为一个可以立刻开始的动作，也降低拖延（拖延的强预测因子包括任务厌恶感和任务延迟）","grade":"B","src":"Kruger, J., & Evans, M. (2004). If you don't want to be late, enumerate: Unpacking reduces the planning fallacy. Journal of Experimental Social Psychology, 40(5), 586–598. <https://doi.org/10.1016/j.jesp.2003.11.001>；Steel, P. (2007). The nature of procrastination: A meta-analytic and theoretical review of quintessential self-regulatory failure. Psychological Bulletin, 133(1). <https://doi.org/10.1037/0033-2909.133.1.65>","note":"Kruger & Evans 只核实到摘要的定性结论，未核实到具体百分比；拆得过细本身也耗时间，以「每个子任务能在一次坐下来的时间内完成」为度","money":"0","time":"少","will":"否","level":"中","lens":"时间","dispute":false,"todo":false,"ratio":"高"},{"id":"4.8","sec":4,"n":8,"title":"给没有外部截止的事自己定一个日期","cost":"零金钱；定了要认，否则等于没定","human":"有外部截止的学生 80.6% 能在截止前做完，而按自己预计的时间做完的只有 38.7%。完成时间几乎是被截止日期决定的，和自己估的关系不大——所以没有截止的事，自己给它定一个并且认账。","gain":"有外部截止的学生 80.6% 在截止前完成，而只有 38.7% 在自己预计的时间内完成；完成时间与截止日期强相关（r = 0.82），与自己的预计只弱相关","grade":"B","src":"Buehler, R., Griffin, D., & Ross, M. (1994). Exploring the \"planning fallacy\": Why people underestimate their task completion times. Journal of Personality and Social Psychology, 67(3), 366–381. <https://doi.org/10.1037/0022-3514.67.3.366>","note":"研究证实的是外部截止的作用，自己设的截止（时间盒、番茄钟一类）效果没有直接检验，属于类推；把自设截止告诉别人可以让它更接近外部截止","money":"0","time":"少","will":"些","level":"大","lens":"时间","dispute":false,"todo":false,"ratio":"高"},{"id":"4.9","sec":4,"n":9,"title":"用自己的时薪决定哪些家务外包","cost":"外包费用；需要先算一次账","human":"中国人平均每天花 1 小时 17 分做家务，实际动手的那部分人是 1 小时 59 分。花钱买时间的人生活满意度更高，而且同样一笔钱，买时间比买东西当下更让人开心。","gain":"中国居民家务劳动每日平均 1 小时 17 分钟，做家务的人平均 1 小时 59 分钟（2024 年调查，3.85 万户 10.7 万人）；四国 6271 人的样本里，花钱买时间的人生活满意度更高，田野实验中买时间的一次消费比买实物带来更高的当下幸福感","grade":"B","src":"Whillans, A. V., Dunn, E. W., Smeets, P., Bekkers, R., & Norton, M. I. (2017). Buying time promotes happiness. Proceedings of the National Academy of Sciences. <https://doi.org/10.1073/pnas.1706541114>；国家统计局 (2024). 第三次全国时间利用调查公报（第二号）. <https://www.stats.gov.cn/sj/zxfb/202410/t20241031_1957216.html>","note":"算法：时薪 = 一个月税后收入 ÷ 一个月实际工作小时；某项家务的外包单价低于时薪、且省下的时间你确实会用在收入或休息上，就外包。只给方法，不给结论，因为每个人的时薪和外包价不同；Whillans 的结果是幸福感口径，不是时间口径","money":"多","time":"少","will":"否","level":"大","lens":"时间","dispute":false,"todo":false,"ratio":"高"},{"id":"4.10","sec":4,"n":10,"title":"给短视频和无目的刷屏设硬上限","cost":"毅力大；需要关推送、删应用或设应用限时","human":"中国人平均每天上网 5 小时 37 分，上网的人是 6 小时 3 分；2018 年同一口径还只有 2 小时 42 分。这是本节时间账里数字最大的一项，砍掉其中一小时，一年就多出 365 小时。","gain":"中国居民互联网使用每日平均 5 小时 37 分钟，使用者平均 6 小时 3 分钟，参与率 92.9%（2024 年）；2018 年同口径为 2 小时 42 分钟。这是本节里数字最大的一项，砍掉其中一小时等于每年多出 365 小时","grade":"C","src":"国家统计局 (2024). 第三次全国时间利用调查公报（第二号）. <https://www.stats.gov.cn/sj/zxfb/202410/t20241031_1957216.html>；国家统计局 (2019). 2018年全国时间利用调查公报. <https://www.stats.gov.cn/sj/zxfb/202302/t20230203_1900224.html>；TODO（待核实：CNNIC 第55次/第56次《中国互联网络发展状况统计报告》中的网民人均每周上网时长与短视频用户规模，官方 PDF 无法提取文本，数字未核实）","note":"互联网使用时间包含工作、学习和社交，不全是浪费；C 级是因为没有研究量化「限制后省回多少并用到哪里」，只有总量统计。其中「刷别人过得怎么样」这一类有随机试验测过省回多少、情绪变了多少，见第 3 节第 21 条","money":"0","time":"少","will":"是","level":"大","lens":"时间","dispute":false,"todo":true,"ratio":"高"},{"id":"4.11","sec":4,"n":11,"title":"不看电视和滚动新闻，需要的信息定时集中看","cost":"毅力中等；可能错过一些即时消息","human":"美国 15 岁以上的人每天看 2.6 小时电视，占掉全部闲暇的一半；中国人平均 1 小时 40 分，75 到 84 岁的老人 3 小时 16 分。要看的信息定时集中看，省下的是这一整块。","gain":"美国 15 岁以上人群看电视每天 2.6 小时，占全部休闲时间（5.2 小时）的一半（2025 年）；中国居民看电视每天平均 1 小时 40 分钟，75 到 84 岁人群 3 小时 16 分钟（2018 年）","grade":"C","src":"U.S. Bureau of Labor Statistics (2026). American Time Use Survey — 2025 Results. <https://www.bls.gov/news.release/atus.nr0.htm>；国家统计局 (2019). 2018年全国时间利用调查公报. <https://www.stats.gov.cn/sj/zxfb/202302/t20230203_1900224.html>","note":"只有总量统计，没有研究量化减少看电视/新闻后时间被用去了哪里；「集中看」的做法是作者经验","money":"0","time":"少","will":"些","level":"大","lens":"时间","dispute":false,"todo":false,"ratio":"高"},{"id":"4.12","sec":4,"n":12,"title":"花一次时间学常用软件的键盘快捷键和自动化","cost":"一次性投入几小时到几十小时；初期比用鼠标慢","human":"多数用了很多年 Word 的人仍然在点工具栏，而对照实验里快捷键是三种操作方式中最快的。学一次是一次性成本，之后每天每次操作都在回本，做同一类工作越久赚得越多。","gain":"251 名有经验的 Word 用户中，多数人很少使用更高效的快捷键，仍以图标工具栏为主；对照实验确认快捷键是三种方式中最快的。省回的时间随每天操作次数累积，长期做同一类工作的人收益最大","grade":"B","src":"Lane, D. M., Napier, H. A., Peres, S. C., & Sándor, A. (2005). Hidden costs of graphical user interfaces: Failure to make the transition from menus and icon toolbars to keyboard shortcuts. International Journal of Human-Computer Interaction. <https://doi.org/10.1207/s15327590ijhc1802_1>","note":"效率实验只有 6 名参与者，摘要没有给出每次操作节省的秒数；只学每天用到十次以上的操作，学得太全是另一种浪费","money":"0","time":"中","will":"些","level":"中","lens":"时间","dispute":false,"todo":false,"ratio":"一般"},{"id":"4.13","sec":4,"n":13,"title":"选住处时把通勤时长放在前面，缩短单程通勤","cost":"高，可能是更高房租或更小的房子，搬家本身也耗时","human":"通勤越长的人主观幸福感越低，而且这笔损失并没有在工资或者住房上被补回来。单程少 30 分钟，一周就省出 5 小时。","gain":"中国居民交通活动每日平均 50 分钟，参与者 1 小时 2 分钟（2024 年）；德国面板数据显示通勤越长主观幸福感系统性越低，且没有在收入或住房上得到补偿；综述确认通勤满意度随时长下降，与交通方式无关。单程少 30 分钟，每周约省 5 小时","grade":"B","src":"Stutzer, A., & Frey, B. S. (2008). Stress that doesn't pay: The commuting paradox. Scandinavian Journal of Economics, 110(2), 339–366. <https://doi.org/10.1111/j.1467-9442.2008.00542.x>；Chatterjee, K., et al. (2020). Commuting and wellbeing: A critical overview of the literature with implications for policy and future research. Transport Reviews, 40(1), 5–34. <https://doi.org/10.1080/01441647.2019.1649317>；国家统计局 (2024). 第三次全国时间利用调查公报（第二号）. <https://www.stats.gov.cn/sj/zxfb/202410/t20241031_1957216.html>","note":"争议：Chatterjee 等综述指出通勤与整体生活满意度之间尚未确立一致关联，人们大体上能用更好的工作或住房换回长通勤的损失；交通活动统计包含所有出行，不只是通勤；能错峰上下班也能把同样的路程压短","money":"多","time":"中","will":"否","level":"大","lens":"时间","dispute":true,"todo":false,"ratio":"一般"}]},{"n":5,"title":"不要浪费钱","intro":"本节口径是金钱：节省比例、年化收益差、期望值，不换算成寿命或时间。凡涉及投资的条目只讲算法与已核实的历史数据，不构成投资建议。","entries":[{"id":"5.1","sec":5,"n":1,"title":"关掉所有自动续费，改为到期手动续","cost":"一次性花 10 到 20 分钟翻一遍支付宝/微信/苹果/安卓的「自动扣款」列表；此后每次续费多点一次","human":"省下的就是那些你早就不用、却还在每月扣钱的订阅。翻一遍支付宝、微信、苹果和安卓的自动扣款列表要不了 20 分钟；法规要求商家扣款前显著提醒，并且必须给你一个随时能取消的简便入口。","gain":"省下的钱等于「已不再使用却仍在扣费」的订阅总额，因人而异；监管已要求经营者在续费前显著提醒并提供「简便的随时取消」选项，取消无需额外成本（中国，2021 年起施行）","grade":"C","src":"国家市场监督管理总局 (2021, 2025 修正). 网络交易监督管理办法（总局令第 37 号，第十八条）. <https://www.samr.gov.cn/zw/zfxxgk/fdzdgknr/fgs/art/2025/art_4b47c79b8d994a42bba4835997688faa.html>","note":"确实高频使用的服务，年付通常比月付便宜，保留自动续费反而合算；本条针对的是「忘了在扣」的那部分。","money":"0","time":"少","will":"否","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"5.2","sec":5,"n":2,"title":"每年三月到六月做一次个税汇算，专项附加扣除该填的填","cost":"0 元；个人所得税 App 上十几分钟","human":"全年只干了几个月、年中换过工作、或者子女教育房贷房租赡养老人这些扣除没填的人，汇算下来通常能退到钱，手机上十几分钟。年综合所得不到 12 万、或者该补的税不到 400 元的，可以不办。","gain":"工资薪金、劳务报酬、稿酬、特许权使用费四项合并后多退少补。国家税务总局 2023 年公告延续到 2027 年 12 月 31 日的免申报口径：年综合所得收入不超过 12 万元，或者补税金额不超过 400 元的，可以不办。反过来，全年只有几个月有收入、年中换过工作、有子女教育或房贷房租赡养老人等扣除没填的，通常能退到钱","grade":"A","src":"国家税务总局 (2025). 个人所得税综合所得汇算清缴管理办法（第六条）及其解读. <https://www.gov.cn/zhengce/202502/content_7006465.htm>；财政部、税务总局 (2023). 关于延续实施个人所得税综合所得汇算清缴有关政策的公告. <https://www.gov.cn/zhengce/zhengceku/202308/content_6900594.htm>","note":"该补税的也要办，不办属于违法。专项附加扣除包括子女教育、继续教育、大病医疗、住房贷款利息、住房租金、赡养老人、3 岁以下婴幼儿照护，房贷和房租只能二选一","money":"0","time":"少","will":"否","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"5.3","sec":5,"n":3,"title":"公积金不只用来买房：租房、装修、物业费都能提，2026 年 9 月 20 日起按新条例办","cost":"办一次提取手续","human":"公积金不是只有买房才能动。新条例把能提取的情形列到九项，租房、装修自住房、交物业费都算；中心受理之后 3 天内必须给你准不准的答复。","gain":"修改后的条例把可提取情形列到九项，包括支付房租、装修自住住房、支付自住住房物业费；管理中心应当自受理申请之日起 3 日内作出准予或者不准提取的决定","grade":"A","src":"国务院 (2026). 国务院关于修改《住房公积金管理条例》的决定（国务院令第 844 号，2026 年 7 月 31 日国务院第 93 次常务会议通过，「自2026年9月20日起施行」）：修改后第二十四条「职工有下列情形之一的，可以提取职工住房公积金账户内的存储余额：（一）支付房租的；（二）购买、建造、翻建、大修自住住房的；（三）偿还购房贷款本息的；（四）装修自住住房的；（五）支付自住住房物业费的；（六）离休、退休的；（七）完全丧失劳动能力，并与单位终止劳动关系的；（八）出境定居的；（九）国务院批准的其他住房消费情形。」；第二十五条「住房公积金管理中心应当自受理申请之日起3日内作出准予提取或者不准提取的决定」；第十八条缴存比例「均不得低于职工上一年度月平均工资的5％」. <https://www.gov.cn/gongbao/2026/issue_12946/202608/content_7079363.html>","note":"账户里的钱是你的工资加单位配的那部分，放着只按很低的利率结息。条例还写明：职工死亡或者被宣告死亡的，继承人、受遗赠人可以提取余额。各地的办理材料和细则由当地管理中心定，先查本地中心的办事指南再跑。","money":"0","time":"少","will":"否","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"5.4","sec":5,"n":4,"title":"每年重算一次手机和宽带套餐，用不上的降档，运营商不给转就投诉","cost":"0 元；查一次账单十几分钟","human":"老套餐往往比现在在售的贵几十块，一年就是几百块白扔。运营商不得无正当理由拒绝或拖延携号转网，也不得单给转网用户设资费方案，卡着不放就投诉。","gain":"工信部规章明确运营商不得「无正当理由拒绝、阻止、拖延向用户提供携号转网服务」，不得「采取拦截、限制等技术手段影响携号转网用户的通信服务质量」，也不得「为携号转网用户设置专项资费方案和营销方案」。老套餐往往比在售套餐贵几十元，长期不动就是每年白扔几百元","grade":"A","src":"工业和信息化部 (2019). 携号转网服务管理规定（工信部信管〔2019〕242 号）. <http://www.gov.cn/zhengce/zhengceku/2019-11/13/content_5451483.htm>","note":"先在营业厅 App 查近半年实际用量，再按用量选套餐。客服说「降档要到营业厅」「合约期内不能改」时，要求给出书面依据，不行就打 12300 投诉","money":"0","time":"少","will":"些","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"一般"},{"id":"5.5","sec":5,"n":5,"title":"不买彩票","cost":"0 元","human":"按规定，乐透数字型彩票拿出来做奖金的下限是销售额的 50%，双色球是 51%——每投 1 元，长期平均返还 0.51 元，稳定亏掉 49%。2024 年全国卖了 6234.86 亿元，其中 1610.31 亿元直接进了公益金，不在返奖里。","gain":"按财政部规定，乐透型/数字型彩票奖金比例下限为销售额的 50%，即开型 65%，竞猜型 73%；双色球按销售额的 51% 计提奖金，每投入 1 元长期期望仅返还 0.51 元，期望亏损 49%。2024 年全国彩票销售 6234.86 亿元，其中 1610.31 亿元进入公益金，未回到购彩者手中（中国，2024 年）","grade":"A","src":"财政部 (2015). 关于规范和加强彩票资金构成比例管理的通知（财综〔2015〕94 号）. <http://m.mof.gov.cn/czxw/201511/t20151113_1560814.htm>；财政部 (2025). 财政部公告 2025 年第 8 号（2024 年彩票公益金筹集分配情况）. <http://zhs.mof.gov.cn/zhengcefabu/202508/t20250828_3970977.htm>；中国福利彩票双色球游戏规则（第十四条）. <https://mzj.nc.gov.cn/ncsmzj/flcp/202111/5dccc1a5da89434e94a62f8ea0e5887e.shtml>","note":"期望值为负是彩票制度设计的结果，不是运气问题；把它当作 2 元一次的娱乐消费、而非理财，是唯一合理的定位。","money":"0","time":"少","will":"否","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"5.6","sec":5,"n":6,"title":"看到「高收益」「保本」「稳赚」直接走开","cost":"零；只需要在听到这几个词时停下来","human":"监管部门自己的说法是：收益率超过 6% 就要打问号，超过 8% 很危险，10% 以上就要准备损失全部本金。正规理财已经不许承诺保本保收益；非法集资亏掉的钱由参与者自行承担，出事没人替你兜底。","gain":"原银保监会主席在 2018 年陆家嘴论坛上的原话：「收益率超过 6% 的就要打问号，超过 8% 的就很危险，10% 以上就要准备损失全部本金」；资管新规要求金融机构「不得承诺保本保收益」、「出现兑付困难时，金融机构不得以任何形式垫资兑付」，也就是正规理财已经没有保本一说；参与非法集资的损失「由集资参与人自行承担」，出事后没有人替你兜底（中国，2018、2021 年）","grade":"A","src":"郭树清在第十届陆家嘴论坛的讲话（2018 年 6 月），天津市地方金融管理局转载. <https://jrgz.tj.gov.cn/ztlm/ztzl/jrjfwphjr/202006/t20200625_2744709.html>；中国人民银行等 (2018). 关于规范金融机构资产管理业务的指导意见（银发〔2018〕106 号，第二条、第六条）. <https://www.gov.cn/gongbao/content/2018/content_5323101.htm>；国务院 (2021). 防范和处置非法集资条例（国务院令第 737 号，第二十五条）. <https://www.gov.cn/gongbao/content/2021/content_5588815.htm>","note":"6%/8%/10% 是监管者给出的经验阈值，不是法律条文；TODO（待核实：原银保监会官网的讲话原文页为动态加载未能抓取，引句以天津市地方金融管理局转载为准）。不构成投资建议。","money":"0","time":"少","will":"否","level":"大","lens":"金钱","dispute":false,"todo":true,"ratio":"极高"},{"id":"5.7","sec":5,"n":7,"title":"不用信用卡最低还款，不为消费开分期或消费贷","cost":"零；需要在账单日前留足全额还款的现金","human":"最低还款不是优惠，是一笔按日计息的贷款，折合年化 18% 上下，而且免息期当场作废、剩余本金全额计息。看利率认年化——央行已经要求发卡机构必须明显展示年化利率，不许只写「日利率」。","gain":"信用卡透支利率 2020 年前以「日利率万分之五」为上限、其 0.7 倍为下限，折合单利年化 18.25%（2021 年起改为发卡机构与持卡人协商定价）；最低还款后剩余本金按日全额计息，免息期同时失效。央行已要求发卡机构必须以明显方式展示年化利率，「不得仅展示日利率、日还款额」，看年化数字再决定（中国，2020 年通知）","grade":"C","src":"中国人民银行 (2020). 关于推进信用卡透支利率市场化改革的通知（银发〔2020〕327 号）. <https://xining.pbc.gov.cn/zhengwugongkai/4081330/4406346/4693549/4159909/index.html>","note":"18.25% 由「万分之五 × 365」算得，为单利口径，按月计复利会更高；个别银行有折扣，以自己账单上公示的年化利率为准。真周转不开时，优先找利率更低的正规渠道，不要拖着最低还款滚利息。","money":"0","time":"少","will":"些","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"一般"},{"id":"5.8","sec":5,"n":8,"title":"不给主播打赏、不给游戏充值、不冲动下单","cost":"零；一次花几分钟关掉免密支付、设单笔和每日限额、删掉平台里绑定的支付方式","human":"2024 年国内游戏收入 3257.83 亿元、6.74 亿用户，人均约 480 元。钱花出去基本追不回来：法律只支持未成年人未经家长同意的那部分退款，成年人没有这一条。最省力的防线是关掉免密支付、设单笔和每日限额、把支付方式解绑。","gain":"这是一笔很大的支出：2024 年国内游戏市场实际销售收入 3257.83 亿元，用户 6.74 亿人，人均约 480 元（由前两数相除算得）。花出去的钱基本追不回：只有限制民事行为能力人（未成年人）未经监护人同意的打赏和充值，监护人请求返还时「人民法院应予支持」；成年人的打赏和充值没有这样的规定。未成年人玩网络游戏本来就只有周五、周六、周日和法定节假日 20 时至 21 时各 1 小时（中国，2020、2021 年）","grade":"B","src":"国家新闻出版署 (2024). 今年中国游戏市场收入超 3257 亿元创新高（中国音数协游戏工委《2024 年中国游戏产业报告》）. <https://www.nppa.gov.cn/xxfb/ywdt/202412/t20241216_877445.html>；最高人民法院 (2020). 关于依法妥善审理涉新冠肺炎疫情民事案件若干问题的指导意见（二）（法发〔2020〕17 号，第 9 条）. <https://www.court.gov.cn/zixun/xiangqing/230181.html>；国家新闻出版署 (2021). 关于进一步严格管理 切实防止未成年人沉迷网络游戏的通知（国新出发〔2021〕14 号）. <https://www.nppa.gov.cn/xxfb/tzgs/202108/t20210830_666285.html>","note":"B 级是因为没有「不打赏能省多少」的直接测量，只有总量数字；关免密、设限额是经验做法（C）。民法典第十九条、第一百四十五条的原文已在下一条逐字引出。不构成投资建议。","money":"0","time":"少","will":"些","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"一般"},{"id":"5.9","sec":5,"n":9,"title":"孩子用手机充值打赏，八岁以上的大额支出未经家长追认可以主张退","cost":"0 元；要花时间取证和交涉，平台通常先拒后退；谈不拢只能起诉，那是几个月起步的事，律师费自理，所以先把材料备齐、走平台和 12315 更划算","human":"八岁以上的孩子花的钱，只要金额和他的年龄智力明显不相称，家长不同意也不追认就是无效的，可以主张退；不满八岁的更是本来就不能自己做主。家长一直不表态，法律上算作拒绝追认。","gain":"八周岁以上的未成年人是限制民事行为能力人，与其年龄智力不相适应的民事法律行为，须经法定代理人同意或者追认才有效；不满八周岁的属无民事行为能力人，其行为由法定代理人代理实施。法定代理人未作表示的，视为拒绝追认","grade":"A","src":"全国人大 (2020). 民法典. 最高人民检察院转载全文. <https://www.spp.gov.cn/spp/fl/202006/t20200602_463888.shtml> 第十九条：「八周岁以上的未成年人为限制民事行为能力人，实施民事法律行为由其法定代理人代理或者经其法定代理人同意、追认；但是，可以独立实施纯获利益的民事法律行为或者与其年龄、智力相适应的民事法律行为。」第二十条：「不满八周岁的未成年人为无民事行为能力人，由其法定代理人代理实施民事法律行为。」第一百四十五条：「限制民事行为能力人实施的纯获利益的民事法律行为或者与其年龄、智力、精神健康状况相适应的民事法律行为有效；实施的其他民事法律行为经法定代理人同意或者追认后有效。」「法定代理人未作表示的，视为拒绝追认。」","note":"关键在举证：要证明操作的是孩子而不是你。有用的材料是充值时间集中在上课或家长上班时段、设备使用记录、孩子的聊天与游戏记录、以及孩子本人的说明。「与年龄智力相适应」没有统一金额线，几十元的皮肤和几万元的打赏不是一回事。事前更省力：给支付方式设免密上限、开启青少年模式、别把支付密码告诉孩子。自己冲动打赏充值的那一面见本节「不给主播打赏、不给游戏充值、不冲动下单」那条。","money":"0","time":"中","will":"些","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"一般"},{"id":"5.10","sec":5,"n":10,"title":"教孩子记一句话：任何人让你拿家长的手机去操作、去报验证码，都是骗子","cost":"0 元；给孩子讲一遍下面六类，约定一句「被骗了先跟我说，我不骂你」；同时把支付设免密上限、开青少年模式，支付密码不告诉孩子","human":"这六类骗局套路各不相同，最后一步永远是同一个动作——让孩子拿家长的手机去转账或者念验证码。所以只要教会一句就够用：谁让你动家长的手机、报验证码，谁就是骗子。再加一句「被骗了先跟我说，我不骂你」，孩子才敢当天说，钱才有可能追回来。","gain":"泉州市反诈骗中心联合泉州市教育局拆的六类青少年骗局，套路各异但最后一步是同一个动作——让孩子拿家长的手机转账：游戏账号装备低价私下交易（小王私下转 260 元后被告知「未成年人转账违规，账号要冻结」，用爸爸手机点「核查链接」，账户 3 万多元被转走）；「解除防沉迷」（威胁「不转账取消，你家长要坐牢」，用妈妈手机转了 7000 元；原文写明防沉迷是官方设定，「根本没有『私下解锁』渠道」）；打赏退款（冒充「官方客服」说未成年人打赏能退，要求「用家长支付宝给指定直播间刷礼物才能退款」，妈妈账户 7.3 万元被打赏后拉黑；原文「有人加你让你『刷礼物退款』，100% 是诈骗」）；冒充同学或老师（盗号后发语音报名字借钱；开学季混进班级群冒充老师发「交学杂费 500 元」，头像昵称一样，还安排「托」说「已交」）；追星（拉进「明星粉丝群，领 888 元红包」，先转 48.88 元「验证」，再吓唬「未成年人参与违规，平台要冻结 8 万，家长要坐牢」，共骗走 1.6 万元；原文「真警察、律师绝不会在网上联系未成年人调查，更不会要家长手机操作」）；二手平台低价商品诱导脱离平台私下转账。同一份材料还列了三条孩子自己别踩的红线：银行卡和电话卡不借不卖不租（卡被用于转移赃款可能构成帮助信息网络犯罪活动罪，留案底影响考研考公），「手机口」兼职是违法犯罪，境外「高薪招聘」可能一到境外就被控制（全国，2025 年 10 月）","grade":"B","src":"泉州市反诈骗中心 (2025). 开学第一课｜反诈是青少年的必修课，这 6 大陷阱一定要避开！<http://gat.fujian.gov.cn/ztzl/fjjffpzxrx/spjq/202510/t20251028_7026836.htm>（福建省公安厅转载）","note":"B 级原因是官方给的是话术拆解和个案，没有发案率或防范效果的统计数字。要和上一条分清：孩子自己充值打赏的钱能按民法典主张退，被骗转给骗子的钱不适用那条，只能按第 8 节第 2 条报警止付，追不追得回看钱还在不在账上。骗子吓唬孩子的核心话术是「你违规了、你家长要坐牢」，事先跟孩子说明白这句话本身就是骗局标志，比事后追问有用；「被骗了先说不骂」这句要真做到，孩子怕挨骂而隐瞒是这几个案例里损失扩大的共同原因。冒充熟人的成人版和 AI 换脸见第 8 节第 3、4 条（反诈硬规则、涉及转账先挂断）。","money":"0","time":"少","will":"些","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"5.11","sec":5,"n":11,"title":"拒绝电子产品的延长保修（延保）","cost":"零；承担保修期外自费维修的小概率支出","human":"延保一般卖到商品原价的 10% 到 50%，而它的毛利率是普通商品的十几倍——百思买 2003 年靠只占营收 3% 到 4% 的延保，赚走了一半以上的利润。这个差价就是你多付的钱。","gain":"延保定价通常为商品原价的 10% 到 50%；研究引用的行业估计称延保平均毛利率 50% 到 60%，约为普通商品毛利率的 18 倍，2003 年延保只占百思买营收的 3% 到 4% 却贡献了超过 50% 的利润（美国，2000 年代零售数据）","grade":"B","src":"Chen T, Kalra A, Sun B (2009). Why Do Consumers Buy Extended Service Contracts? Journal of Consumer Research 36(4):611-623. <https://doi.org/10.1086/605298>","note":"毛利率数字是论文转引的行业估计（Business Week 2004），非论文自己的测算；适用于自己能承担一次维修费的普通人，靠一台设备吃饭且无备机的人另算。手机碎屏险类产品要单独按自己的摔机频率算期望值。","money":"0","time":"少","will":"否","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"5.12","sec":5,"n":12,"title":"优先选通过一致性评价的仿制药和集采中选药","cost":"零；处方或购药时多问一句「有没有集采/通用名药」","human":"集采第二批平均降价 53%，最高降 93%；到 2026 年 4 月已经做了 11 批、覆盖 490 种药。开药买药时多问一句「有没有集采的、通用名的」，同样的成分能少花一大截。","gain":"国家组织药品集采第二批平均降价 53%、最高 93%；截至 2026 年 4 月已开展 11 批、覆盖 490 种药品，通过或视同通过一致性评价的药品达 1695 个，约占临床常用化学药的 2/3（中国，2020 到 2026 年官方数据）","grade":"A","src":"国家医疗保障局 (2020). 第二批国家组织药品集中采购和使用工作答记者问. <https://www.nhsa.gov.cn/art/2020/1/17/art_38_2264.html>；国家医疗保障局 (2026). 国务院政策例行吹风会：健全全周期全渠道药品价格形成机制. <http://www.nhsa.gov.cn/art/2026/4/15/art_14_20221.html>","note":"争议：集采入围以一致性评价为质量门槛，官方立场是疗效等同；部分临床医生对个别品种的实际疗效差异有质疑，但缺少可引用的系统性证据。换药前问医生，慢病长期用药尤其如此。","money":"0","time":"少","will":"否","level":"大","lens":"金钱","dispute":true,"todo":false,"ratio":"极高"},{"id":"5.13","sec":5,"n":13,"title":"在医保 App 上办一次家庭共济绑定，职工医保个人账户的钱就能给配偶、父母、子女看病买药","cost":"0 元；在参保地医保 App 或经办机构办一次家庭共济绑定","human":"办一次绑定，你职工医保个人账户里的钱就能给配偶、父母、孩子看病买药用；不办就只能自己用，钱躺在账户里。","gain":"个人账户可用于支付本人及其配偶、父母、子女在定点医疗机构就医由个人负担的医疗费用，以及在定点零售药店购买药品、医疗器械、医用耗材由个人负担的费用；文件还提出探索用于家人参加城乡居民医保的个人缴费","grade":"A","src":"国务院办公厅 (2021). 关于建立健全职工基本医疗保险门诊共济保障机制的指导意见（国办发〔2021〕14 号）第（五）项：「个人账户主要用于支付参保人员在定点医疗机构或定点零售药店发生的政策范围内自付费用。可以用于支付参保人员本人及其配偶、父母、子女在定点医疗机构就医发生的由个人负担的医疗费用，以及在定点零售药店购买药品、医疗器械、医用耗材发生的由个人负担的费用。探索个人账户用于配偶、父母、子女参加城乡居民基本医疗保险等的个人缴费。个人账户不得用于公共卫生费用、体育健身或养生保健消费等不属于基本医疗保险保障范围的支出。」<https://www.gov.cn/zhengce/zhengceku/2021-04/22/content_5601280.htm>","note":"很多人的个人账户里躺着几千元，同时家里老人在自费买药。绑定一次以后长期有效，各地叫法多为「家庭共济」，在本地医保 App 里办。注意反向的红线：个人账户不能用于健身、养生保健这类消费，拿它去药店买保健品套现属于骗保。","money":"0","time":"少","will":"否","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"5.14","sec":5,"n":14,"title":"喝烧开的自来水，不常年买瓶装水","cost":"烧水的时间和少量燃气/电费；一个水壶","human":"北京第一阶梯水价合 0.005 元一升，瓶装水按 1 元 500 毫升算是 2 元一升，差 400 倍。自来水执行的是强制性国家标准，平时烧开了喝就行；真碰上水源出事、水发臭发浑，那不是多煮几分钟能解决的，停用并反映。","gain":"北京居民第一阶梯水价 5 元/立方米，即 0.005 元/升；若瓶装水按 1 元/500 毫升计，每升 2 元，是自来水的 400 倍。生活饮用水执行强制性国家标准 GB 5749-2022（2022 年 3 月 15 日发布，2023 年 4 月 1 日起施行，主管部门为国家疾控局）（中国，2015 年水价与 2022 年标准）","grade":"C","src":"北京市发展和改革委员会. 居民用水价格表. <https://fgw.beijing.gov.cn/bmcx/djcx/jzldj/202003/t20200331_1752796.htm>；国家市场监督管理总局 国家标准全文公开系统. GB 5749-2022 生活饮用水卫生标准. <https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=99E9C17E3547A3C0CE2FD1FFD9F2F7BE>；杭州市联合调查组 (2025). 关于杭州市余杭区部分小区供水异常调查情况通报（2025 年 7 月 23 日），新华网转载 <http://www.news.cn/20250723/1be62dac3b0b4461a643791ff552e93d/c.html>；杭州市余杭区人民政府. 余杭区 2025 年 4 月／5 月／6 月水源水水质监测数据（杭州余杭水务控股集团公开，检测单位杭州嘉澍环境监测有限公司，附件 PDF 表 1 第 24 项「粪大肠菌群」） <https://www.yuhang.gov.cn/art/2025/5/8/art_1229204072_59140140.html>、<https://www.yuhang.gov.cn/art/2025/6/5/art_1229204072_59142885.html>、<https://www.yuhang.gov.cn/art/2025/7/3/art_1229204072_59146464.html>；公安部网络安全保卫局 (2025). 编造虚假「警情通报」，捏造「粪水」谣言，邵某豪被刑事拘留 <http://www.news.cn/politics/20250722/3178b3bd189c4eb4b293982e92aab438/c.html>","note":"争议在于「达标」管的是出厂水和末梢水，水源与管网出问题时会短暂失守。2025 年 7 月 16 日杭州余杭仁和水厂原水嗅味异常，仁和、良渚部分小区自来水发臭，官方结论是藻类厌氧降解产生的硫醚类物质，切换水源后出厂水总大肠菌群、大肠埃希氏菌均未检出且全分析符合 GB 5749-2022，7 名干部被问责、7 月水费全免并免费换滤芯；而同一水源的粪大肠菌群事发前已连月抬升（苕溪永胜取水口 4 月 10 个/L、5 月 7300 个/L、6 月 16000 个/L，超 GB 3838 Ⅲ 类限值 10000 个/L，同月四岭水库 28000 个/L、馒头山水库 24000 个/L 也超）。所以：烧开只杀微生物，除不掉嗅味物质和溶解性化学物，闻到异味或水发黄发浑就停用、向供水企业和 12345 反映、临时改喝瓶装水，别指望多煮几分钟压过去；但这属于局部偶发事故且当地按次赔付，仍不构成常年买瓶装水的理由。网传「粪水管接错」是伪造的警情通报，发布者已被刑事拘留（见第 9 节）。瓶装水 1 元/500 毫升是为算式设的假设价，按自己所在城市的实价重算；老旧小区二次供水设施不达标的，可以加装过滤或只在此场景买水。各地水价不同，北京数字仅作量级参考。","money":"0","time":"少","will":"否","level":"中","lens":"金钱","dispute":true,"todo":false,"ratio":"高"},{"id":"5.15","sec":5,"n":15,"title":"不频繁交易股票","cost":"零；需要克制「看到消息就想动」的冲动","human":"美国 6.6 万个账户的数据里，交易最频繁那组年化只有 11.4%，同期市场是 17.9%。差的这 6 个多百分点几乎全被交易成本吃掉——两组的毛收益其实差不多，手一动钱就少。","gain":"对 66,465 个美国折扣券商家庭账户（1991 到 1996 年）的研究：交易最频繁的一组年化收益 11.4%，同期市场 17.9%，平均家庭 16.4%；平均家庭年换手率 75%。频繁交易组与不频繁组的毛收益差别很小，差距主要来自交易成本（美国，1991 到 1996 年）","grade":"A","src":"Barber BM, Odean T (2000). Trading Is Hazardous to Your Wealth: The Common Stock Investment Performance of Individual Investors. The Journal of Finance 55(2):773-806. <https://doi.org/10.1111/0022-1082.00226>","note":"数据是美国 1990 年代的，A 股的佣金、印花税结构不同，但「换手越高、净收益越低」的机制一致。不构成投资建议。","money":"0","time":"少","will":"些","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"5.16","sec":5,"n":16,"title":"不借钱投资、不加杠杆、不买自己看不懂的","cost":"零；需要在行情好的时候忍住不「借点钱多赚一点」","human":"借钱买股票，跌破线又补不上钱就被强制平仓，浮亏当场变成实亏，连「等它涨回来」的机会都没有。监管规定开户不足半年、日均资产不到 50 万的人不能开融资账户——这个门槛本身就在说它不是给普通人用的。","gain":"杠杆把亏损放大：融资买入后，抵押物市值跌到维持担保比例线以下又没能追加担保，就会被强制平仓，浮亏当场变成实亏，没有「等它涨回来」的机会。监管规定「从事证券交易时间不足半年、缺乏风险承担能力、最近 20 个交易日日均证券类资产低于 50 万元」的客户不得开立信用账户，这个门槛本身就在说明它不是给普通人的工具（中国，2015 年）","grade":"B","src":"中国证监会 (2015). 证券公司融资融券业务管理办法（证监会令第 117 号，第十二条）. <https://www.csrc.gov.cn/csrc/c106256/c1654005/content.shtml>；上海证券交易所. 《上海证券交易所融资融券交易实施细则》解读（投资者教育材料）. <https://www.sse.com.cn/services/tradingservice/margin/edu/c/10074042/files/a1f1c4833302451fb9130dbb94116c56.pdf>","note":"「看不懂的不买」没有直接文献，是共识（C）；用消费贷、信用卡套现去投资是变相杠杆，利率见本节第 7 条。不构成投资建议。","money":"0","time":"少","will":"些","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"5.17","sec":5,"n":17,"title":"用宽基指数基金替代主动管理基金作为长期底仓","cost":"放弃「选中明星基金经理」的可能性；需要接受和指数一样的下跌","human":"主动基金整体持仓已经很接近整个市场，但多收的那笔管理费是实打实从你的净回报里扣掉的；模拟显示能赚回自己成本的基金很少。","gain":"美国主动股票型基金的整体组合接近市场组合，但主动管理的高成本原封不动地变成了投资者更低的净回报；自助法模拟显示很少有基金能产生足以覆盖成本的超额收益（美国，2010 年发表）","grade":"B","src":"Fama EF, French KR (2010). Luck versus Skill in the Cross-Section of Mutual Fund Returns. The Journal of Finance 65(5):1915-1947. <https://doi.org/10.1111/j.1540-6261.2010.01598.x>；TODO（待核实：S&P Dow Jones Indices, SPIVA U.S. Scorecard Year-End 2024，网站拒绝自动抓取，其中「长期多数主动大盘基金跑输标普 500」的具体百分比未能核对）；TODO（待核实：中国市场同类研究，未找到可引用的原始文献）","note":"争议：Harvey CR, Liu Y (2022). Luck versus Skill in the Cross Section of Mutual Fund Returns: Reexamining the Evidence. The Journal of Finance 77(3). <https://doi.org/10.1111/jofi.13123> 指出 Fama-French 的自助法存在欠采样问题，即使部分基金有显著超额收益也可能无法拒绝零假设，即「几乎没有基金有技能」的结论可能过强。中国主动基金整体是否跑输指数尚无本节可引用的原始文献。不构成投资建议。","money":"0","time":"少","will":"些","level":"大","lens":"金钱","dispute":true,"todo":true,"ratio":"高"},{"id":"5.18","sec":5,"n":18,"title":"同类基金优先选费率低的","cost":"零；申购前多看一眼「管理费 + 托管费 + 销售服务费」","human":"年费率每高 1 个百分点，20 年后到手少约 18%，30 年后少约 26%。同类基金里挑费率低的，是这件事上唯一一个你能提前确定的变量。","gain":"费率差异按复利侵蚀：年费率高 1 个百分点，20 年后终值少 0.99^20 ≈ 18.2%，30 年后少约 26%。中国 2023 年起推行公募基金费率改革，下调主动权益类基金管理费率和托管费率上限（具体上限数字待核实）","grade":"C","src":"中国证监会 (2023). 证监会有关部门负责人就公募基金费率改革答记者问. <http://www.csrc.gov.cn/csrc/c100028/c7418692/content.shtml>；Fama EF, French KR (2010). 见第 11 条. <https://doi.org/10.1111/j.1540-6261.2010.01598.x>","note":"复利算式为纯算术，假设两只基金费前收益相同；实际还要算申购费、赎回费和 C 类份额的销售服务费。不构成投资建议。","money":"0","time":"少","will":"否","level":"大","lens":"金钱","dispute":false,"todo":true,"ratio":"极高"},{"id":"5.19","sec":5,"n":19,"title":"别把钱押在一只股票、一个平台、一套房上","cost":"零；接受「不会正好押中最赚的那一个」","human":"几项资产只要不是完全同涨同跌，分开放就能在预期收益不变的前提下把波动降下来。反过来，钱全押在一只股票、一个平台、一套房上，它出事就等于你全部出事。","gain":"只要几项资产不是完全同涨同跌，把钱分开放，预期收益不变而波动更小，这是 Markowitz 1952 年提出、此后几十年沿用的组合选择基本结论；反过来，钱全在一只股票或一个平台上，它的方差就是你全部的方差，出事时没有任何对冲","grade":"B","src":"Markowitz, H. (1952). Portfolio Selection. The Journal of Finance, 7(1), 77–91. <https://doi.org/10.1111/j.1540-6261.1952.tb01525.x>","note":"B 级是因为经典文献是理论推导，没有给出「分散能少亏多少」的实证数字；分散只降波动，不保证不亏。买宽基指数基金（本节第 17 条）本身就是最省事的分散。不构成投资建议。","money":"0","time":"少","will":"些","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"5.20","sec":5,"n":20,"title":"交个税的人开个人养老金账户，每年 12000 元能在税前扣掉；不交个税的人开了不划算","cost":"0 元开户；代价是这笔钱锁到退休，中途取不出来","human":"省下的钱等于「你的边际税率减 3%」乘以实际存进去的额度：税率 10% 的人一年最多省 840 元，20% 的省 2040 元，30% 的省 3240 元。本来就不用交个税的人存了一分不省，领的时候反倒要按 3% 交，是净亏。钱锁到退休，中途取不出来。","gain":"缴费按 12000 元／年的限额，在综合所得或经营所得中据实扣除；投资环节计入账户的投资收益暂不征收个人所得税；领取时不并入综合所得，单独按 3% 计税。所以省下的是「你的边际税率减 3%」乘以实际缴费额：边际税率 10% 的人每年最多省 840 元，20% 的省 2040 元，30% 的省 3240 元；本来就不用交个税（年综合所得扣除后没到起征点）的人，缴费环节一分钱没省，领取时反而要按 3% 缴，是净亏。缴费额度按自然年度累计，次年重新计算，当年没缴满不能结转。2024 年 12 月 15 日起全国实施（全国）","grade":"A","src":"财政部、税务总局 (2024). 关于在全国范围实施个人养老金个人所得税优惠政策的公告（财政部 税务总局公告 2024 年第 21 号，2024 年 12 月 12 日）. <https://www.gov.cn/zhengce/zhengceku/202412/content_6992498.htm>；人力资源社会保障部等五部门 (2022). 个人养老金实施办法（第七、八、九、十二、十三条）. <https://www.gov.cn/zhengce/zhengceku/2022-11/05/content_5724783.htm>","note":"账户「封闭运行」，只有四种情形能领：达到领取基本养老金年龄、完全丧失劳动能力、出国（境）定居、国家规定的其他情形。所以这不是理财，是一个锁定期极长的税务安排——先确认自己的边际税率，再决定缴多少，别为了「薅羊毛」把应急金锁进去（应急金见第 27 条）。账户里的钱还要自己选产品投资，会亏，选的规则和本节第 17、18 条（宽基指数基金、优先选费率低的）一样。扣除凭证由个人养老金信息管理服务平台出具，工资薪金可以选当年预扣预缴时扣或次年汇算时扣（汇算见第 2 条）。","money":"0","time":"少","will":"否","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"5.21","sec":5,"n":21,"title":"健身房按次付费或短周期付费，除非有一年以上的稳定记录","cost":"单次价格比年卡均摊价高；需要诚实评估自己的去场频率","human":"美国那份三年数据里，选月费 70 美元以上合同的会员平均每月只去 4.3 次，折合每次 17 美元以上，而按次买 10 次卡每次只要 10 美元；他们在会籍期间平均多付了 600 美元。除非已经有一年以上稳定去的记录，否则按次或短期更划算。","gain":"对美国 3 家健身俱乐部 7,752 名会员 3 年数据的研究：选择月费超过 70 美元合同的会员平均每月只去 4.3 次，折合每次超过 17 美元，而 10 次卡只需每次 10 美元；这些用户在会籍期间平均多付 600 美元。月付会员超过一年仍未退卡的比例比年付会员高 17%（美国，三年面板数据）","grade":"B","src":"DellaVigna S, Malmendier U (2006). Paying Not to Go to the Gym. American Economic Review 96(3):694-719. <https://doi.org/10.1257/aer.96.3.694>","note":"单一研究、美国数据，但机制（高估未来自控力）普遍。已有连续一年每周两次以上记录的人，年卡确实更便宜。","money":"少","time":"少","will":"否","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"一般"},{"id":"5.22","sec":5,"n":22,"title":"交预付款要签书面合同；商家出风险要停收，跑路前你有权要回未消费的余额","cost":"0 元；难的是当场坚持要合同，不接受「先充了再说」","human":"收预付款必须签书面合同、写明怎么退。商家出现重大经营风险就该停止收款；要停业或搬走必须提前告诉你，你有权要求继续履行或者退还没消费完的余额。违反的罚违法所得 1 到 10 倍，没有违法所得的罚 50 万元以下。","gain":"条例规定收预付款必须订立书面合同并约定退款方式；出现重大经营风险应当停止收取预付款；决定停业或迁移应当提前告知，消费者有权要求继续履行或者退还未消费余额。违反的可处违法所得 1 到 10 倍罚款，无违法所得的处 50 万元以下罚款","grade":"A","src":"国务院 (2024). 中华人民共和国消费者权益保护法实施条例（国务院令第 778 号，2024 年 7 月 1 日施行）. <https://www.gov.cn/zhengce/zhengceku/202403/content_6940159.htm> 第二十二条：「经营者以收取预付款方式提供商品或者服务的，应当与消费者订立书面合同，约定商品或者服务的具体内容、价款或者费用、预付款退还方式、违约责任等事项。」「经营者未按照约定提供商品或者服务的，应当按照消费者的要求履行约定或者退还预付款。」「经营者出现重大经营风险，有可能影响经营者按照合同约定或者交易习惯正常提供商品或者服务的，应当停止收取预付款。经营者决定停业或者迁移服务场所的，应当提前告知消费者……消费者……有权要求经营者继续履行提供商品或者服务的义务，或者要求退还未消费的预付款余额。」；第五十条罚则","note":"这条给的是事后的法律依据，不是事前的安全感——商家真跑了，钱多半已经不在账上。所以顺序仍然是：先按本节「健身房按次付费或短周期付费」那条少充，再靠这一条维权。同一条例第二十七条还规定，收押金必须事先约定退还方式、程序和时限，不得对退还设置不合理条件。","money":"0","time":"少","will":"些","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"一般"},{"id":"5.23","sec":5,"n":23,"title":"大额非必需购买设 24 小时冷静期，网购善用七日无理由退货","cost":"延后一天满足；退货运费通常自付","human":"省下的是那些第二天就不想要的东西。网购从收到货那天起七天内可以无理由退，定作的、生鲜易腐的、拆封的数字商品和报刊除外。","gain":"省下的是冲动购买中「第二天就不想要了」的那部分，无法给出统一比例；网络购买商品自收到之日起七日内可无理由退货，定作、鲜活易腐、已拆封数字商品、报刊除外（中国，2017 年起施行）","grade":"C","src":"国家市场监督管理总局 (2020 修订). 网络购买商品七日无理由退货暂行办法（总局令第 31 号）. <https://www.gov.cn/zhengce/zhengceku/2020-11/03/content_5557118.htm>","note":"「冷静期」本身是经验规则，没有直接文献；七日退货是它的制度兜底，退货前先确认商品是否在排除清单内、包装是否完好。","money":"0","time":"少","will":"些","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"一般"},{"id":"5.24","sec":5,"n":24,"title":"不为「划线价」和大促囤货","cost":"放弃部分真折扣；需要记住常购商品的日常价","human":"人判断贵不贵靠的是最先看到的那个数，之后再怎么调整都不够，所以「原价 999 现价 499」会系统性地让你高估便宜的程度。而按规定，打折的基准只是促销前七天内本店的最低成交价——划线价不一定真卖过。","gain":"判断锚定于最先看到的数字，之后的调整通常不足，所以「原价 999 现价 499」会系统性抬高你对便宜程度的估计；监管规定折价基准应为促销前七日内同店最低成交价，也就是说划线价并不必然是曾经的售价（中国，2020 年起施行）","grade":"C","src":"Tversky A, Kahneman D (1974). Judgment under Uncertainty: Heuristics and Biases. Science 185(4157):1124-1131. <https://doi.org/10.1126/science.185.4157.1124>；国家市场监督管理总局 (2020). 规范促销行为暂行规定（总局令第 32 号，第二十一条）. <https://www.samr.gov.cn/zw/zfxxgk/fdzdgknr/fgs/art/2023/art_cae53a080be2401e8f91c6d6291539f8.html>","note":"锚定效应是实验室结论，对囤货损失没有直接的金钱量化；囤货的隐性成本还包括过期、占地和「反正有，多用点」。只囤保质期长、确定会用完、单价确实低于历史价的东西。","money":"0","time":"少","will":"些","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"一般"},{"id":"5.25","sec":5,"n":25,"title":"保险优先买消费型，把「返还」「分红」当作不保证的部分","cost":"消费型保险到期无返还，心理上像「白花了」；需要自己安排储蓄","human":"分红和返还那部分是不保证的，监管要求说明书必须加粗提示「未来的保单红利为非保证利益」。多交的那笔保费，本质上是让保险公司替你存钱：收益不保证，还不好取出来。","gain":"监管规则要求分红型产品说明书用加粗字体提示「未来的保单红利为非保证利益，其红利分配是不确定的」，且红利演示的利差上限为 4.5% 减去产品预定利率；返还型/分红型的额外保费本质上是交给保险公司代管的储蓄，收益不保证、流动性差（中国，2023 年起施行）","grade":"C","src":"中国银保监会 (2022). 一年期以上人身保险产品信息披露规则（银保监规〔2022〕24 号）. <https://www.gov.cn/zhengce/zhengceku/2023-01/04/content_5735014.htm>","note":"争议：对完全存不下钱的人，返还型的强制储蓄功能有实际价值；本条针对的是有自律的普通人。精算原理上「消费型 + 自己投资」优于「返还型」的量化差距因产品而异，本节没有可引用的系统性数据。不构成投资建议。","money":"0","time":"少","will":"些","level":"大","lens":"金钱","dispute":true,"todo":false,"ratio":"高"},{"id":"5.26","sec":5,"n":26,"title":"三者险买够：交强险限额全国统一且不高，超出的部分从你自己家里出","cost":"商业第三者责任险一年几百到上千元，保额越高单位保费越便宜","human":"交强险的赔偿限额全国统一，而且死亡伤残、医疗费、财产损失分开算，真撞了人很容易超。超出的部分是从你自己家里掏的，所以商业三者险要买够。","gain":"交强险在全国范围内实行统一责任限额，且分为死亡伤残、医疗费用、财产损失以及无责任四项分别计算；超出限额的部分由侵权人自己承担。不投交强险的，车辆被扣留并处应缴保险费 2 倍罚款","grade":"A","src":"国务院 (2006, 2012 修订). 机动车交通事故责任强制保险条例（国务院令第 462 号，第 618 号令修改）第二十三条：「机动车交通事故责任强制保险在全国范围内实行统一的责任限额。责任限额分为死亡伤残赔偿限额、医疗费用赔偿限额、财产损失赔偿限额以及被保险人在道路交通事故中无责任的赔偿限额。」「责任限额由保监会会同国务院公安部门、国务院卫生主管部门、国务院农业主管部门规定。」第二十一条限额内赔偿；第三十九条未投保的「由公安机关交通管理部门扣留机动车……处依照规定投保最低责任限额应缴纳的保险费的2倍罚款」. <http://www.gov.cn/gongbao/content/2012/content_2131962.htm>","note":"TODO（待核实：现行的交强险各项责任限额具体金额，由金融监管部门规定，本次未取得可逐字核对的原文）。要点是结构而不是数字：交强险分项赔、限额统一且不高，撞伤人的赔偿总额可以远超它，差额没有任何兜底。三者险保额买多少本书不给数字，但它是这本书里少数「多花几百元换掉一个可能压垮家庭的尾部风险」的地方。","money":"多","time":"少","will":"否","level":"大","lens":"金钱","dispute":false,"todo":true,"ratio":"高"},{"id":"5.27","sec":5,"n":27,"title":"先存出 3 到 6 个月生活费的应急金，放在随时能取的地方","cost":"不花钱，但这笔钱要放弃更高收益，只放活期、货币基金或随时可取的存款","human":"3 到 6 个月生活费放在随时能取的地方，失业或生病时就不用去借年化 18% 的钱，也不用割肉卖掉投资。放在银行的存款有存款保险，同一家银行最高赔 50 万元。","gain":"有应急金就不用在失业、生病时借钱（消费贷、最低还款的年化利率见本节第 7 条）或割肉卖掉投资；放在银行的存款受存款保险保护，同一家银行最高偿付 50 万元（中国，2015 年）","grade":"C","src":"国务院 (2015). 存款保险条例（国务院令第 660 号，第五条）. <https://www.gov.cn/zhengce/content/2015-03/31/content_9562.htm>","note":"「3 到 6 个月」是通行经验，没有找到官方或学术原文，故标 C；金额按自己的固定支出算，不按收入算。不构成投资建议。","money":"0","time":"少","will":"些","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"5.28","sec":5,"n":28,"title":"提前还房贷之前先做一道比较题，不要凭感觉","cost":"半小时算账；需要诚实估计自己能拿到的税后稳定收益率","human":"提前还款拿到的是一笔确定收益，数值就等于你的房贷利率。所以只需要回答一个问题：你能长期稳定拿到的税后收益，是不是高过房贷利率？高就别还，不高或者说不准就还。等额本息前期利息占比高，越早还省得越多，用银行 App 的提前还款试算直接看数。","gain":"算法：设房贷年利率 r（按合同，2026 年 8 月 20 日 5 年期以上 LPR 为 3.5%，实际执行利率为 LPR 加减点），可选替代投资的税后年化收益 g。提前还款的确定收益率就是 r；若 g 稳定大于 r，钱留在投资里更划算；若 g 小于 r 或不确定，提前还款等于锁定一笔无风险的 r。等额本息前期利息占比高，越早还省息越多，这一点用银行 App 的「提前还款试算」直接看数字（中国，2026 年利率）","grade":"C","src":"全国银行间同业拆借中心受中国人民银行授权 (2026). 2026 年 8 月 20 日贷款市场报价利率（LPR）公告. <https://www.chinamoney.com.cn/chinese/rdgz/20260820/3399885.html>","note":"只写算法不下结论：g 很难稳定超过 r 是常态，但留够应急现金优先于任何一方。注意合同里的提前还款违约金条款。不构成投资建议。","money":"0","time":"少","will":"否","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"极高"},{"id":"5.29","sec":5,"n":29,"title":"网购认平台规则和法条，不认主播和「好评」","cost":"不花钱；下单前多看一眼售后条款和定金规则，收货后留好订单、直播回放截图和聊天记录","human":"商家欺诈按价款三倍赔，不足 500 元按 500 元算；平台明知卖家侵权还不管的要连带赔。直播间刷单、刷好评、发虚假信息都要担责，组织刷单最高罚 200 万元并可能吊照。定金最多只能收合同额的 20%，你违约定金不退，卖家违约双倍返还。大数据杀熟是明文禁止的。","gain":"经营者有欺诈行为的按价款三倍赔偿，不足 500 元按 500 元；平台明知或应知卖家侵权不处理的承担连带责任；直播间和主播不得虚构交易、关注、浏览、点赞等流量、不得发布虚假信息，造成损害的承担民事责任；组织虚假交易、虚假评价帮人刷宣传的罚 100 万元以下，情节严重 100 万到 200 万元并可吊销执照；定金不得超过合同标的额 20%，你不履行定金不退，卖家不履行双倍返还；用个人信息做自动化决策不得在交易价格等条件上搞不合理差别待遇（大数据杀熟）（全国）","grade":"A","src":"全国人大常委会 (2013 修正). 消费者权益保护法（第四十四、五十五条）. <https://www.samr.gov.cn/zfjcj/tzgg/art/2023/art_615af9ed6bcd4974bf853dd2e02bc663.html>（市场监管总局转载）；国家网信办等七部门 (2021). 网络直播营销管理办法（试行）（第十八、二十八条）. <https://www.gov.cn/zhengce/zhengceku/2021-04/23/content_5601682.htm>；全国人大常委会 (2025 修订). 反不正当竞争法（第九、二十五条）. <https://www.ssf.gov.cn/portal/rootfiles/2025/09/01/1758444945285569-1758444945303119.pdf>（全国社保基金理事会转载）；全国人大 (2020). 民法典（第五百八十六、五百八十七条）. <https://www.court.gov.cn/zixun/xiangqing/233181.html>；全国人大常委会 (2021). 个人信息保护法（第二十四条）. <https://www.stats.gov.cn/gk/tjfg/xgfxfg/202503/t20250310_1958923.html>（国家统计局转载）；山东省市场监管局 (2025). 六起网络不正当竞争典型案例. <https://www.samr.gov.cn/jjj/fbzdjz/art/2025/art_cbaed1c006584baeb6823a6b01325ba4.html>","note":"「哪个平台性价比最高、不容易买到劣质品」没有可引用的官方对比数据，本书不做平台排名，能查到的只有整体抽查（见下一条）。反不正当竞争法 2025 年修订后虚假宣传由旧第八条改为第九条、罚则由第二十条改为第二十五条，2025 年 10 月 15 日起施行，别抄旧条号；山东案例里一家公司组织「刷手」虚假交易 75 笔、本金 68 万余元被查处，罚款数字通报未写。七日无理由退货见本节第 23 条。","money":"0","time":"少","will":"些","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"一般"},{"id":"5.30","sec":5,"n":30,"title":"直播间买的东西出了问题，先向平台要卖家和带货人的信息，平台必须给","cost":"0 元；向平台提出要求即可","human":"直播维权最常见的死结是找不到该告谁。出了纠纷你可以直接要求平台提供直播间运营者、带货人的信息和经营记录，平台必须给。","gain":"发生消费争议时，直播营销平台经营者应当根据消费者的要求，提供直播间运营者、直播营销人员的相关信息以及相关经营活动记录——这解决的是直播维权里最常见的死结：找不到该告谁","grade":"A","src":"国务院 (2024). 中华人民共和国消费者权益保护法实施条例（国务院令第 778 号，2024 年 7 月 1 日施行）. <https://www.gov.cn/zhengce/zhengceku/202403/content_6940159.htm>：「经营者通过网络直播等方式提供商品或者服务的，应当依法履行消费者权益保护相关义务。直播营销平台经营者应当建立健全消费者权益保护制度，明确消费争议解决机制。发生消费争议的，直播营销平台经营者应当根据消费者的要求提供直播间运营者、直播营销人员相关信息以及相关经营活动记录等必要信息。」「直播间运营者、直播营销人员发布的直播内容构成商业广告的，应当依照《中华人民共和国广告法》的有关规定履行广告发布者、广告经营者或者广告代言人的义务。」","note":"下单前把直播画面和承诺录屏，出问题时先向平台要主体信息，再决定投诉还是起诉。同一条例还规定：不得擅自扩大不适用七日无理由退货的商品范围，不得把「不适用无理由退货」设成默认选项，未经你确认不得拒绝退货。","money":"0","time":"少","will":"否","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"5.31","sec":5,"n":31,"title":"买大件前先查国家抽检通报、3C 认证和能效标识","cost":"不花钱；几分钟，在市场监管总局和认监委官网查一下","human":"2024 年国家抽检 25250 批次产品，14.3% 不合格；电商渠道更差，7297 批次里 23.5% 不合格，实体店是 15.1%。买大件前花几分钟查一下抽检通报和 3C 证书真伪，能效标识该贴的不能缺。","gain":"2024 年国家监督抽查 25250 批次产品，不合格率 14.3%；其中电商渠道抽 7297 批次、不合格率 23.5%，比上年升 1.8 个百分点，实体店抽 8055 批次、不合格率 15.1%；强制性产品认证（3C）证书可在认监委官网「认证结果」栏查真伪；能效标识按产品目录强制管理，标识须含能效等级、能效指标和能效信息码，伪造、冒用或该标不标的依节约能源法处罚（全国）","grade":"B","src":"市场监管总局 (2025). 关于 2024 年产品质量国家监督抽查情况的通报. <https://www.samr.gov.cn/zw/zfxxgk/fdzdgknr/zljds/art/2025/art_02676c16ac634fd9a48ec6ea10eb000d.html>；国家认监委. 官网「认证结果」查询入口. <https://www.cnca.gov.cn/> ；国家发展改革委、国家质检总局 (2016). 能源效率标识管理办法（令第 35 号，第三、七、二十七条）. <https://www.gov.cn/zhengce/2021-11/30/content_5713245.htm>","note":"抽查是监管抽样，不等于市场整体合格率，也不能据此给平台排名；「查一下能少买到多少劣质品」没有研究，所以给 B。认监委查询平台 cx.cnca.cn 本节核实时打不开，入口以 cnca.gov.cn 首页为准。抽查通报的数字每年更新，用时查最新一期。","money":"0","time":"少","will":"否","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"5.32","sec":5,"n":32,"title":"手串、玉石、名表、潮玩按「花掉的钱」算账，不按「存下的钱」算","cost":"0 元；只是不把「以后能升值」算进购买理由","human":"这类东西买的那一刻价里就先扣掉一截税：不含增值税每只 1 万元及以上的手表按「高档手表」征 20% 消费税，金银铂金首饰和钻石 5%，其他贵重首饰和珠宝玉石 10%，增值税还在外面。这些钱转手卖给下一个人时拿不回来。卖这头要么自己找买家，要么押给典当行——动产质押的月综合费用上限是当金的 42‰，一年就是当金的五成，当金利息另算，典当期限最长 6 个月，到期 5 天内不赎不续就算绝当，估价 3 万元以上的可以委托拍卖，拍卖收入先扣拍卖费和当金本息，不够还要向你追。真喜欢就当消费买，别算成理财。","gain":"买入一侧，《消费税税目税率表》：「高档手表」税率 20%，「贵重首饰及珠宝玉石」中金银首饰、铂金首饰和钻石及钻石饰品 5%、其他贵重首饰和珠宝玉石 10%；高档手表的口径是「销售价格（不含增值税）每只在 10000 元（含）以上的各类手表」。变现一侧，《典当管理办法》第三十六条典当期限最长不得超过 6 个月，第三十七条当金利率按中国人民银行公布的 6 个月期法定贷款利率及典当期限折算、利息不得预扣，第三十八条动产质押典当的月综合费率不得超过当金的 42‰（房地产抵押 27‰、财产权利质押 24‰），第四十条期限届满后 5 日内不赎当也不续当即为绝当，第四十三条估价金额 3 万元以上的绝当物可委托拍卖、拍卖收入扣除拍卖费用及当金本息后剩余退还当户、不足部分向当户追索（全国）","grade":"A","src":"国务院 (2008). 中华人民共和国消费税暂行条例（国务院令第 539 号，附《消费税税目税率表》）. <https://www.gov.cn/zhengce/zhengceku/2008-11/14/content_1795.htm>；财政部、国家税务总局 (2006). 关于调整和完善消费税政策的通知（财税〔2006〕33 号）. <http://www.mof.gov.cn/zhengwuxinxi/zhengcefabu/2006zcfb/200805/t20080524_34758.htm>；商务部、公安部 (2005). 典当管理办法（2005 年第 8 号令，第三十六、三十七、三十八、四十、四十三条）. <https://www.gov.cn/gongbao/content/2005/content_93074.htm>","note":"「一年五成」是按月费率直乘 12 的粗算，用来看量级，不是精确年化。税率和费率是明文数字，「这类东西长期能不能升值」没有可引用的官方统计，本书不做预测，也不点评任何品类。这条要拦的只是把消费当投资的那部分理由：喜欢、戴着高兴，按消费买没问题；以「保值」「以后能卖更高」为由把预算加上去，才是亏钱的地方。黄金也分两头：按克重买卖的投资性金条和按件卖的首饰不是一回事，首饰价里含设计和工费，回收时通常不算这部分。二手平台的挂牌价不是成交价，别当行情看。","money":"0","time":"少","will":"些","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"一般"},{"id":"5.33","sec":5,"n":33,"title":"珠宝玉石只认带 CMA 标志的检测报告，并到发证部门官网核一下这家机构","cost":"0 元；下单前查一次机构资质，几分钟","human":"证书本身是能伪造的，所以要查的是出证书的机构。检测机构向社会出具有证明作用的报告，必须先取得资质认定，报告上要标 CMA 标志，标志由 CMA 图案加证书编号组成；发证部门要在官网公布取得资质的机构名单和证书状态，你能自己查这家在不在、证还有没有效。市场监管总局 2026 年 6 月公布的「打假清源」典型案例里，有直播间把染色石英岩玉、处理过的翡翠、玻璃和塑料当成「天然翡翠、蜜蜡、水晶」卖，随货的「国检证书」是自己找人做的；另一家被扣的 469 件「天然水晶」检出 259 件是合成的；还有店铺把假的「GIA」「CMA」「中玉珠宝玉石鉴定中心」招牌挂在直播背景墙上，另外自购 181 只「国家珠宝玉石质量监督检验中心」合格证标识配给手镯。","gain":"《检验检测机构资质认定管理办法》第二条，资质认定是对「向社会出具具有证明作用的数据、结果」的检验检测机构实施的评价许可；第十五条资质认定标志由 CMA 图案和资质认定证书编号组成；第二十一条机构向社会出具具有证明作用的数据、结果的，应当在检验检测报告上标注资质认定标志；第二十二条资质认定部门应当在官方网站公布取得资质认定的机构信息并注明证书状态；第三十四条未依法取得资质认定擅自向社会出具具有证明作用的数据、结果的处 3 万元罚款；第三十七条伪造、变造、冒用资质认定证书或者标志的处 3 万元以下罚款。官方案例（市场监管总局 2026 年 6 月 4 日公布的传统工艺市场「打假清源」典型案例）：江苏东海一直播间宣称所售为「天然的、无酸洗、无优化、缅甸的 A 货」并配「国检证书」，送检结果为石英岩玉（染色）、翡翠（处理）、玻璃、塑料，证书系当事人自行联系制作；同县另一案扣押 469 件疑似假冒天然水晶制品，检出 210 件天然水晶、259 件合成水晶；河南镇平一店铺私制「GIA CMA 中玉珠宝玉石鉴定中心认证合作单位」展板用于直播，并网购制作「国家珠宝玉石质量监督检验中心」合格证标识 181 只配售（全国）","grade":"A","src":"国家质量监督检验检疫总局 (2015 公布，2021 修改). 检验检测机构资质认定管理办法（第二、十五、二十一、二十二、三十四、三十七条）. <https://www.gov.cn/zhengce/2021-04/22/content_5723677.htm>；国家市场监督管理总局 (2026). 市场监管总局公布一批传统工艺市场「打假清源」典型案例. <https://www.samr.gov.cn/xw/zj/art/2026/art_1529399cfe874b8780c4496eb0158020.html>；国家标准化管理委员会. GB/T 16552—2017《珠宝玉石 名称》（现行，2018 年 5 月 1 日实施）. <https://openstd.samr.gov.cn/bzgk/gb/newGbInfo?hcno=18FFB042811998A0309E05CF452B2438>","note":"珠宝玉石的名称有国家标准，检测结论写的是「石英岩玉（染色）」「翡翠（处理）」这种带括号的形式，括号里那两个字就是差价所在；「A 货」「老坑」「无优化」是卖家话术，不是鉴定结论，拿它当结论的正是上面被查的那家。同一批案例里还有伪造矿区现场安排人扮「矿工」直播、安排水军烘托气氛、编「急用钱」「亲人重病」剧本的，以及宣称商品能「防治风湿病、提高免疫力、改善睡眠质量、疏通血管」——后一类按虚假宣传查处。买大件的通用查法见本节第 31 条（查抽检通报和 3C 认证），直播间出事找谁见第 29、30 条（网购认平台规则、直播间出问题找平台要信息）。","money":"0","time":"少","will":"否","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"5.34","sec":5,"n":34,"title":"盲盒、抽卡这类随机销售，按「这笔钱不会回来」算","cost":"0 元；只是买之前把预算定死","human":"规则给了你知情权，没给你后悔权。经营者必须把抽取规则、商品分布、限量款投放数量、抽取概率、商品价值范围显著公示，不许后台操纵结果、不许随意调概率、不许设空盒——这些是你日后投诉的具体抓手。但「保底、抽取金额上限、次数上限」在文件里只是「鼓励」，不是必须；而且经充分告知并由你在单次购买时确认后，网上买的盲盒拆封后可以不适用七日无理由退货（商家不得用默认勾选替你确认）。所以拆开那一下就是能反悔的最后时刻。不满 8 周岁的孩子商家不得卖，8 周岁及以上要确认已取得监护人同意。","gain":"《盲盒经营行为规范指引（试行）》第九条：商品名称、种类、样式、抽取规则、商品分布、限量商品投放数量、抽取概率、商品价值范围等关键信息应当以显著方式对外公示，保证消费者购买前知晓；不得通过后台操纵改变抽取结果、随意调整抽取概率等方式变相诱导消费，不得以折现、回购、换购等方式拒绝或者故意拖延发放盲盒，不得设置空盒。第十一条只是「鼓励」经营者建立保底机制，通过设定抽取时间、抽取金额上限和次数上限等方式引导理性消费。第十七条：经充分告知提示并经消费者单次购买时确认后，以互联网形式销售的盲盒商品拆封后可以不适用七日无理由退货，经营者不得以默认勾选方式替代消费者确认环节。第二十一条：不得以盲盒名义从事或者变相从事赌博活动。第二十三条：不得向未满 8 周岁未成年人销售盲盒，向 8 周岁及以上未成年人销售应当依法确认已取得相关监护人的同意（全国）","grade":"A","src":"市场监管总局 (2023). 盲盒经营行为规范指引（试行）（国市监稽发〔2023〕39 号，第九、十一、十七、二十一、二十三条）. <https://www.samr.gov.cn/zw/zfxxgk/fdzdgknr/zfjcs/art/2023/art_e2facd76a7fb4e90b03912cffb5e7d53.html>","note":"这是指引，管的是经营者该怎么做，本身不是处罚依据；真出了事按产品质量法、反不正当竞争法、消费者权益保护法处理。概率没公示、公示的概率和实际对不上、买到空盒，都是能投诉的具体事由，投诉前把页面规则和开箱过程录屏。孩子拿手机充值打赏的退款见本节第 9 条，大额非必需购买的 24 小时冷静期见第 23 条，「买到手就淡了、于是接着买」这个循环见第 6 节第 23 条（别指望买东西改善心情）。","money":"0","time":"少","will":"些","level":"小","lens":"金钱","dispute":false,"todo":false,"ratio":"一般"}]},{"n":6,"title":"反面清单","intro":"本节收的是「看起来便宜又有效」但原始证据显示收益接近零、为零或为负的东西。排序按大众花钱多少与证据硬度综合，越靠前越值得先停掉。","entries":[{"id":"6.1","sec":6,"n":1,"title":"不要为了长寿或防心血管病吃复合维生素","cost":"约 0.5–2 元/天，一年 200–700 元；长期吞药的心理依赖","human":"1.4 万名男医生吃了十一年，心血管事件和死亡都没吃出差别；把 9 项试验、5 万多人放一起看，也看不出对死亡有影响。省下的是一年两百到七百块。确诊营养缺乏的人、孕妇补叶酸不在此列。","gain":"PHS II（14,641 名男医生，中位随访 11.2 年）主要心血管事件 HR 1.01（95% CI 0.91–1.10），全因死亡 HR 0.94（0.88–1.02）；USPSTF 2022 汇总 9 项 RCT 51,550 人，多维片与全因死亡无关联，评级 I（证据不足）；看起来划算是因为「一片补齐所有营养」的直觉和单价低","grade":"A","src":"Sesso HD et al. (2012). Multivitamins in the prevention of cardiovascular disease in men: the Physicians' Health Study II randomized controlled trial. JAMA. <https://doi.org/10.1001/jama.2012.14805>；US Preventive Services Task Force (2022). Vitamin, Mineral, and Multivitamin Supplementation to Prevent Cardiovascular Disease and Cancer. JAMA. <https://doi.org/10.1001/jama.2022.8970>","note":"争议：PHS II 同队列的癌症分析显示总癌症发生 HR 0.92（0.86–0.998，P=0.04），癌症死亡 HR 0.88（0.77–1.01）未达显著（Gaziano JM et al. 2012, JAMA, <https://doi.org/10.1001/jama.2012.14641>），效应很小且仅见于男医生人群。确诊营养缺乏者、孕妇（叶酸）、饮食极不均衡者不在此列，按医嘱补","money":"0","time":"少","will":"否","level":"中","lens":"金钱","dispute":true,"todo":false,"ratio":"高"},{"id":"6.2","sec":6,"n":2,"title":"不要为了预防心血管病吃普通鱼油","cost":"约 1–3 元/天，一年 400–1000 元","human":"两项试验（2.6 万人和 1.5 万名糖尿病患者）里，每天 1 克鱼油对心血管事件和死亡都没做出差别。「吃鱼有好处」不等于「吃鱼油胶囊有好处」，省下的是一年四百到一千块。","gain":"VITAL（25,871 人，1 g/天，中位随访 5.3 年）主要心血管事件 HR 0.92（95% CI 0.80–1.06），全因死亡 HR 1.02（0.90–1.15）；ASCEND（15,480 名糖尿病患者，1 g/天，平均随访 7.4 年）严重血管事件 RR 0.97（0.87–1.08），全因死亡 RR 0.95（0.86–1.05）；看起来划算是因为「吃鱼有益」被直接等同于「吃鱼油胶囊有益」","grade":"A","src":"Manson JE et al. (2019). Marine n-3 Fatty Acids and Prevention of Cardiovascular Disease and Cancer. NEJM. <https://doi.org/10.1056/NEJMoa1811403>；ASCEND Study Collaborative Group (2018). Effects of n-3 Fatty Acid Supplements in Diabetes Mellitus. NEJM. <https://doi.org/10.1056/NEJMoa1804989>","note":"争议：REDUCE-IT（8,179 人，已有心血管病或糖尿病、服他汀且甘油三酯 135–499 mg/dL）用 4 g/天纯 EPA 处方药，主要终点 17.2% vs 22.0%，HR 0.75（0.68–0.83）（Bhatt DL et al. 2019, NEJM, <https://doi.org/10.1056/NEJMoa1812792>）。那是高剂量处方 EPA 用于高危人群，不等于保健品鱼油用于普通人；吃鱼本身不在本条范围","money":"0","time":"少","will":"否","level":"中","lens":"金钱","dispute":true,"todo":false,"ratio":"高"},{"id":"6.3","sec":6,"n":3,"title":"不要为了长寿给不缺维生素 D 的人补维生素 D","cost":"约 0.2–0.5 元/天，一年 100–200 元；钱不多，主要是「以为已经做了预防」的错觉","human":"两项试验里（2.6 万人吃 5 年、2.1 万名老人吃 5 年），给本来不缺的人补维 D，癌症、心血管和死亡都没有变化，死亡率 5.3% 对 5.1%。确诊缺乏、骨质疏松、长期不见光的人不在此列，按医嘱补。","gain":"VITAL（25,871 人，2000 IU/天，中位随访 5.3 年）浸润性癌 HR 0.96（95% CI 0.88–1.06），主要心血管事件 HR 0.97（0.85–1.12），全因死亡 HR 0.99（0.87–1.12）；D-Health（21,315 名 60 岁以上澳大利亚人，60,000 IU/月，5 年）全因死亡 HR 1.04（0.93–1.18），死亡率 5.3% vs 5.1%；看起来划算是因为观察性研究里维 D 水平低的人死亡率高，被误读为补充即有效","grade":"A","src":"Manson JE et al. (2019). Vitamin D Supplements and Prevention of Cancer and Cardiovascular Disease. NEJM. <https://doi.org/10.1056/NEJMoa1809944>；Neale RE et al. (2022). The D-Health Trial: a randomised controlled trial of the effect of vitamin D on mortality. Lancet Diabetes Endocrinol. <https://doi.org/10.1016/S2213-8587(21)00345-4>","note":"争议：两项试验都没有专门纳入真正缺乏者，结论只适用于「不缺的人」；确诊缺乏、骨质疏松、长期不见光、婴幼儿等特定人群仍按医嘱补。本条只针对全因死亡与癌症/心血管终点","money":"0","time":"少","will":"否","level":"中","lens":"金钱","dispute":true,"todo":false,"ratio":"高"},{"id":"6.4","sec":6,"n":4,"title":"不要为了防癌吃抗氧化补剂（β 胡萝卜素、维生素 E、维生素 A）","cost":"约 0.5–2 元/天；吸烟者的成本是肺癌风险上升","human":"这一条不只是没用：78 项试验、近 30 万人汇总，抗氧化补剂反而把死亡率略微推高；两项针对吸烟者的大试验里，β 胡萝卜素让肺癌发生率高 18% 到 28%，总死亡高 8% 到 17%。吸烟的人和接触过石棉的人尤其别吃。","gain":"Cochrane 综述（78 项 RCT，296,707 人）抗氧化补剂总死亡 RR 1.02（95% CI 0.98–1.05），低偏倚风险试验 RR 1.04（1.01–1.07），β 胡萝卜素 RR 1.05（1.01–1.09），维生素 E RR 1.03（1.00–1.05）；ATBC（29,133 名男性吸烟者，20 mg/天）肺癌发生率升高 18%（3%–36%），总死亡升高 8%（1%–16%）；CARET（18,314 名吸烟者/石棉暴露者）肺癌 RR 1.28（1.04–1.57），全因死亡 RR 1.17（1.03–1.33）；看起来划算是因为「抗氧化 = 抗衰老 = 防癌」的推理链每一步都像常识","grade":"A","src":"Bjelakovic G et al. (2012). Antioxidant supplements for prevention of mortality in healthy participants and patients with various diseases. Cochrane Database Syst Rev. <https://doi.org/10.1002/14651858.CD007176.pub2>；The Alpha-Tocopherol, Beta Carotene Cancer Prevention Study Group (1994). The effect of vitamin E and beta carotene on the incidence of lung cancer and other cancers in male smokers. NEJM. <https://doi.org/10.1056/NEJM199404143301501>；Omenn GS et al. (1996). Effects of a combination of beta carotene and vitamin A on lung cancer and cardiovascular disease. NEJM. <https://doi.org/10.1056/NEJM199605023341802>","note":"USPSTF 2022 对 β 胡萝卜素和维生素 E 给出 D 级（建议不用），吸烟者和石棉暴露者是明确的受害人群；从蔬菜水果摄入抗氧化物不在本条范围","money":"0","time":"少","will":"否","level":"中","lens":"死亡率","dispute":false,"todo":false,"ratio":"高"},{"id":"6.5","sec":6,"n":5,"title":"不要指望氨糖（葡萄糖胺）/软骨素治膝关节炎","cost":"约 2–5 元/天，一年 700–1800 元","human":"1583 人吃了 24 周：安慰剂组本来就有 60.1% 的人说疼痛缓解了，氨糖只比它高 3.9 个百分点、软骨素高 5.3 个，都没到有统计意义的程度。一年七百到一千八，买的基本是那六成安慰剂效应。","gain":"GAIT（1,583 名膝骨关节炎患者，24 周）疼痛缓解应答率安慰剂 60.1%，氨糖比安慰剂高 3.9 个百分点（P=0.30），软骨素高 5.3 个百分点（P=0.17），两者合用高 6.5 个百分点（P=0.09），均不显著；对照药塞来昔布高 10.0 个百分点（P=0.008）；看起来划算是因为「补软骨的原料」听起来直接对症，且安慰剂本身就有六成应答","grade":"A","src":"Clegg DO et al. (2006). Glucosamine, chondroitin sulfate, and the two in combination for painful knee osteoarthritis. NEJM. <https://doi.org/10.1056/NEJMoa052771>","note":"争议：同一试验中基线中重度疼痛亚组合用应答率 79.2% vs 54.3%（P=0.002），但作者明确称之为「探索性分析」。膝关节炎的减重和肌力训练是有证据的替代方案，见第 2 节","money":"0","time":"少","will":"否","level":"中","lens":"金钱","dispute":true,"todo":false,"ratio":"高"},{"id":"6.6","sec":6,"n":6,"title":"不要靠维生素 C 预防感冒","cost":"泡腾片约 1–2 元/片，一年 300–700 元","human":"29 项对照、11306 人：天天吃维 C 基本不减少得感冒的次数；感冒之后才开始吃也看不出一致的效果。它确实能把病程缩短约 8%——一次感冒少难受半天，自己算这值不值一年三五百。马拉松选手、寒地行军的士兵是例外，他们得感冒的概率能降一半。","gain":"Cochrane 综述（29 项对照，11,306 人）普通人群规律补充维 C 的感冒发生率 RR 0.97（95% CI 0.94–1.00），即基本不减少得感冒的次数；感冒后才开始吃「在治疗性试验中未见一致效应」；同一综述中长期规律补充可使感冒病程缩短约 8%（成人，95% CI 3%–12%）、14%（儿童，7%–21%）；马拉松运动员、滑雪者与寒地行军士兵（5 项试验，598 人）的感冒发生率 RR 0.48（95% CI 0.35–0.64）；看起来划算是因为便宜、酸甜好喝、且「维 C 防感冒」流传了半个世纪","grade":"A","src":"Hemilä H, Chalker E (2013). Vitamin C for preventing and treating the common cold. Cochrane Database Syst Rev. <https://doi.org/10.1002/14651858.CD000980.pub4>","note":"争议：同一综述显示长期规律补充可把感冒病程缩短约 8%（成人，3%–12%）、14%（儿童，7%–21%），一次感冒少病半天左右；马拉松、滑雪、寒地行军士兵（5 项试验，598 人）发生率 RR 0.48（0.35–0.64）。绝大多数人不属于这两类","money":"0","time":"少","will":"否","level":"小","lens":"金钱","dispute":true,"todo":false,"ratio":"一般"},{"id":"6.7","sec":6,"n":7,"title":"不要给没有症状的自己做「全身 PET-CT」或「肿瘤标志物套餐」","cost":"全身 PET-CT 约 7000–10000 元/次并伴随电离辐射；肿瘤标志物套餐几百元；真正的成本是假阳性之后的复查、活检与手术","human":"给没症状的人查，主要产出是假阳性：1192 个没症状的人做全身 CT，86% 至少查出一处「异常」，37% 被叫回去进一步检查，而绝大多数是良性的。卵巢癌标志物筛查的大试验里，筛查组的死亡率反而略高，0.2% 到 3.25% 的人因为假阳性挨了一刀，其中最多 15% 出现严重手术并发症。一次七千到一万，还有辐射。有证据的那几项筛查是另一回事。","gain":"USPSTF 对无症状女性用 CA-125 和超声筛查卵巢癌给 D 级（建议不做）：PLCO 试验卵巢癌死亡率筛查组 0.34% vs 常规组 0.29%（RR 1.18，95% CI 0.82–1.71），无获益；因假阳性接受手术的比例在各试验为 0.2%–3.25%，其中最多 15% 出现严重手术并发症；全身 CT 筛查 1,192 名无症状者，86% 至少有一处「异常」，37% 被建议进一步检查，而「大多数发现按描述是良性的」；看起来划算是因为「一次查全身、早发现早治疗」符合直觉","grade":"A","src":"US Preventive Services Task Force (2018). Screening for Ovarian Cancer: US Preventive Services Task Force Recommendation Statement. JAMA（同一份建议另有 USPSTF 官方页）. <https://doi.org/10.1001/jama.2017.21926>、<https://www.uspreventiveservicestaskforce.org/uspstf/recommendation/ovarian-cancer-screening>；Furtado CD et al. (2005). Whole-body CT screening: spectrum of findings and recommendations in 1192 patients. Radiology. <https://doi.org/10.1148/radiol.2372041741>","note":"肿瘤标志物部分是 RCT 证据，全身 CT/PET-CT 部分只有描述性研究（相当于 B 级）。有证据的筛查（结直肠、宫颈、乳腺、高危者的低剂量胸 CT）是另一回事，见第 1 节；已有症状或确诊癌症者的 PET-CT 是诊疗手段，不在本条范围","money":"0","time":"少","will":"否","level":"中","lens":"死亡率","dispute":false,"todo":false,"ratio":"高"},{"id":"6.8","sec":6,"n":8,"title":"不要指望手环/手表的运动量化帮你减重","cost":"200–2000 元设备，加上每天看数据的注意力","human":"471 个超重成人做同样的生活方式干预，戴设备那组两年减了 3.5 公斤，不戴的反而减了 5.9 公斤。设备帮不上减重这件事，运动本身才管用。","gain":"IDEA 试验（471 名超重/肥胖成人，24 个月）在同样的生活方式干预基础上，佩戴可穿戴设备组减重 3.5 kg（95% CI 2.6–4.5），不戴组反而减 5.9 kg（5.0–6.8），差 2.4 kg（1.0–3.7，P=0.002）；看起来划算是因为「量化才能管理」的说法和设备一次性付费","grade":"B","src":"Jakicic JM et al. (2016). Effect of Wearable Technology Combined With a Lifestyle Intervention on Long-term Weight Loss: The IDEA Randomized Clinical Trial. JAMA. <https://doi.org/10.1001/jama.2016.12858>","note":"单一试验，用的是 2010 年代初的臂戴设备，结论不能外推到「所有可穿戴设备无用」；运动本身有效，见第 2 节，本条只说设备不是减重的必要开销","money":"0","time":"少","will":"否","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"6.9","sec":6,"n":9,"title":"不要为了「更健康」花溢价买有机食品","cost":"通常是普通食品价格的 1–3 倍","human":"把 17 项人体研究和 223 项成分研究放一起看，没有有力证据说有机食品更有营养；只有 3 项看了真实的健康结局，也没有差别。有机农产品检出农药残留的比例确实低 30 个百分点，但检出不等于超标。多吃蔬菜水果本身有用，有机与否不影响这一点。","gain":"系统综述（17 项人体研究，223 项食品成分研究）「缺乏有力证据表明有机食品比常规食品显著更有营养」；仅 3 项人体研究看临床结局（过敏、症状性感染），组间无显著差异；有机农产品检出农药残留的风险低 30 个百分点，但检出不等于超标；看起来划算是因为「无农药 = 更安全 = 更健康」每一步都像常识","grade":"B","src":"Smith-Spangler C et al. (2012). Are organic foods safer or healthier than conventional alternatives?: a systematic review. Ann Intern Med. <https://doi.org/10.7326/0003-4819-157-5-201209040-00007>","note":"健康结局的人体研究极少，属于「没有证据支持有益」而非「证明无益」；环境、动物福利、口味不在本条口径内。多吃蔬菜水果本身有效，有机与否不影响这一条","money":"0","time":"少","will":"否","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"6.10","sec":6,"n":10,"title":"不要花大钱买保健品、膏方、滋补品来「调理身体」","cost":"从几百元到上万元不等，礼品化之后常常成倍上涨","human":"监管规定保健食品包装上必须用不小于 20% 的面积写「保健食品不是药物，不能代替药物治疗疾病」——管它的机构本身就不认它能治病。最常见的那几种成分（多维、鱼油、维 D、抗氧化剂、氨糖、维 C）本节前六条已经逐个查过，结论都是没做出差别。但这笔钱多半不是为了疗效花的，是买给父母的，或者提着上门的，那份心意本身没有问题，问题只在于货不对。同样的钱换成这些，每一项在书里都有出处：陪老人去打该打的疫苗（老年人每年的流感疫苗见第 1 节第 20 条，50 岁以后的带状疱疹疫苗见第 1 节第 21 条，65 岁以上的肺炎球菌疫苗见第 1 节第 22 条）；买个血压计，盯着他把降压药按医嘱吃满（第 1 节第 7 条）；把家里的浴室和楼梯改一改、陪他练平衡和腿部力量（第 1 节第 13 条）；到年纪的癌症筛查陪着去做一次（第 1 节第 17 到 19 条）；老人长期卧床的，压疮和长期护理保险见第 17 节第 7、8 条。要提东西上门，换成水果、米面、他爱吃的东西，比膏方实在。","gain":"国家市场监管总局规定保健食品包装主展示面必须用不小于 20% 的面积标注「保健食品不是药物，不能代替药物治疗疾病」，并把保健食品的目的界定为「补充膳食营养物质、维持改善机体健康状态或者降低疾病发生风险因素」，即监管机构本身不认可其治疗功效；本节前 6 条已列出其中最常见成分（多维、鱼油、维 D、抗氧化剂、氨糖、维 C）的 RCT 结果；看起来划算是因为「不治病但调理」的说法无法被证伪，且送礼场景下购买决策由人情而非证据驱动","grade":"C","src":"国家市场监督管理总局 (2019). 市场监管总局就《保健食品标注警示用语指南》和《保健食品原料目录与保健功能目录管理办法》有关情况举办专题新闻发布会. <https://www.samr.gov.cn/tssps/sjdt/tpxw/art/2023/art_4b658b824b1b4b0ba57c09a56cc93aad.html>","note":"这是「没有证据支持」而非「证明无效」，故为 C 级。成分明确的产品按前几条查对应文献；确诊营养缺乏或在治疗中的人按医嘱。这条否的是产品，不是心意——老人自己买了、已经在吃的，只要不是拿它替掉正在吃的药、也没吃出问题，不必上门去争这一场，把该打的疫苗和该做的筛查安排上更要紧；真正要拦的是「先交钱的投资养老」和会顶替药物的那一类，见第 17 节第 5 条","money":"0","time":"少","will":"否","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"极高"},{"id":"6.11","sec":6,"n":11,"title":"不要在没有肠道问题时长期吃益生菌","cost":"约 2–5 元/天，一年 700–1800 元","human":"45 项健康成人试验汇总：吃益生菌不能让肠道菌群发生持久改变，停了就回去，血脂也没有改善。抗生素相关腹泻这类特定情况有单独的证据，不在这一条里。","gain":"综述 45 项健康成人试验，「未能支持益生菌能引起肠道菌群的持久改变，也未能改善健康成人的血脂」，菌群变化是暂时性的，停用即消失；看起来划算是因为「肠道健康」的概念足够宽泛，且每天一瓶的单价很低","grade":"B","src":"Khalesi S et al. (2019). A review of probiotic supplementation in healthy adults: helpful or hype? Eur J Clin Nutr. <https://doi.org/10.1038/s41430-018-0135-9>","note":"同一综述报告健康人在排便性状、女性阴道乳杆菌等指标上有小幅改善。抗生素相关腹泻、特定菌株的特定适应证有独立证据，不在本条范围；本条只针对「健康人日常保健」","money":"0","time":"少","will":"否","level":"小","lens":"金钱","dispute":false,"todo":false,"ratio":"一般"},{"id":"6.12","sec":6,"n":12,"title":"不要为了「增强免疫力」逼自己洗冷水澡","cost":"钱 0；每天 30–90 秒不适感，冬季坚持需要毅力；心血管病患者有冷刺激风险","human":"3018 人的试验里，洗冷水澡的人请病假的次数少了 29%，但请假的总天数没有差别，所以谈不上少生病。2025 年汇总 11 项试验：冲完冷水，炎症指标反而短暂升高，免疫指标没变化。爱洗随便洗，别把它当成一笔健康投资。","gain":"荷兰 RCT（3,018 人，热水澡结尾冲 30/60/90 秒冷水）病假次数减少 29%（IRR 0.71），但「病假天数没有显著组间差异」，生活质量、工作效率、焦虑均无临床相关差异；2025 年系统综述（11 项 RCT，3,177 人）显示冷水浸泡后即刻与 1 小时炎症指标反而升高，免疫指标无变化，压力仅在 12 小时时点降低，作者称证据「受限于 RCT 少、样本小」；看起来划算是因为免费，且「吃苦 = 有效」的直觉","grade":"B","src":"Buijze GA et al. (2016). The Effect of Cold Showering on Health and Work: A Randomized Controlled Trial. PLOS ONE. <https://doi.org/10.1371/journal.pone.0161749>；Cain T et al. (2025). Effects of cold-water immersion on health and wellbeing: A systematic review and meta-analysis. PLOS ONE. <https://doi.org/10.1371/journal.pone.0317615>","note":"争议：病假次数减少 29% 是真实的显著结果，但生病天数不减，更像「生病了也照常上班」而非少生病；运动员训练后恢复是另一个问题。冷水澡本身对健康人无害，本条只说别把它当健康投资","money":"0","time":"少","will":"否","level":"小","lens":"金钱","dispute":true,"todo":false,"ratio":"一般"},{"id":"6.13","sec":6,"n":13,"title":"不要买排毒、清肠、酵素、碱性水这类产品","cost":"数百到数千元；断食式「排毒」还可能带来低血糖与营养不足","human":"综述的原话是：排毒产业这么大，支持它的临床证据非常少，而且根本没有针对商业排毒饮食做过随机对照试验。「酸性体质致癌」那套查了 8278 篇文献只剩 1 篇合格，也没看出关联。- 收益：综述结论「尽管排毒产业蓬勃发展，支持这些饮食的临床证据非常少」，且「没有针对商业排毒饮食的随机对照试验」；碱性饮食/碱性水与癌症的系统综述筛了 8,278 篇文献，只有 1 篇符合纳入标准且未见关联，作者称「向公众推广碱性饮食和碱性水用于癌症预防或治疗是不合理的」；看起来划算是因为「身体里有毒素要排」「酸性体质致癌」这两个前提听起来像生理学","gain":"","grade":"C","src":"Klein AV, Kiat H (2015). Detox diets for toxin elimination and weight management: a critical review of the evidence. J Hum Nutr Diet. <https://doi.org/10.1111/jhn.12286>；Fenton TR, Huang T (2016). Systematic review of the association between dietary acid load, alkaline water and cancer. BMJ Open. <https://doi.org/10.1136/bmjopen-2015-010438>","note":"属于「没有证据支持」，故为 C 级。肝肾本身承担代谢废物清除，无对应疾病时不需要额外「排毒」","money":"0","time":"少","will":"否","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"6.14","sec":6,"n":14,"title":"不要为了凑够「每天 8 杯水」强迫自己喝水","cost":"钱 0；时间与精力少量，夜尿增多","human":"追查「每天 8 杯水」的出处，找不到任何一项支持它的研究；相反，对几千人饮食饮水的调查提示不需要那么多，因为食物和别的饮料已经带进来大量水分。渴了就喝、看尿的颜色就够。高温作业、剧烈运动、有肾结石史、口渴感变迟钝的老人要另外主动补水。","gain":"对「8×8」（每天 8 杯 8 盎司水）的文献回顾「未找到任何支持 8×8 的科学研究」，反而「对数千名成年人的食物与液体摄入调查强烈提示不需要如此大量」，因为食物和其他饮品已提供大量水分；看起来划算是因为水免费、数字整齐、且「多喝水」在任何场合都显得无害","grade":"C","src":"Valtin H (2002). \"Drink at least eight glasses of water a day.\" Really? Is there scientific evidence for \"8 x 8\"? Am J Physiol Regul Integr Comp Physiol. <https://doi.org/10.1152/ajpregu.00365.2002>","note":"这是「没有证据支持固定数字」而非「多喝水有害」；渴了就喝、看尿色即可。高温作业、剧烈运动、肾结石病史、老年人口渴感减退者需要主动补水，不在本条范围","money":"0","time":"少","will":"否","level":"小","lens":"金钱","dispute":false,"todo":false,"ratio":"一般"},{"id":"6.15","sec":6,"n":15,"title":"不要花钱算命、看塔罗、看星座来做决定","cost":"钱 0；放弃一种拿主意的捷径","human":"经典课堂实验里，学生拿到的「个人性格分析」其实人手一份、内容完全一样，却普遍觉得很准——算命之所以总显得准，原因在这里。真实代价也不止几十块：河南息县那个网络算命团伙先免费看手相引流，再收香火钱和最高 3888 元的「供养套餐」，50 多名被害人、追回赃款 200 多万元，主犯判了十一年。当娱乐花几十块无所谓，拿它决定辞职、结婚、投资才是亏钱的地方。","gain":"经典课堂实验：学生做完性格测验后拿到的「个人分析」其实人人相同，却普遍认为很准，作者的结论是「被本人或分析者接受，不能证明解释正确」，这解释了算命为什么总显得准（巴纳姆效应）；占星术的双盲检验：两组双盲测试检验「星盘能否准确描述受试者性格」，发表在 Nature 上；官方案例：河南息县检察院通报的网络算命诈骗团伙，以免费看手相引流再收「香火钱」和最高 3888 元的「供养套餐」，被害人 50 余人、追回赃款 200 余万元，主犯判有期徒刑十一年并处罚金 10 万元","grade":"B","src":"Forer BR (1949). The fallacy of personal validation: A classroom demonstration of gullibility. Journal of Abnormal and Social Psychology. <https://doi.org/10.1037/h0059240>；Carlson S (1985). A double-blind test of astrology. Nature. <https://doi.org/10.1038/318419a0>；最高人民检察院 (2026). 河南息县：历经三年持续追踪打掉一批网络算命诈骗团伙. <https://www.spp.gov.cn/zdgz/202607/t20260728_732935.shtml>","note":"两篇都是单一研究，本节只核实到摘要：Forer 的评分均值、Carlson 的占星师命中率等具体数字 TODO（待核实：APA 和 Nature 页面付费墙，未能在可打开的页面里找到）。口径是「没有预测效度」，不评价信仰；当娱乐花几十块钱不在本条范围，拿它决定辞职、结婚、投资才是亏的地方。","money":"0","time":"少","will":"否","level":"中","lens":"金钱","dispute":false,"todo":true,"ratio":"高"},{"id":"6.16","sec":6,"n":16,"title":"不要买防蓝光眼镜来「保护视力」，也不要相信「对着屏幕干几个月眼睛就废了」","cost":"0 元；省下镜片上那几百到上千元的加价","human":"Cochrane 汇总 17 项试验的结论是：戴防蓝光镜片和戴普通镜片相比，短期内的眼疲劳感受「可能没有差别」，矫正视力基本没影响，也没找到保护黄斑的证据，省下的是镜片上那几百到上千的加价。另一半同样要紧：屏幕带来的眼酸眼干是可逆的疲劳，不等于把眼睛看坏了；真正会在短期内造成不可逆损伤的是电焊弧光、紫外线和激光。","gain":"Cochrane 2023 年的系统综述纳入 17 项随机对照试验（样本 5 到 156 人，随访从不足 1 天到 5 周），因数据不足、人群异质和随访期差异未做合并分析。与不带蓝光过滤的镜片相比：随访不足一周时的主观视疲劳评分「可能没有差别」（低确定性证据），其中一项 120 人的试验均差 9.76 个单位（95% CI −33.95 到 53.47）；临界闪烁融合频率「可能几乎没有差别」（低确定性）；最佳矫正视力「大概没有影响」（均差 0.00 logMAR，95% CI −0.02 到 0.02，1 项研究 156 人，中等确定性）；对白天警觉性的影响不明（2 项试验 42 人，极低确定性）。综述也没有找到支持它保护黄斑的证据","grade":"A","src":"Singh S, Downie LE, Anderson AJ, Keller PR, White SJ, Ang M, Wolffsohn JS (2023). Blue-light filtering spectacle lenses for visual performance, sleep, and macular health in adults. Cochrane Database of Systematic Reviews, 8, CD013244. <https://doi.org/10.1002/14651858.CD013244.pub2>","note":"屏幕带来的是数字视疲劳和干眼——眼酸、发干、看久了发糊，休息和多眨眼能缓解，是可逆的，不等于「把眼睛看坏了」（这句是眼科共识，不是上面那篇综述的结论，属 C 级）。真正会在短期内造成不可逆眼损伤的是电焊弧光、紫外线和激光这类强光源，「电光性眼炎」是法定职业病，挡它的是护目镜和面罩、不是防蓝光镜片，见第 19 节第 11 条（粉尘噪声化学毒物的防护）。眼睛持续不适或者视力真的在下降，去眼科查清原因，别自己换个镜片了事。儿童青少年的近视防控见第 30 节第 4、10、7 条（每天户外 2 小时、散瞳验光、不买「治愈近视」的产品）。","money":"0","time":"少","will":"否","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"6.17","sec":6,"n":17,"title":"不要把献血当保健：「排毒、降血脂、防心梗」没有随机试验支持，频繁献倒是真会缺铁","cost":"0 元；一次采血加填表、观察休息约一小时，之后几周身体在回补铁储备","human":"「献血能排毒、降血脂、防心梗」的源头是芬兰一项 2862 名中年男性的观察研究：两年内献过血的 153 人里 1 人心梗，没献的 2529 人里 316 人心梗，算下来风险低 88%。问题出在献血的人本来就更健康——把 118 万北欧献血者放一起，只按年龄性别这类特征校正时，每年多献一次血死亡率低 18.6%；再把「一直健康才一直被允许献血」这层扣掉，就只剩 7.5%，原作者自己写明这不能当成献血有益健康的证据。真做成随机试验的那次是阴性的：1277 名下肢动脉病患者随机分成定期放血组和对照组，主要终点全因死亡没有差别。反过来，献得太勤确实会让人没力气、怕冷，机制是铁：4.5 万人的随机试验里，把献血间隔缩短的那几组疲劳、气短、头晕眼花、夜里腿躺不住都更多，血红蛋白和铁蛋白更低，因血红蛋白不达标被推迟献血的人更多，而生活质量、体力活动和认知测试没测出差别。缺铁到贫血确实影响产热：10 名缺铁性贫血女性在 28 ℃ 水中泡 100 分钟后，直肠温度和耗氧量都低于对照组。","gain":"芬兰 Kuopio 队列 2862 名 42 至 60 岁男性、平均随访近 9 年：基线前 24 个月内献过血的 153 人中 1 人（0.7%）发生急性心梗，未献血的 2529 人中 316 人（12.5%）发生（两比例差异 P<0.0001），校正年龄与其他冠心病危险因素后相对风险 0.12（95% CI 0.02–0.86，P=0.035）——属观察性证据。北欧 SCANDAT 数据库 1,182,495 名献血者、9,526,627 人年随访中 15,401 人死亡：仅校正人口学特征时每年多献一次血死亡率下降 18.6%（95% CI 16.8%–20.4%），再校正内部健康献血者效应后降幅只剩 7.5%（5.7%–9.4%），作者结论为「不能解释为有益健康的确凿证据」。FeAST 随机对照试验：1277 名症状性下肢动脉疾病患者随机分为每 6 个月定期放血减铁组与对照组，主要终点全因死亡 125/636（20%）对 148/641（23%），HR 0.85（95% CI 0.67–1.08，P=0.17），死亡加非致死性心梗与卒中 180（28%）对 205（32%），HR 0.88（0.72–1.07，P=0.20）。INTERVAL 随机试验 45,263 名全血献血者（男性 12/10/8 周、女性 16/14/12 周三种间隔）：缩短间隔两年内采血量显著增加（男性 8 周组比 12 周组多 1.69 单位，95% CI 1.59–1.80），生活质量、体力活动、认知功能各组无显著差异，但献血相关症状（乏力、气短、眩晕、头晕、不宁腿）更多、血红蛋白与铁蛋白平均值更低、因血红蛋白低被推迟的次数更多（各项 P<0.0001）。缺铁与产热：10 名缺铁性贫血女性、8 名铁储备耗竭未贫血者与 12 名对照女性在 28 ℃ 水浴 100 分钟后，贫血组直肠温度 36.0±0.2 ℃ 对照组 36.2±0.1 ℃（P=0.001），耗氧量 5.28±0.26 对 5.99±0.29 mL·min⁻¹·kg⁻¹（P=0.04），甲状腺素与三碘甲状腺原氨酸也更低（P<0.002）。看起来成立，是因为献血者是被反复筛过的健康人群，而「放掉铁就能护心」的假说在随机试验里没验出来","grade":"A","src":"Salonen JT, Tuomainen TP, Salonen R, Lakka TA, Nyyssönen K (1998). Donation of blood is associated with reduced risk of myocardial infarction. The Kuopio Ischaemic Heart Disease Risk Factor Study. American Journal of Epidemiology, 148(5), 445-451. <https://doi.org/10.1093/oxfordjournals.aje.a009669>；Ullum H, Rostgaard K, Kamper-Jørgensen M, et al. (2015). Blood donation and blood donor mortality after adjustment for a healthy donor effect. Transfusion, 55(10), 2479-2485. <https://doi.org/10.1111/trf.13205>；Zacharski LR, Chow BK, Howes PS, et al. (2007). Reduction of iron stores and cardiovascular outcomes in patients with peripheral arterial disease: a randomized controlled trial. JAMA, 297(6), 603-610. <https://doi.org/10.1001/jama.297.6.603>；Di Angelantonio E, Thompson SG, Kaptoge S, et al. (2017). Efficiency and safety of varying the frequency of whole blood donation (INTERVAL): a randomised trial of 45 000 donors. Lancet, 390(10110), 2360-2371. <https://doi.org/10.1016/S0140-6736(17)31928-1>；Beard JL, Borel MJ, Derr J (1990). Impaired thermoregulation and thyroid function in iron-deficiency anemia. American Journal of Clinical Nutrition, 52(5), 813-819. <https://doi.org/10.1093/ajcn/52.5.813>；全国人大常委会 (1997). 中华人民共和国献血法（第二、九、十四条）. <https://flk.npc.gov.cn/detail?id=2c909fdd678bf17901678bf5e71801f9>；国家卫生健康委等 (2024-01-08). 关于进一步做好无偿献血者激励奖励工作的通知. <https://www.gov.cn/zhengce/zhengceku/202401/content_6924875.htm>","note":"这条否掉的是「为了自己的身体去献血」，不是献血本身。血是给别人的，按本书的受益人分档落在第④档（陌生人），能回到自己这边的是制度给的那一份：《献血法》第十四条规定无偿献血者本人临床用血免交采集、储存、分离、检验的费用，配偶和直系亲属可按省级政府规定免交或减交；国家卫健委 2024 年 1 月的通知写明 28 个省份已实现无偿献血者及其亲属省内医院用血费用出院直接减免，获无偿献血奉献奖的人可按当地「三免」政策免费乘公共交通、免费游政府投资主办的公园、免交公立医院普通门诊诊察费。要献就按法定间隔来：《献血法》第九条规定每次一般 200 毫升、最多不超过 400 毫升，两次间隔不少于 6 个月，提倡的年龄是 18 至 55 周岁；别为了凑荣誉或团体指标压到最短间隔。女性、体重偏低、月经量多的人铁本来就紧，反复献的人可以自费查一次铁蛋白；献完出现持续乏力、怕冷、晚上躺下腿里难受得忍不住要动（不宁腿），别当成「元气伤了」猜，去查血常规和铁蛋白，缺铁就按医嘱补铁并把间隔拉长。怕冷那一段的人体证据只有 10 人的小样本，放在这里是给机制，不是给发生率","money":"0","time":"中","will":"些","level":"小","lens":"死亡率","dispute":false,"todo":false,"ratio":"一般"},{"id":"6.18","sec":6,"n":18,"title":"不要靠通用体检套餐防病，按年龄性别做那几项有证据的筛查","cost":"0 元，省下每年几百到几千元的套餐费；换来的义务是自己记住该做哪几项、各隔多久","human":"把 23 万人分成「定期做通用健康检查」和「不做」两组，11 项试验合起来看，两组的死亡率一样，差别落在 3% 以内，心血管死亡和癌症死亡也一样。Cochrane 作者给的结论就一句：不大可能有益。真正降低死亡率的是有明确指征的那几项——量血压、超重的人 35 岁后查空腹血糖、查乙肝、女性的宫颈癌和乳腺癌筛查、45 到 50 岁起查结直肠癌、重度吸烟者的低剂量 CT，书里各有一条，间隔也写在那里。而 35 岁以上每年免费测一次血压、65 岁以上每年一次免费体检，本来就是国家基本公共卫生服务项目给的。","gain":"Cochrane 系统综述 2019 年更新版纳入 17 项随机对照试验，其中总死亡率合并 11 项试验、233,298 名参与者、21,535 例死亡，通用健康检查组对照组 RR 1.00（95% CI 0.97–1.03）；心血管死亡率 9 项试验、170,227 人、6,237 例死亡，RR 1.05（95% CI 0.94–1.16）；癌症死亡率 8 项试验、139,290 人、3,663 例死亡，RR 1.01（95% CI 0.92–1.12）；作者结论为「通用健康检查不大可能有益」。国家基本公共卫生服务项目为 35 岁及以上常住居民每年免费测量一次血压，为 65 岁及以上老年人每年免费提供一次健康体检，内容含体格检查、血常规、尿常规、肝功能（谷草转氨酶、谷丙转氨酶、总胆红素）、肾功能（血清肌酐、血尿素）、空腹血糖、血脂（总胆固醇、甘油三酯、低密度脂蛋白胆固醇、高密度脂蛋白胆固醇）、心电图和腹部 B 超（肝胆胰脾）（全国）","grade":"A","src":"Krogsbøll LT, Jørgensen KJ, Gøtzsche PC (2019). General health checks in adults for reducing morbidity and mortality from disease. Cochrane Database of Systematic Reviews, 1, CD009009. <https://doi.org/10.1002/14651858.CD009009.pub3>；国家卫生计生委 (2017). 国家基本公共卫生服务规范（第三版）（老年人健康管理服务、高血压患者健康管理服务）. <https://www.nhc.gov.cn/ewebeditor/uploadfile/2017/04/20170417104506514.pdf>","note":"这条否掉的是「拿年度套餐当防病手段」，不是「所有检查都别做」——有指征的筛查该做，见第 1 节第 7、8、14、17、18、19、23、24、29 条（血压、血糖、乙肝、乳腺、宫颈、结直肠、幽门螺杆菌、低剂量 CT、有过高危行为就去查），各自的起始年龄和间隔写在那里。单位组织、别人付钱的体检照去，这条针对的是自费买套餐和自己加项。已经有慢性病、有症状，或者医生按病情开的检查不在此列，那是诊疗不是筛查。套餐里最常见的无证据项目是肿瘤标志物和全身影像，见本节第 7 条；查出无症状的尿酸高、胆囊结石怎么办见下面两条。Cochrane 纳入的试验多在高收入国家、基线医疗可及性较好，医疗资源可及性差的地区不宜直接照搬这个结论。","money":"0","time":"少","will":"否","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"6.19","sec":6,"n":19,"title":"不要因为体检查出尿酸高、但从没痛过，就开始吃降尿酸药","cost":"0 元，省下的是长期药费、定期复查和一次不必要的用药风险","human":"血尿酸超标、但从来没发作过痛风、也没长痛风石的人，吃降尿酸药买的主要是心安：按美国风湿病学会算的账，24 个人吃满 3 年才拦得住一次痛风发作。想靠它护肾也落空了：两项随机试验分别在慢性肾病和 1 型糖尿病人群里用别嘌醇试过，肾功能下降的速度和吃安慰剂没有差别，其中一项里吃药那组尿蛋白反而多出四成。真正该做的是把体重、酒和含糖饮料管起来，把尿酸记进体检趋势线，等真发作过了再正经开始治。","gain":"美国风湿病学会 2020 年痛风指南对无症状高尿酸血症（血尿酸 >6.8 mg/dL 且无既往痛风发作、无皮下痛风石）有条件推荐不启动任何降尿酸药物（别嘌醇、非布司他、丙磺舒），证据确定性评为「高」，表下脚注写明「按归因风险计算，需治疗 24 名患者 3 年才能预防一次痛风发作」。CKD-FIX 随机对照试验（363 名 3 或 4 期慢性肾病、无痛风史且有进展风险者，别嘌醇 100–300 mg/日对安慰剂，104 周）：eGFR 年变化 -3.33（95% CI -4.11 到 -2.55）对 -3.23（-3.98 到 -2.47）mL/min/1.73 m²，组间差 -0.10（-1.18 到 0.97），P=0.85；严重不良事件 46% 对 44%。PERL 随机对照试验（530 名 1 型糖尿病合并早中期糖尿病肾病者，3 年加 2 个月洗脱）：别嘌醇把血尿酸从 6.1 降到 3.9 mg/dL，但洗脱后两组 GFR 差 0.001 mL/min/1.73 m²（95% CI -1.9 到 1.9），P=0.99，尿白蛋白排泄率在别嘌醇组反而高 40%（0 到 80）。看起来划算是因为「指标超标就该吃药压下去」的直觉","grade":"A","src":"FitzGerald JD, Dalbeth N, Mikuls T, et al. (2020). 2020 American College of Rheumatology Guideline for the Management of Gout. Arthritis Care & Research, 72(6), 744-760（表 1 及其脚注）. <https://doi.org/10.1002/acr.24180>；Badve SV, Pascoe EM, Tiku A, et al. (2020). Effects of Allopurinol on the Progression of Chronic Kidney Disease. New England Journal of Medicine, 382(26), 2504-2513. <https://doi.org/10.1056/NEJMoa1915833>；Doria A, Galecki AT, Spino C, et al. (2020). Serum Urate Lowering with Allopurinol and Kidney Function in Type 1 Diabetes. New England Journal of Medicine, 382(26), 2493-2503. <https://doi.org/10.1056/NEJMoa1916624>","note":"这条否掉的是「没发作过就开始终身吃降尿酸药」，不是「尿酸高无所谓」。同一份指南列了例外，有条件推荐启动：第一次发作并且合并 3 期及以上慢性肾病、血尿酸 >9 mg/dL（约 535 µmol/L）、或有尿路结石。已经发作过、有痛风石、有影像学骨破坏的人该吃药，见第 16 节第 9 条。汉族携带 HLA-B\\*5801 的比例是 7.4%，白人只有 0.7%，亚裔用别嘌醇发生超敏综合征的风险是白人的 3 倍——本来可以先不吃的药，没必要多冒这一次风险。两项肾脏试验的人群是慢性肾病和 1 型糖尿病患者，不能直接外推成「高尿酸对肾完全无害」，它们否掉的是「吃药降尿酸能护肾」这个做法","money":"0","time":"少","will":"否","level":"小","lens":"死亡率","dispute":false,"todo":false,"ratio":"一般"},{"id":"6.20","sec":6,"n":20,"title":"不要因为体检查出胆囊结石、但从没疼过，就去预防性切胆囊","cost":"0 元，省下一次全麻手术和住院；换来的义务是记住哪几个信号一出现就得就医","human":"胆囊里有石头、但从没疼过的人，绝大多数一直不会疼。意大利一个一万一千多人的普查队列里，580 个无症状带石者随访近九年，78% 一直没症状；美国一组 135 个无症状带石者随访约四年，10% 出现症状、7% 做了手术，同一批 691 人里 50 例死亡只有 2 例和胆道有关，而且都发生在本来就有症状的人身上。英国的诊疗指南写得很直接：胆囊和胆管都正常的无症状胆囊结石，不出症状就不需要治疗。同一个队列里，实际做掉的胆囊切除有 41% 做在无症状的人身上。","gain":"意大利 MICOL 人群队列（11,229 名 29 至 69 岁者超声普查，856 人有胆结石，其中 580 人无症状，平均随访 8.7 年）：无症状者中 453 人（78.1%）保持无症状，61 人（10.5%）出现轻症状，66 人（11.4%）出现重症状；随访期内 189 例胆囊切除中 41.3% 做在无症状患者身上；作者结论为「期待治疗对多数患者仍是有效的处理方式」。美国 HMO 队列（691 名确诊胆结石者，平均随访 78±61.6 个月）：135 名无症状者随访 58±50.2 个月（中位 46.3 个月）后仅 10% 出现胆石症状、7% 接受手术；全组 50 例死亡中仅 2 例与胆道相关，且均在有症状组；作者结论为「有无声结石的患者不需要在出现症状前手术」。NICE 指南 CG188 第 1.2.1 条：「对胆囊和胆道均正常、偶然发现无症状胆囊结石的人，应告知其在出现症状前不需要治疗」。看起来划算是因为「早晚要疼，不如趁年轻一次切了」的直觉","grade":"A","src":"Festi D, Reggiani ML, Attili AF, et al. (2010). Natural history of gallstone disease: Expectant management or active treatment? Results from a population-based cohort study. Journal of Gastroenterology and Hepatology, 25(4), 719-724. <https://doi.org/10.1111/j.1440-1746.2009.06146.x>；McSherry CK, Ferstenberg H, Calhoun WF, Lahman E, Virshup M (1985). The natural history of diagnosed gallstone disease in symptomatic and asymptomatic patients. Annals of Surgery, 202(1), 59-63. <https://doi.org/10.1097/00000658-198507000-00009>；National Institute for Health and Care Excellence (2014). Gallstone disease: diagnosis and management. NICE guideline CG188，第 1.2.1、1.3.1 条. <https://www.nice.org.uk/guidance/cg188/chapter/Recommendations>","note":"本条只管一种情形——石头在胆囊里、而且从没疼过。**胆总管里的石头是另一回事**：同一份指南第 1.3.1 条明确，胆总管结石无论有没有症状都要清除胆管并切除胆囊。出现右上腹或上腹持续绞痛、发热寒战、眼白或皮肤发黄、小便颜色变深，都要当天就医，别拿这一条硬扛。医生看过影像后建议手术时，问清楚是基于哪一条理由（比如胆管受累、合并息肉、胆囊壁的异常），别拿本条去反驳——这条挡的是「没有任何理由、只因为查出石头就切」。两项队列都是观察性研究，但看的是自然史而不是疗效，用在这里合适；它们的随访是 4 到 9 年，更长的年限里比例会往上走","money":"0","time":"少","will":"否","level":"中","lens":"死亡率","dispute":false,"todo":false,"ratio":"高"},{"id":"6.21","sec":6,"n":21,"title":"不要为了防肾结石把钙戒掉","cost":"0 元，反而不用为「哪些东西含钙」提心吊胆","human":"得了草酸钙结石的人常被劝少吃钙，但随机试验的结论是反的。120 个反复长草酸钙结石、尿钙又偏高的男性分成两组，一组正常吃钙同时少吃动物蛋白和盐，一组吃传统的低钙饮食，五年后复发的是 12 人对 23 人，正常吃钙那组的复发风险只有低钙组的一半。低钙那组尿里的草酸反而升了，正常钙那组降了——试验里低钙那组的尿草酸确实升上去了，正常钙那组降下来了。英国的指南也写明不要限制钙，成人维持每天 700 到 1200 毫克。","gain":"5 年随机对照试验：120 名复发性草酸钙结石合并特发性高钙尿男性，随机分为「正常钙（30 mmol/日）+ 低动物蛋白（52 g/日）+ 低盐（50 mmol 氯化钠/日）」组与传统低钙（10 mmol/日）组，5 年复发 12/60 对 23/60，未校正相对风险 0.49（95% CI 0.24–0.98），P=0.04；随访中两组尿钙均下降约 170 mg/日，但尿草酸排泄在低钙组平均上升 5.4 mg/日、在正常钙组平均下降 7.2 mg/日。NICE 指南 NG118 第 1.8.1 条：不限制每日钙摄入，成人维持 700 到 1,200 mg/日、儿童青少年按年龄 350 到 1,000 mg/日。看起来划算是因为「结石是钙做的，那就少吃钙」的直觉","grade":"A","src":"Borghi L, Schianchi T, Meschi T, et al. (2002). Comparison of two diets for the prevention of recurrent stones in idiopathic hypercalciuria. New England Journal of Medicine, 346(2), 77-84. <https://doi.org/10.1056/NEJMoa010369>；National Institute for Health and Care Excellence (2019). Renal and ureteric stones: assessment and management. NICE guideline NG118，第 1.8.1 条. <https://www.nice.org.uk/guidance/ng118/chapter/Recommendations>","note":"争议——该试验只做在男性、复发性草酸钙结石合并高钙尿的人群里，不能直接外推到所有结石类型；而且试验组同时改了三样（正常钙、少动物蛋白、少盐），不能把全部好处记在「不戒钙」一件事上，低盐和少动物蛋白同样在起作用。这条否掉的是「主动把含钙的东西戒掉」，不是「该多补钙」：改的是一日三餐里的钙，钙补充剂是另一回事，有结石史的人要不要吃补充剂问主治医生。多喝水那条见第 16 节第 8 条（肾结石后把水喝到每天 2.5–3 升）","money":"0","time":"少","will":"否","level":"大","lens":"死亡率","dispute":true,"todo":false,"ratio":"极高"},{"id":"6.22","sec":6,"n":22,"title":"不要为了「转运」「招财」「养人」买水晶、手串、貔貅这类物件","cost":"0 元；只是不把「转运」「养人」算进买它的理由","human":"「戴了能改运、能招财、能养人」这类说法没有任何可核查的证据，和算命显得准是同一个机制：说法足够笼统，你会自己往身上套。真有商家把话说到功效上，那是明文禁止的虚假宣传——市场监管总局 2026 年公布的典型案例里，就有直播间假称商品能「防治风湿病、提高免疫力、改善睡眠质量、疏通血管」，还虚构剧本演给你看，被按虚假宣传查处。当装饰品买、喜欢就戴，没问题；为了改运而加预算、成串成套地买，是这条要拦的。","gain":"经典课堂实验显示，人人拿到同一份笼统的「个人分析」却普遍认为很准（巴纳姆效应），这解释了「戴了之后确实顺了」的体验从哪来，作者的结论是「被本人接受不能证明解释正确」。官方案例：市场监管总局 2026 年 6 月 4 日公布的传统工艺市场「打假清源」典型案例中，广东四会一珠宝店在直播间虚构商品材质，并假称商品具有「防治风湿病、提高免疫力、改善睡眠质量、疏通血管」等功效，通过虚构剧本演绎误导、欺骗消费者，违反反不正当竞争法第九条第一款（全国）","grade":"B","src":"Forer BR (1949). The fallacy of personal validation: A classroom demonstration of gullibility. Journal of Abnormal and Social Psychology. <https://doi.org/10.1037/h0059240>；国家市场监督管理总局 (2026). 市场监管总局公布一批传统工艺市场「打假清源」典型案例. <https://www.samr.gov.cn/xw/zj/art/2026/art_1529399cfe874b8780c4496eb0158020.html>","note":"口径是「没有可核查的功效和预测效度」，不评价任何信仰或习俗，也不针对送礼、纪念、传家这些用途。功效宣称和「转运」说法是两件事：前者有明文可依、能投诉，后者没有研究、也无从证伪，只能靠自己划预算。买之前先当它是普通饰品，问一句「如果它什么都不改变，这个价我还买吗」。材质和证书怎么查、把它当投资为什么不划算，见第 5 节第 32、33 条（手串名表按花掉的钱算、珠宝玉石认 CMA 报告）；花钱算命见本节第 15 条。","money":"0","time":"少","will":"些","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"一般"},{"id":"6.23","sec":6,"n":23,"title":"不要指望买东西改善心情或身份感","cost":"0 元；难的是心情差的时候不下单","human":"把钱和物质看得越重的人，主观幸福感平均越低——259 项独立样本的合并结果是这样，只是相关强度弱（r ≈ -0.19），而且相关不等于因果。同一批数据里，和「冒险的健康与消费行为」「负面的自我评价」的关联要强得多（r 在 -0.28 到 -0.44 之间）。另一组研究比较「买经历」和「买东西」：两次调查和随后的实验室实验里，为获得一段经历而花的钱，比买来一件物品让人更满意。所以心情差的时候，把预算挪到一次出门、一场演出、一顿和人一起吃的饭，比挪到购物车里更可能有用。","gain":"荟萃分析合并 259 项独立样本、753 个效应量：物质主义倾向与个人幸福感显著负相关，最常用的多维量表上 r = -0.19（校正后 ρ = -0.24），只测「重视金钱」的单一量表关联更弱（r = -0.08 到 -0.11）；按结局分，与冒险性健康和消费行为、负面自我评价的关联最强（r = -0.28 到 -0.44），与生活满意度、负性情绪最弱（r = -0.13 到 -0.15）；中介分析提示这种负向关联可能由心理需要满足不足来解释。另一项研究：两次面向不同人群的调查中，受访者报告为获得生活经历而做的消费比物质性消费更让自己快乐，随后的实验室实验中，回想一次经历型消费后的正性情绪也高于回想一次物质型消费（全国口径不适用，两项均为国外样本）","grade":"B","src":"Dittmar H, Bond R, Hurst M, Kasser T (2014). The relationship between materialism and personal well-being: A meta-analysis. Journal of Personality and Social Psychology, 107(5), 879-924. <https://doi.org/10.1037/a0037409>；Van Boven L, Gilovich T (2003). To do or to have? That is the question. Journal of Personality and Social Psychology, 85(6), 1193-1202. <https://doi.org/10.1037/0022-3514.85.6.1193>","note":"争议——纳入的研究以横断面相关为主，作者自己在结论里说需要更多实验、纵向和发展研究来看清方向，所以不能读成「买东西会让人不快乐」，只能读成「靠买东西来变快乐，指望不大」。效应量弱：r = -0.19 大致只解释了几个百分点的差异，个体差别很大。两项研究都是国外样本，中国人群没有可引的同类数据。这条不反对为喜欢的东西花钱，反对的是把购物当成情绪调节手段——那会让下一次心情差时的默认动作还是下单。省钱的具体动作见第 5 节，情绪差时真正有证据的做法见第 22 节后半节和第 29 节，为「比别人强一档」而加的预算见本节第 24 条。","money":"0","time":"少","will":"是","level":"中","lens":"金钱","dispute":true,"todo":false,"ratio":"一般"},{"id":"6.24","sec":6,"n":24,"title":"不要为了「在周围人里往上挪一档」多花钱换房、换车、换圈子","cost":"0 元；只是在加预算之前多问一句「这笔加价买的是东西本身，还是我在这群人里的位置」","human":"控制住自己的收入之后，邻居挣得越多，人报告的幸福感越低；而且「邻居多挣一点」和「自己少挣同样一点」，对幸福感的打击是一个量级。这个效应只出现在和自己学历相同的邻居之间，对学历不同的邻居基本没反应，也只出现在常和邻居来往的人身上——说明它是「和同类人比」，不是「住在贵地方本身不好」。所以为了搬进一个人人都比你宽裕的地方而加的那笔预算，买到的是把自己在参照系里往下挪一档。同一份数据也显示，自己和邻居的收入一起涨，人还是觉得更好过——绝对水平仍然算数，这条要拦的只是为「相对位置」多付的那部分。","gain":"美国全国家庭与住户调查（NSFH）两轮面板数据，与按 1990 年人口普查 5% 微观样本推算的本地（PUMA）平均收入匹配：控制本人收入与一系列个人特征后，邻居收入越高，自报幸福感越低，效应大、稳健且高度显著；作者的表述是「邻居收入上升」与「本人收入下降同样幅度」导致的幸福感下降处于同一数量级。加个体固定效应后系数方向不变、量级相近（显著性降至 10% 水平），加州与调查轮次的固定效应后基本不变，说明不是由「爱搬去穷地方的人本来就更快乐」或州一级的遗漏变量造成；效应在常与邻居来往的人身上更强，在只与社区外朋友来往的人身上不显著，租房者与自有住房者没有差异（不支持「贵地方房价高所以实际收入低」的解释）；幸福感只随学历相同的邻居的收入下降，对学历不同的邻居的收入几乎无反应，且主要通过「对自己物质处境的满意度」传导，而不是对家庭生活等其他方面的满意度；若本人与邻居收入同比例上升，幸福感仍上升","grade":"B","src":"Luttmer EFP (2005). Neighbors as Negatives: Relative Earnings and Well-Being. The Quarterly Journal of Economics, 120(3), 963–1002. <https://doi.org/10.1093/qje/120.3.963>；Luttmer EFP (2004). Neighbors as Negatives: Relative Earnings and Well-Being. NBER Working Paper No. 10667（本条引用的表述与数量级按这一版逐字核对）. <https://www.nber.org/papers/w10667>","note":"B 的理由：观察性面板数据、单一研究、国外样本，结局是自报幸福感而不是钱；作者虽用个体固定效应和州×轮次固定效应排掉了几类混杂，但仍不是随机试验，中国人群没有可引的同类数据。收益量级定「中」是沿用本节第 23 条（别指望买东西改善心情）的口径：省下的钱确实可能是万元级，但「省下就换来多少幸福感」没有数字支撑，不按万元级记「大」。这条不反对为更大的房子、更安静的小区、更短的通勤花钱——那些是东西本身；要拦的是「同事都换了、我不能比他们差」这个理由。住处该按什么排序见第 4 节第 13 条，买东西调情绪见本节第 23 条（别指望买东西改善心情），网上往上比见第 3 节第 21 条（别把「别人过得怎么样」当每日必读）","money":"0","time":"少","will":"些","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"一般"}]}]
